-- ===== 最小化窗口彩虹光晕效果 =====
task.spawn(function()
    local miniFrame = nil
    for _ = 1, 120 do
        if Window.MiniWindow and Window.MiniWindow.Frame then
            miniFrame = Window.MiniWindow.Frame
            break
        end
        local screenGui = Window.UIElements and Window.UIElements.Main and Window.UIElements.Main:FindFirstAncestorOfClass("ScreenGui")
        if screenGui then
            for _, desc in pairs(screenGui:GetDescendants()) do
                if desc:IsA("Frame") and (desc.Name:lower():find("mini") or desc.Name:lower():find("minimize")) then
                    if desc.Visible and desc ~= Window.UIElements.Main then
                        miniFrame = desc
                        break
                    end
                end
            end
            if miniFrame then break end
        end
        task.wait(0.25)
    end

    if not miniFrame then return end

    for _, child in pairs(miniFrame:GetChildren()) do
        if child.Name == "MiniGlowContainer" or child.Name == "MiniTopGlow" or child.Name == "MiniBottomGlow" then
            child:Destroy()
        end
    end

    local glowContainer = Instance.new("Frame")
    glowContainer.Name = "MiniGlowContainer"
    glowContainer.Size = UDim2.new(1, 16, 1, 16)
    glowContainer.Position = UDim2.new(0, -8, 0, -8)
    glowContainer.BackgroundColor3 = Color3.new(1, 1, 1)
    glowContainer.BackgroundTransparency = 0
    glowContainer.BorderSizePixel = 0
    glowContainer.ZIndex = miniFrame.ZIndex - 1
    glowContainer.Parent = miniFrame

    local glowCorner = Instance.new("UICorner")
    glowCorner.CornerRadius = UDim.new(0, 14)
    glowCorner.Parent = glowContainer

    local glowGrad = Instance.new("UIGradient")
    glowGrad.Name = "MiniGlowGradient"
    glowGrad.Color = makeRainbowColorSequence(0, 1, 1, 8)
    glowGrad.Rotation = 0
    glowGrad.Parent = glowContainer

    local glowStroke = Instance.new("UIStroke")
    glowStroke.Name = "MiniGlowStroke"
    glowStroke.Thickness = 3
