-- ===== 头像框插入 =====
task.spawn(function()
    local main = Window.UIElements and Window.UIElements.Main
    if not main then return end

    local function createAvatarFrame()
        local frame = Instance.new("Frame")
        frame.Name = "WXHUBAvatarFrame"
        frame.BackgroundColor3 = Color3.fromRGB(8, 8, 14)
        frame.BackgroundTransparency = 0
        frame.Size = UDim2.new(1, -20, 0, 155)
        frame.BorderSizePixel = 0
        frame.ClipsDescendants = true

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 18)
        corner.Parent = frame

        local stroke = Instance.new("UIStroke")
        stroke.Thickness = 2.5
        stroke.Color = makeRainbowColor(0)
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = frame

        local avatarImg = Instance.new("ImageLabel")
        avatarImg.Name = "AvatarImage"
        avatarImg.Image = avatarThumbUrl
        avatarImg.BackgroundTransparency = 1
        avatarImg.Size = UDim2.new(0, 115, 0, 115)
        avatarImg.Position = UDim2.new(0.5, -57, 0.5, -57)
        avatarImg.Parent = frame

        local imgCorner = Instance.new("UICorner")
        imgCorner.CornerRadius = UDim.new(0, 12)
        imgCorner.Parent = avatarImg

        return frame
    end

    local function insertIntoScroller(scroller)
        if scroller and not scroller:FindFirstChild("WXHUBAvatarFrame") then
            local frame = createAvatarFrame()
            frame.Parent = scroller
            frame.ZIndex = 10
            return true
        end
        return false
    end

    local inserted = false
    for _ = 1, 60 do
        if AnnounceTab then
            local container = AnnounceTab.Content or AnnounceTab.Container or AnnounceTab.Frame or AnnounceTab.TabFrame or AnnounceTab.Instance
            if container and container:IsA("GuiObject") then
                local scroller = container:FindFirstChildOfClass("ScrollingFrame")
                if not scroller then
                    for _, child in pairs(container:GetDescendants()) do
                        if child:IsA("ScrollingFrame") then scroller = child break end
                    end
                end
                if insertIntoScroller(scroller) then inserted = true break end
            end
        end
        if not inserted then
            for _, scroll in pairs(main:GetDescendants()) do
                if scroll:IsA("ScrollingFrame") then
                    for _, child in pairs(scroll:GetDescendants()) do
                        if child:IsA("TextLabel") and (child.Text:find("玩家信息") or child.Text:find("作者信息")) then
                            if insertIntoScroller(scroll) then inserted = true break end
                        end
                    end
                end
                if inserted then break end
            end
        end
        if inserted then break end
        task.wait(0.3)
    end
end)

