            WindUI:Notify({ Title = "恢复", Content = "生命值已回满", Icon = "heart", Duration = 3 })
        end
    })
    GeneralTab:Space()
    GeneralTab:Button({
        Title = "传送到随机玩家",
        Color = makeRainbowColor(240),
        Justify = "Center",
        Icon = "shuffle",
        Callback = function()
            local allPlayers = Players:GetPlayers()
            if #allPlayers > 1 then
                local target
                repeat target = allPlayers[math.random(1, #allPlayers)] until target ~= LocalPlayer
                local char, tChar = LocalPlayer.Character, target.Character
                if char and tChar then
                    local root, tRoot = char:FindFirstChild("HumanoidRootPart"), tChar:FindFirstChild("HumanoidRootPart")
                    if root and tRoot then
                        root.CFrame = tRoot.CFrame + Vector3.new(0, 3, 0)
                        WindUI:Notify({ Title = "传送", Content = "已传送到: " .. target.Name, Icon = "map-pin", Duration = 3 })
                    end
                end
            else
                WindUI:Notify({ Title = "传送失败", Content = "服务器中没有其他玩家", Icon = "alert-triangle", Duration = 3 })
            end
        end
    })
    GeneralTab:Space()
    GeneralTab:Button({
        Title = "bs飞行",
        Color = makeRainbowColor(180),
        Justify = "Center",
        Icon = "plane",
        Callback = function()
            loadstring(game:HttpGet("https://pastebin.com/raw/Z6SX4xsj"))()
            WindUI:Notify({ Title = "bs飞行", Content = "飞行脚本已加载", Icon = "check", Duration = 3 })
        end
