                    -- 投掷按钮
                    local throwBtn = Instance.new("TextButton")
                    throwBtn.Size = UDim2.new(0, 80, 0, 80)
                    throwBtn.Position = UDim2.new(1, -90, 1, -120)
                    throwBtn.AnchorPoint = Vector2.new(0.5, 0.5)
                    throwBtn.BackgroundColor3 = Color3.fromRGB(255, 100, 100)
                    throwBtn.BackgroundTransparency = 0.4
                    throwBtn.Text = "投掷"
                    throwBtn.TextColor3 = Color3.new(1, 1, 1)
                    throwBtn.Font = Enum.Font.SourceSansBold
                    throwBtn.TextSize = 20
                    throwBtn.BorderSizePixel = 0
                    throwBtn.Parent = gui
                    throwBtn.MouseButton1Click:Connect(function() throwPart() end)
                    throwBtn.TouchTap:Connect(function() throwPart() end)

                    -- PC鼠标解锁
                    if not RUserInputService.TouchEnabled then
                        lockButton = Instance.new("TextButton")
                        lockButton.Size = UDim2.new(0, 100, 0, 35)
                        lockButton.Position = UDim2.new(1, -90, 1, -40)
                        lockButton.AnchorPoint = Vector2.new(0.5, 0.5)
                        lockButton.BackgroundColor3 = Color3.fromRGB(200, 200, 200)
                        lockButton.BackgroundTransparency = 0.4
                        lockButton.Text = "解锁鼠标"
                        lockButton.TextColor3 = Color3.new(1, 1, 1)
                        lockButton.Font = Enum.Font.SourceSansBold
                        lockButton.TextSize = 16
                        lockButton.BorderSizePixel = 0
                        lockButton.Parent = gui

                        if RUserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
                            lockButton.Text = "解锁鼠标"
                        else
                            lockButton.Text = "锁定鼠标"
                            mouseUnlocked = true
                        end

                        local function toggleMouseLock()
                            mouseUnlocked = not mouseUnlocked
                            if mouseUnlocked then
                                RUserInputService.MouseBehavior = Enum.MouseBehavior.Default
                                if mouseBlocker then
                                    mouseBlocker.Visible = true
                                    mouseBlocker.Modal = true
                                end
                                lockButton.Text = "锁定鼠标"
                            else
                                RUserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
                                if mouseBlocker then
                                    mouseBlocker.Visible = false
                                    mouseBlocker.Modal = false
                                end
                                lockButton.Text = "解锁鼠标"
                            end
                        end

                        lockButton.MouseButton1Click:Connect(toggleMouseLock)
                        lockButton.TouchTap:Connect(toggleMouseLock)

                        mouseBlocker = Instance.new("Frame")
                        mouseBlocker.Name = "MouseBlocker"
                        mouseBlocker.BackgroundTransparency = 1
                        mouseBlocker.Size = UDim2.fromScale(1, 1)
                        mouseBlocker.Position = UDim2.fromScale(0, 0)
                        mouseBlocker.ZIndex = 0
                        mouseBlocker.Visible = false
                        mouseBlocker.Modal = false
                        mouseBlocker.Parent = gui

                        _G.__toggleMouseLock = toggleMouseLock
                    end
                end

                local function createDeleteButton()
                    local gui = Instance.new("ScreenGui")
                    gui.Name = "DeleteButtonGUI"
                    gui.IgnoreGuiInset = true
                    gui.ResetOnSpawn = false
                    gui.DisplayOrder = UI_DISPLAY_ORDER
                    gui.Parent = tplayer:WaitForChild("PlayerGui")

                    local btn = Instance.new("TextButton")
                    btn.Size = UDim2.new(0, 60, 0, 30)
                    btn.AnchorPoint = Vector2.new(1, 1)
                    btn.Position = UDim2.new(1/8, 0, 1/8, 0)
                    btn.BackgroundColor3 = Color3.fromRGB(200, 50, 50)
                    btn.Text = "删除UI"
                    btn.TextColor3 = Color3.new(1, 1, 1)
                    btn.Font = Enum.Font.SourceSansBold
                    btn.TextSize = 14
                    btn.BorderSizePixel = 0
                    btn.Parent = gui
                    btn.MouseButton1Click:Connect(function() clearOldUI() end)
                    btn.TouchTap:Connect(function() clearOldUI() end)
                end

                -- ========== 高亮 ==========
                local function clearHighlight()
                    if highlight then highlight:Destroy() end
                    highlight = nil
                    highlightedPart = nil
                end

                local function setHighlight(part)
                    if highlightedPart == part then return end
                    clearHighlight()
                    if part then
                        highlight = Instance.new("Highlight")
                        highlight.Adornee = part
                        highlight.FillTransparency = 1
                        highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
                        highlight.OutlineTransparency = 0
                        highlight.Parent = part
                        highlightedPart = part
                    end
                end

                -- ========== 核心：收回身体完整流程（关闭碰撞→瞬移身体→等待→回准星→恢复碰撞） ==========
                local function retractPartAsync(part)
                    if not part or not part.Parent then return end
                    local character = tplayer.Character
                    if not character then return end
                    local root = character:FindFirstChild("HumanoidRootPart")
                    if not root then return end

                    task.spawn(function()
                        if holdingPart ~= part then return end

                        root.CanCollide = false
                        part.CanCollide = false

                        part.CFrame = root.CFrame

                        pcall(function()
                            part:SetNetworkOwner(tplayer)
                        end)

                        task.wait(0.1)

                        local targetCFrame = tcamera.CFrame * CFrame.new(0, 0, -GRAB_DISTANCE)
                        part.CFrame = targetCFrame

                        if root and root.Parent then
                            root.CanCollide = true
                        end
                        if part and part.Parent then
                            part.CanCollide = true
                        end
                    end)
                end

                -- ========== 释放 / 投掷 ==========
                local function releasePart()
                    if holdingPart then
                        holdingPart.CanCollide = true
                        holdingPart = nil
                    end
                    reclaiming = false
                end

                function grabHighlightedPart()
                    if not highlightedPart then return end
                    local character = tplayer.Character
                    if not character or not character:FindFirstChild("HumanoidRootPart") then return end

                    if holdingPart then return end

                    local part = highlightedPart
                    holdingPart = part
                    clearHighlight()
                    lastRefreshTime = tick()

                    if part:IsA("BasePart") then
                        originalTransparency = part.Transparency
                    else
                        originalTransparency = 0
                    end

                    retractPartAsync(part)
                    reclaiming = false
                end

                function throwPart()
                    if not holdingPart then return end
                    local part = holdingPart
                    holdingPart = nil

                    part.CanCollide = true
                    local direction = tcamera.CFrame.LookVector
                    part.Velocity = direction * THROW_FORCE
                    part.RotVelocity = Vector3.new(math.random(-5,5), math.random(-5,5), math.random(-5,5))
                    reclaiming = false
                end

                -- ========== 射线检测 ==========
                local function getCrosshairTarget()
                    local rayOrigin = tcamera.CFrame.Position
                    local rayDirection = tcamera.CFrame.LookVector * MAX_GRAB_DISTANCE
                    local raycastParams = RaycastParams.new()
                    raycastParams.FilterType = Enum.RaycastFilterType.Blacklist
                    raycastParams.FilterDescendantsInstances = {tplayer.Character}
                    local rayResult = RWorkspace:Raycast(rayOrigin, rayDirection, raycastParams)
                    if rayResult then
                        local part = rayResult.Instance
                        if part:IsA("BasePart") and not part.Anchored then
                            return part
                        end
                    end
                    return nil
                end

                -- ========== 键盘监听 ==========
                if not RUserInputService.TouchEnabled then
                    RUserInputService.InputBegan:Connect(function(input)
                        if input.KeyCode == GRAB_KEY then
                            grabHighlightedPart()
                        elseif input.KeyCode == THROW_KEY then
                            throwPart()
                        elseif input.KeyCode == TOGGLE_MOUSE_KEY then
                            if _G.__toggleMouseLock then
                                _G.__toggleMouseLock()
                            end
                        end
                    end)
                end

                -- ========== 每帧更新 ==========
                RRunService.Heartbeat:Connect(function()
                    if not holdingPart then
                        local target = getCrosshairTarget()
                        if target then
                            setHighlight(target)
                        else
                            clearHighlight()
                        end
                    else
                        clearHighlight()
                    end

                    if holdingPart and holdingPart.Parent then
                        local targetCFrame = tcamera.CFrame * CFrame.new(0, 0, -GRAB_DISTANCE)
                        holdingPart.CFrame = targetCFrame
                        holdingPart.CanCollide = false

                        if holdingPart:IsA("BasePart") then
                            holdingPart.Transparency = originalTransparency
                        end

                        if tick() - lastRefreshTime >= REFRESH_INTERVAL then
                            lastRefreshTime = tick()
                            retractPartAsync(holdingPart)
                        end

                        local currentOwner = nil
                        pcall(function()
                            currentOwner = holdingPart:GetNetworkOwner()
                        end)
                        if currentOwner and currentOwner ~= tplayer and not reclaiming then
                            reclaiming = true
                            task.spawn(function()
                                retractPartAsync(holdingPart)
                                reclaiming = false
                            end)
                        end
                    else
                        if holdingPart then
                            releasePart()
                        end
                    end

                    if mouseUnlocked and mouseBlocker then
                        if not mouseBlocker.Visible or not mouseBlocker.Modal then
                            mouseBlocker.Visible = true
                            mouseBlocker.Modal = true
                        end
                        if RUserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
                            RUserInputService.MouseBehavior = Enum.MouseBehavior.Default
                        end
                    end
                end)

                -- ========== 角色重生清理 ==========
                tplayer.CharacterAdded:Connect(function()
                    releasePart()
                    clearHighlight()
                end)

                -- ========== 初始化 ==========
                createCrosshair()
                createActionButtons()
                createDeleteButton()
            end)
        end
    })
end

