    -- ============================================================
-- 游戏脚本分区：最坚强战场（TSB，大文件，内含自动农场/自动格挡）
-- ============================================================
    ["最坚强战场"] = [==[
local Players=game:GetService("Players")
local RunService=game:GetService("RunService")
local UserInputService=game:GetService("UserInputService")
local TweenService=game:GetService("TweenService")
local HttpService=game:GetService("HttpService")
local Workspace=game:GetService("Workspace")
local VirtualInputManager=game:GetService("VirtualInputManager")
local cam=Workspace.CurrentCamera
local player=Players.LocalPlayer
local Teleport={Active=false,Target=nil,Connection=nil,PlayerList={},WallVision=false,OriginalTransparency={},HorizontalOrbitActive=false,HorizontalOrbitConnection=nil,OrbitRadius=10,HorizontalSpeed=2,HorizontalAngle=0,FlingLoopActive=false,FlingLoopConnection=nil,FlingInterval=0.5,LastFlingTime=0,TouchFlingActive=false,TouchFlingConnection=nil,PredictEnabled=false,PredictDelay=0.125,Mode="Follow"}
local CoordinateManager={SavedCoordinates={},FilePath="SavedCoordinates.json"}
local SupaTech={Enabled=false,IsExecuting=false,IsCooldown=false,CooldownEndTime=0,AnimId="10503381238",RagdollAnimId="10473655645",EndAnimId="180436148",NearbyRange=7,WaitBeforeAction=0.2875,TeleportDuration=0.6,VerticalOffset=2.5,TeleportOffset=0.2,UpwardAngle=50,FaceDistance=1.5,CooldownTime=5.0,RandomRadius=0.5}
local InvisData={enabled=false,char=nil,hum=nil,root=nil,parts={},connections={},heartbeatCon=nil,offset=Vector3.new(0,-200000,0)}
local NotificationSettings={Position="TopLeft",Width=300,Height=70,TextSize=18,PopSpeed=0.4,RetractSpeed=0.4,Duration=2.5}
local InvisHotkey=Enum.KeyCode.T
local function ReadFile(path)local success,result=pcall(function()if readfile then return readfile(path)elseif syn and syn.readfile then return syn.readfile(path)else return nil end end)return success and result or nil end
local function WriteFile(path,content)local success,result=pcall(function()if writefile then writefile(path,content)return true elseif syn and syn.writefile then syn.writefile(path,content)return true else return false end end)return success and result or false end
local function LoadCoordinates()local content=ReadFile(CoordinateManager.FilePath)if content then local success,data=pcall(function()return HttpService:JSONDecode(content)end)if success and type(data)=="table"then CoordinateManager.SavedCoordinates=data return true end end return false end
local function SaveCoordinates()local success=pcall(function()local json=HttpService:JSONEncode(CoordinateManager.SavedCoordinates)return WriteFile(CoordinateManager.FilePath,json)end)return success end
local function InitCoordinateManager()LoadCoordinates()end
local function ShowNotification(message,color,duration)color=color or Color3.fromRGB(0,150,255)duration=duration or NotificationSettings.Duration if _G.NotificationGui then _G.NotificationGui:Destroy()end local gui=Instance.new("ScreenGui")gui.Parent=player:WaitForChild("PlayerGui")gui.ResetOnSpawn=false gui.Name="CustomNotification"_G.NotificationGui=gui local container=Instance.new("Frame")container.Parent=gui container.Size=UDim2.new(1,0,1,0)container.BackgroundTransparency=1 container.ClipsDescendants=true local frame=Instance.new("Frame")frame.Parent=container frame.Size=UDim2.new(0,NotificationSettings.Width,0,NotificationSettings.Height)frame.BackgroundColor3=Color3.fromRGB(20,20,30)frame.BackgroundTransparency=0 local corner=Instance.new("UICorner")corner.Parent=frame corner.CornerRadius=UDim.new(0,8)local stroke=Instance.new("UIStroke")stroke.Parent=frame stroke.Color=color stroke.Thickness=2 local text=Instance.new("TextLabel")text.Parent=frame text.Size=UDim2.new(1,-20,1,-10)text.Position=UDim2.new(0,10,0,5)text.BackgroundTransparency=1 text.Text=message text.TextColor3=Color3.fromRGB(220,220,255)text.TextSize=NotificationSettings.TextSize text.Font=Enum.Font.Gotham text.TextWrapped=true text.TextXAlignment=Enum.TextXAlignment.Left text.TextYAlignment=Enum.TextYAlignment.Top local margin=10 local w=NotificationSettings.Width local h=NotificationSettings.Height local startPos,endPos if NotificationSettings.Position=="TopLeft"then startPos=UDim2.new(0,margin,0,-h-margin)endPos=UDim2.new(0,margin,0,margin)elseif NotificationSettings.Position=="TopRight"then startPos=UDim2.new(1,-w-margin,0,-h-margin)endPos=UDim2.new(1,-w-margin,0,margin)elseif NotificationSettings.Position=="BottomLeft"then startPos=UDim2.new(0,margin,1,margin)endPos=UDim2.new(0,margin,1,-h-margin)elseif NotificationSettings.Position=="BottomRight"then startPos=UDim2.new(1,-w-margin,1,margin)endPos=UDim2.new(1,-w-margin,1,-h-margin)else startPos=UDim2.new(0,margin,0,-h-margin)endPos=UDim2.new(0,margin,0,margin)end frame.Position=startPos local tweenIn=TweenService:Create(frame,TweenInfo.new(NotificationSettings.PopSpeed,Enum.EasingStyle.Quad,Enum.EasingDirection.In),{Position=endPos})tweenIn:Play()task.delay(duration,function()if not frame.Parent then return end local tweenOut=TweenService:Create(frame,TweenInfo.new(NotificationSettings.RetractSpeed,Enum.EasingStyle.Quad,Enum.EasingDirection.In),{Position=startPos})tweenOut:Play()tweenOut.Completed:Connect(function()gui:Destroy()_G.NotificationGui=nil end)end)end
local function hsvToRgb(h,s,v)local r,g,b local i=math.floor(h/60)%6 local f=(h/60)-math.floor(h/60)local p=v*(1-s)local q=v*(1-f*s)local t=v*(1-(1-f)*s)if i==0 then r,g,b=v,t,p elseif i==1 then r,g,b=q,v,p elseif i==2 then r,g,b=p,v,t elseif i==3 then r,g,b=p,q,v elseif i==4 then r,g,b=t,p,v else r,g,b=v,p,q end return Color3.new(r,g,b)end
local function makeRainbowColor(timeOffset,saturation,value)saturation=saturation or 1 value=value or 1 local speed=60 local hue=(tick()*speed+(timeOffset or 0))%360 return hsvToRgb(hue,saturation,value)end
local function makeRainbowColorSequence(timeOffset,saturation,value,count)saturation=saturation or 1 value=value or 1 count=count or 6 local speed=60 local hueOffset=(tick()*speed+(timeOffset or 0))%360 local keypoints={}for i=0,count-1 do local hue=(hueOffset+(i/count)*360)%360 local c=hsvToRgb(hue,saturation,value)local t=i/(count-1)keypoints[i+1]=ColorSequenceKeypoint.new(t,c)end return ColorSequence.new(keypoints)end
local _rainbowGrads={}local _rbConn=nil local function startRainbow()if _rbConn then return end _rbConn=RunService.Heartbeat:Connect(function()local t=tick()*60 for _,g in ipairs(_rainbowGrads)do if g and g.Parent then if g:IsA("UIGradient")then g.Color=makeRainbowColorSequence(t,1,1,6)elseif g:IsA("UIStroke")then g.Color=makeRainbowColor(t,1,1)end end end end)end
