local function CreateButton(name,yPosition,hasIndicator)local Button=Instance.new("TextButton")Button.Name=name Button.Size=UDim2.new(1,0,0,30)Button.Position=UDim2.new(0,0,0,yPosition)Button.BackgroundColor3=Color3.fromRGB(40,40,60)Button.BackgroundTransparency=0.225 Button.TextColor3=Color3.fromRGB(220,220,255)Button.Text=name Button.TextSize=10 Button.Font=Enum.Font.Gotham Button.Parent=Content local ButtonCorner=Instance.new("UICorner")ButtonCorner.Parent=Button ButtonCorner.CornerRadius=UDim.new(0,6)local ButtonStroke=Instance.new("UIStroke")ButtonStroke.Parent=Button ButtonStroke.Color=Color3.fromRGB(255,255,255)ButtonStroke.Thickness=1.2 local ButtonStrokeGrad=Instance.new("UIGradient")ButtonStrokeGrad.Color=makeRainbowColorSequence(0,1,1,6)ButtonStrokeGrad.Rotation=0 ButtonStrokeGrad.Parent=ButtonStroke table.insert(_rainbowGrads,ButtonStrokeGrad)if hasIndicator then local Indicator=Instance.new("Frame")Indicator.Name="Indicator"Indicator.Size=UDim2.new(0,6,0,6)Indicator.Position=UDim2.new(1,-10,0.5,-3)Indicator.BackgroundColor3=Color3.fromRGB(255,50,50)Indicator.BorderSizePixel=0 Indicator.Parent=Button local IndicatorCorner=Instance.new("UICorner")IndicatorCorner.Parent=Indicator IndicatorCorner.CornerRadius=UDim.new(1,0)end return Button end
local function CreateInputControl(label,yPosition,defaultValue,minValue,maxValue)local ControlFrame=Instance.new("Frame")ControlFrame.Size=UDim2.new(1,0,0,25)ControlFrame.Position=UDim2.new(0,0,0,yPosition)ControlFrame.BackgroundTransparency=1 ControlFrame.Parent=Content local Label=Instance.new("TextLabel")Label.Size=UDim2.new(0.4,0,1,0)Label.Position=UDim2.new(0,0,0,0)Label.BackgroundTransparency=1 Label.Text=label Label.TextColor3=Color3.fromRGB(180,200,255)Label.TextSize=9 Label.Font=Enum.Font.Gotham Label.TextXAlignment=Enum.TextXAlignment.Left Label.Parent=ControlFrame local ValueBox=Instance.new("TextButton")ValueBox.Size=UDim2.new(0.6,0,1,0)ValueBox.Position=UDim2.new(0.4,0,0,0)ValueBox.BackgroundColor3=Color3.fromRGB(40,40,60)ValueBox.Text=tostring(defaultValue)ValueBox.TextColor3=Color3.fromRGB(0,200,255)ValueBox.TextSize=9 ValueBox.Font=Enum.Font.Gotham ValueBox.Parent=ControlFrame local ValueCorner=Instance.new("UICorner")ValueCorner.Parent=ValueBox ValueCorner.CornerRadius=UDim.new(0,4)local ValueStroke=Instance.new("UIStroke")ValueStroke.Parent=ValueBox ValueStroke.Color=Color3.fromRGB(255,255,255)ValueStroke.Thickness=1 local ValueStrokeGrad=Instance.new("UIGradient")ValueStrokeGrad.Color=makeRainbowColorSequence(0,1,1,6)ValueStrokeGrad.Rotation=0 ValueStrokeGrad.Parent=ValueStroke table.insert(_rainbowGrads,ValueStrokeGrad)return{Frame=ControlFrame,Box=ValueBox,Value=defaultValue,Min=minValue,Max=maxValue}end
local function UpdateToggleButton(button,isActive,activeText,inactiveText)if not button then return end button.Text=isActive and(activeText or"开启")or(inactiveText or"关闭")local indicator=button:FindFirstChild("Indicator")if indicator then indicator.BackgroundColor3=isActive and Color3.fromRGB(50,255,50)or Color3.fromRGB(255,50,50)end button.BackgroundColor3=isActive and Color3.fromRGB(40,80,40)or Color3.fromRGB(60,40,40)end
