onfirmButton.Text="确认"ConfirmButton.TextColor3=Color3.fromRGB(220,220,255)ConfirmButton.TextSize=12 ConfirmButton.Font=Enum.Font.Gotham local ConfirmCorner=Instance.new("UICorner")ConfirmCorner.Parent=ConfirmButton ConfirmCorner.CornerRadius=UDim.new(0,5)local CancelButton=Instance.new("TextButton")CancelButton.Parent=PopupFrame CancelButton.Size=UDim2.new(0,70,0,25)CancelButton.Position=UDim2.new(0.5,10,1,-40)CancelButton.BackgroundColor3=Color3.fromRGB(120,40,40)CancelButton.Text="取消"CancelButton.TextColor3=Color3.fromRGB(220,220,255)CancelButton.TextSize=12 CancelButton.Font=Enum.Font.Gotham local CancelCorner=Instance.new("UICorner")CancelCorner.Parent=CancelButton CancelCorner.CornerRadius=UDim.new(0,5)ConfirmButton.MouseButton1Click:Connect(function()local inputText=InputBox.Text local numberValue=tonumber(inputText)if numberValue then if numberValue<minValue then numberValue=minValue elseif numberValue>maxValue then numberValue=maxValue end callback(numberValue)end PopupGui:Destroy()end)CancelButton.MouseButton1Click:Connect(function()PopupGui:Destroy()end)InputBox.FocusLost:Connect(function(enterPressed)if enterPressed then local inputText=InputBox.Text local numberValue=tonumber(inputText)if numberValue then if numberValue<minValue then numberValue=minValue elseif numberValue>maxValue then numberValue=maxValue end callback(numberValue)end PopupGui:Destroy()end end)end
