local PosY=847 local PosButtonSize=38 local PosButtons={}local positions={"左上","右上","左下","右下"}local posMap={["左上"]="TopLeft",["右上"]="TopRight",["左下"]="BottomLeft",["右下"]="BottomRight"}for i,posName in ipairs(positions)do local btn=Instance.new("TextButton")btn.Name="Pos"..posName btn.Size=UDim2.new(0,PosButtonSize,0,22)btn.Position=UDim2.new((i-1)*0.25,0,0,PosY)btn.BackgroundColor3=Color3.fromRGB(40,40,60)btn.BackgroundTransparency=0.2 btn.Text=posName btn.TextColor3=Color3.fromRGB(220,220,255)btn.TextSize=9 btn.Font=Enum.Font.Gotham btn.Parent=Content local btnCorner=Instance.new("UICorner")btnCorner.Parent=btn btnCorner.CornerRadius=UDim.new(0,4)local btnStroke=Instance.new("UIStroke")btnStroke.Parent=btn btnStroke.Color=Color3.fromRGB(255,255,255)btnStroke.Thickness=1 local btnStrokeGrad=Instance.new("UIGradient")btnStrokeGrad.Color=makeRainbowColorSequence(i*45,1,1,6)btnStrokeGrad.Rotation=0 btnStrokeGrad.Parent=btnStroke table.insert(_rainbowGrads,btnStrokeGrad)local highlight=Instance.new("UIStroke")highlight.Name="Highlight"highlight.Parent=btn highlight.Color=Color3.fromRGB(255,200,100)highlight.Thickness=2 highlight.Transparency=1 PosButtons[posName]=btn btn.MouseButton1Click:Connect(function()NotificationSettings.Position=posMap[posName]for _,b in pairs(PosButtons)do local hl=b:FindFirstChild("Highlight")if hl then hl.Transparency=1 end end local hl=btn:FindFirstChild("Highlight")if hl then hl.Transparency=0 end ShowNotification("通知位置已切换至: "..posName,Color3.fromRGB(255,200,100),1.5)end)end
