local CameraLock={Enabled=false,Connection=nil}
local function ToggleCameraLock()
if CameraLock.Enabled then
CameraLock.Enabled=false
if CameraLock.Connection then CameraLock.Connection:Disconnect() CameraLock.Connection=nil end
local myChar=player.Character
if myChar then local myHumanoid=myChar:FindFirstChildOfClass("Humanoid") if myHumanoid then myHumanoid.AutoRotate=true end end
UpdateToggleButton(CameraLockButton,false,"自瞄锁定:开启","自瞄锁定:关闭")
ShowNotification("自瞄已关闭",Color3.fromRGB(255,100,0))
else
if not Teleport.Target then ShowNotification("请先选择目标玩家",Color3.fromRGB(255,50,50)) return end
CameraLock.Enabled=true
UpdateToggleButton(CameraLockButton,true,"自瞄锁定:开启","自瞄锁定:关闭")
ShowNotification("自瞄已开启 - 目标: "..Teleport.Target.Name,Color3.fromRGB(0,255,100))
if CameraLock.Connection then CameraLock.Connection:Disconnect() end
CameraLock.Connection=RunService.RenderStepped:Connect(function()
if not CameraLock.Enabled then return end
local target=Teleport.Target
if not target then return end
local targetChar=target.Character
local myChar=player.Character
if not targetChar or not myChar then return end
local targetRoot=targetChar:FindFirstChild("HumanoidRootPart")or targetChar:FindFirstChild("Head")
local myRoot=myChar:FindFirstChild("HumanoidRootPart")
local myHumanoid=myChar:FindFirstChildOfClass("Humanoid")
if not targetRoot or not myRoot then return end
if myHumanoid then myHumanoid.AutoRotate=false end
local cam=workspace.CurrentCamera
if cam then cam.CFrame=CFrame.new(cam.CFrame.Position,targetRoot.Position) end
myRoot.CFrame=CFrame.new(myRoot.Position,Vector3.new(targetRoot.Position.X,myRoot.Position.Y,targetRoot.Position.Z))
end)
end
end
CameraLockButton.MouseButton1Click:Connect(ToggleCameraLock)
