local function SaveCurrentCoordinate()local character=player.Character if not character then ShowNotification("角色未找到",Color3.fromRGB(255,50,50))return end local humanoidRootPart=character:FindFirstChild("HumanoidRootPart")if not humanoidRootPart then ShowNotification("未找到HumanoidRootPart",Color3.fromRGB(255,50,50))return end CreateTextInputPopup("保存坐标","输入坐标名称",function(coordinateName)local position=humanoidRootPart.Position local coordinate={name=coordinateName,x=math.round(position.X*100)/100,y=math.round(position.Y*100)/100,z=math.round(position.Z*100)/100,timestamp=os.time()}table.insert(CoordinateManager.SavedCoordinates,coordinate)SaveCoordinates()ShowNotification("坐标已保存: "..coordinateName,Color3.fromRGB(0,255,100))end)end
local function ShowCoordinateSelectionPopup(title,actionCallback)if #CoordinateManager.SavedCoordinates==0 then ShowNotification("没有保存的坐标",Color3.fromRGB(255,150,0))return end local SelectionGui=Instance.new("ScreenGui")SelectionGui.Parent=player:WaitForChild("PlayerGui")local SelectionFrame=Instance.new("Frame")SelectionFrame.Parent=SelectionGui SelectionFrame.Size=UDim2.new(0,280,0,350)SelectionFrame.Position=UDim2.new(0.5,-140,0.5,-175)SelectionFrame.BackgroundColor3=Color3.fromRGB(20,20,35)SelectionFrame.Active=true SelectionFrame.Draggable=true local SelectionCorner=Instance.new("UICorner")SelectionCorner.Parent=SelectionFrame SelectionCorner.CornerRadius=UDim.new(0,10)local SelectionStroke=Instance.new("UIStroke")SelectionStroke.Parent=SelectionFrame SelectionStroke.Color=Color3.fromRGB(255,255,255)SelectionStroke.Thickness=2 local SelectionStrokeGrad=Instance.new("UIGradient")SelectionStrokeGrad.Color=makeRainbowColorSequence(0,1,1,6)SelectionStrokeGrad.Rotation=0 SelectionStrokeGrad.Parent=SelectionStroke table.insert(_rainbowGrads,SelectionStrokeGrad)local Title=Instance.new("TextLabel")Title.Parent=SelectionFrame Title.Size=UDim2.new(1,-20,0,30)Title.Position=UDim2.new(0,10,0,10)Title.BackgroundTransparency=1 Title.Text=title Title.TextColor3=Color3.fromRGB(220,220,255)Title.TextSize=14 Title.Font=Enum.Font.GothamBold local ScrollFrame=Instance.new("ScrollingFrame")ScrollFrame.Parent=SelectionFrame ScrollFrame.Size=UDim2.new(1,-20,1,-80)ScrollFrame.Position=UDim2.new(0,10,0,50)ScrollFrame.BackgroundTransparency=1 ScrollFrame.ScrollBarThickness=4 ScrollFrame.CanvasSize=UDim2.new(0,0,0,#CoordinateManager.SavedCoordinates*45)local CloseButton=Instance.new("TextButton")CloseButton.Parent=SelectionFrame CloseButton.Size=UDim2.new(0,80,0,25)CloseButton.Position=UDim2.new(0.5,-40,1,-35)CloseButton.BackgroundColor3=Color3.fromRGB(120,40,40)CloseButton.Text="关闭"CloseButton.TextColor3=Color3.fromRGB(220,220,255)CloseButton.TextSize=12 CloseButton.Font=Enum.Font.Gotham local CloseCorner=Instance.new("UICorner")CloseCorner.Parent=CloseButton CloseCorner.CornerRadius=UDim.new(0,5)for i,coord in ipairs(CoordinateManager.SavedCoordinates)do local CoordButton=Instance.new("TextButton")CoordButton.Size=UDim2.new(1,0,0,40)CoordButton.Position=UDim2.new(0,0,0,(i-1)*45)CoordButton.BackgroundColor3=Color3.fromRGB(40,40,60)CoordButton.Text=string.format("%s\nX:%.1f Y:%.1f Z:%.1f",coord.name,coord.x,coord.y,coord.z)CoordButton.TextColor3=Color3.fromRGB(220,220,255)CoordButton.TextSize=9 CoordButton.Font=Enum.Font.Gotham CoordButton.TextWrapped=true CoordButton.Parent=ScrollFrame local CoordCorner=Instance.new("UICorner")CoordCorner.Parent=CoordButton CoordCorner.CornerRadius=UDim.new(0,6)local CoordStroke=Instance.new("UIStroke")CoordStroke.Parent=CoordButton CoordStroke.Color=Color3.fromRGB(255,255,255)CoordStroke.Thickness=1 local CoordStrokeGrad=Instance.new("UIGradient")CoordStrokeGrad.Color=makeRainbowColorSequence(i*30,1,1,6)CoordStrokeGrad.Rotation=0 CoordStrokeGrad.Parent=CoordStroke table.insert(_rainbowGrads,CoordStrokeGrad)CoordButton.MouseButton1Click:Connect(function()actionCallback(coord,i)SelectionGui:Destroy()end)end CloseButton.MouseButton1Click:Connect(function()SelectionGui:Destroy()end)end
local function TeleportToCoordinate()ShowCoordinateSelectionPopup("选择要传送的坐标",function(coord)local character=player.Character if not character then ShowNotification("角色未找到",Color3.fromRGB(255,50,50))return end local humanoidRootPart=character:FindFirstChild("HumanoidRootPart")if not humanoidRootPart then ShowNotification("未找到HumanoidRootPart",Color3.fromRGB(255,50,50))return end humanoidRootPart.CFrame=CFrame.new(coord.x,coord.y,coord.z)ShowNotification("已传送到: "..coord.name,Color3.fromRGB(0,255,100))end)end
