local function CreatePlayerSelectionUI()local PlayerSelectGui=Instance.new("ScreenGui")PlayerSelectGui.Parent=player:WaitForChild("PlayerGui")PlayerSelectGui.Name="PlayerSelectionUI"PlayerSelectGui.ResetOnSpawn=false local PlayerSelectFrame=Instance.new("Frame")PlayerSelectFrame.Parent=PlayerSelectGui PlayerSelectFrame.Size=UDim2.new(0,200,0,300)PlayerSelectFrame.Position=UDim2.new(0.5,-100,0.5,-150)PlayerSelectFrame.BackgroundColor3=Color3.fromRGB(20,20,35)PlayerSelectFrame.Active=true PlayerSelectFrame.Draggable=true local PlayerSelectCorner=Instance.new("UICorner")PlayerSelectCorner.Parent=PlayerSelectFrame PlayerSelectCorner.CornerRadius=UDim.new(0,10)local PlayerSelectStroke=Instance.new("UIStroke")PlayerSelectStroke.Parent=PlayerSelectFrame PlayerSelectStroke.Color=Color3.fromRGB(255,255,255)PlayerSelectStroke.Thickness=2 local PlayerSelectStrokeGrad=Instance.new("UIGradient")PlayerSelectStrokeGrad.Color=makeRainbowColorSequence(0,1,1,6)PlayerSelectStrokeGrad.Rotation=0 PlayerSelectStrokeGrad.Parent=PlayerSelectStroke table.insert(_rainbowGrads,PlayerSelectStrokeGrad)local Title=Instance.new("TextLabel")Title.Parent=PlayerSelectFrame Title.Size=UDim2.new(1,-20,0,30)Title.Position=UDim2.new(0,10,0,10)Title.BackgroundTransparency=1 Title.Text="选择玩家"Title.TextColor3=Color3.fromRGB(220,220,255)Title.TextSize=14 Title.Font=Enum.Font.GothamBold local PlayerScroll=Instance.new("ScrollingFrame")PlayerScroll.Parent=PlayerSelectFrame PlayerScroll.Size=UDim2.new(1,-20,1,-80)PlayerScroll.Position=UDim2.new(0,10,0,50)PlayerScroll.BackgroundTransparency=1 PlayerScroll.ScrollBarThickness=4 local PlayerListLayout=Instance.new("UIListLayout")PlayerListLayout.Parent=PlayerScroll PlayerListLayout.SortOrder=Enum.SortOrder.Name local CloseButton=Instance.new("TextButton")CloseButton.Parent=PlayerSelectFrame CloseButton.Size=UDim2.new(0,80,0,25)CloseButton.Position=UDim2.new(0.5,-40,1,-35)CloseButton.BackgroundColor3=Color3.fromRGB(120,40,40)CloseButton.Text="关闭"CloseButton.TextColor3=Color3.fromRGB(220,220,255)CloseButton.TextSize=12 CloseButton.Font=Enum.Font.Gotham local CloseCorner=Instance.new("UICorner")CloseCorner.Parent=CloseButton CloseCorner.CornerRadius=UDim.new(0,5)Teleport.PlayerList=GetAllPlayers()PlayerScroll.CanvasSize=UDim2.new(0,0,0,#Teleport.PlayerList*35)for _,p in ipairs(Teleport.PlayerList)do local currentPlayer=p local PlayerButton=Instance.new("TextButton")PlayerButton.Size=UDim2.new(1,0,0,30)PlayerButton.BackgroundColor3=Color3.fromRGB(40,40,60)PlayerButton.Text=p.DisplayName.." ("..p.Name..")"PlayerButton.TextColor3=Color3.fromRGB(220,220,255)PlayerButton.TextSize=11 PlayerButton.Font=Enum.Font.Gotham PlayerButton.Parent=PlayerScroll local PlayerButtonCorner=Instance.new("UICorner")PlayerButtonCorner.Parent=PlayerButton PlayerButtonCorner.CornerRadius=UDim.new(0,6)local PlayerButtonStroke=Instance.new("UIStroke")PlayerButtonStroke.Parent=PlayerButton PlayerButtonStroke.Color=Color3.fromRGB(255,255,255)PlayerButtonStroke.Thickness=1 local PlayerButtonStrokeGrad=Instance.new("UIGradient")PlayerButtonStrokeGrad.Color=makeRainbowColorSequence(0,1,1,6)PlayerButtonStrokeGrad.Rotation=0 PlayerButtonStrokeGrad.Parent=PlayerButtonStroke table.insert(_rainbowGrads,PlayerButtonStrokeGrad)PlayerButton.MouseButton1Click:Connect(function()Teleport.Target=currentPlayer PlayerSelectGui:Destroy()ShowNotification("已选择: "..currentPlayer.DisplayName.." ("..currentPlayer.Name..")",Color3.fromRGB(0,200,255))end)end CloseButton.MouseButton1Click:Connect(function()PlayerSelectGui:Destroy()end)end
PlayerSelectButton.MouseButton1Click:Connect(CreatePlayerSelectionUI)
local function GetPredictedPosition(rootPart)if not Teleport.PredictEnabled then return rootPart.Position end local vel=rootPart.AssemblyLinearVelocity if vel.Magnitude<0.5 then return rootPart.Position end return rootPart.Position+vel*Teleport.PredictDelay end
local function TeleportRoutine()if not Teleport.Active then return end local myChar=player.Character local targetChar=Teleport.Target and Teleport.Target.Character if not myChar or not targetChar then StopTeleport()return end local myRoot=myChar:FindFirstChild("HumanoidRootPart")local targetRoot=targetChar:FindFirstChild("HumanoidRootPart")if myRoot and targetRoot then local targetPos=GetPredictedPosition(targetRoot)local newPos=Vector3.new(targetPos.X,targetPos.Y-5.5,targetPos.Z)myRoot.CFrame=CFrame.new(newPos,targetPos)end end
local function LockBehindRoutine()if not Teleport.Active then return end local myChar=player.Character local targetChar=Teleport.Target and Teleport.Target.Character if not myChar or not targetChar then StopTeleport()return end local myRoot=myChar:FindFirstChild("HumanoidRootPart")local targetRoot=targetChar:FindFirstChild("HumanoidRootPart")local myHumanoid=myChar:FindFirstChildOfClass("Humanoid")if not myRoot or not targetRoot or not myHumanoid then StopTeleport()return end local targetPos=GetPredictedPosition(targetRoot)local targetCFrameAtPos=CFrame.new(targetPos)*(targetRoot.CFrame-targetRoot.CFrame.Position)local rx,ry,rz=targetCFrameAtPos:ToEulerAnglesYXZ()local yawCFrame=CFrame.fromEulerAnglesYXZ(0,ry,0)local offsetCFrame=CFrame.new(targetCFrameAtPos.Position)*yawCFrame*CFrame.new(0,0,5)local offsetPos=offsetCFrame.Position local finalCFrame=CFrame.new(offsetPos)*yawCFrame myHumanoid.AutoRotate=false myRoot.AssemblyLinearVelocity=Vector3.zero myRoot.AssemblyAngularVelocity=Vector3.zero myRoot.CFrame=finalCFrame if sethiddenproperty then pcall(function()sethiddenproperty(myRoot,"PhysicsRepRootPart",targetRoot)end)end end
local function ParallelOrbitRoutine()if not Teleport.HorizontalOrbitActive then return end local myChar=player.Character local targetChar=Teleport.Target and Teleport.Target.Character if not myChar or not targetChar then StopParallelOrbit()return end local myRoot=myChar:FindFirstChild("HumanoidRootPart")local targetRoot=targetChar:FindFirstChild("HumanoidRootPart")if myRoot and targetRoot then local centerPos=GetPredictedPosition(targetRoot)Teleport.HorizontalAngle=Teleport.HorizontalAngle+Teleport.HorizontalSpeed*0.05 local radius=Teleport.OrbitRadius local x=centerPos.X+math.cos(Teleport.HorizontalAngle)*radius local z=centerPos.Z+math.sin(Teleport.HorizontalAngle)*radius local raycastParams=RaycastParams.new()raycastParams.FilterType=Enum.RaycastFilterType.Blacklist raycastParams.FilterDescendantsInstances={myChar}local raycastResult=Workspace:Raycast(Vector3.new(x,centerPos.Y+10,z),Vector3.new(0,-50,0),raycastParams)local y=raycastResult and raycastResult.Position.Y or centerPos.Y local newPos=Vector3.new(x,y+3,z)myRoot.CFrame=CFrame.new(newPos,centerPos)end end
local function DeleteUI()ScreenGui:Destroy()ShowNotification("UI界面已删除",Color3.fromRGB(255,100,0))end
DeleteUIButton.MouseButton1Click:Connect(DeleteUI)
local function ToggleWallVision()Teleport.WallVision=not Teleport.WallVision UpdateToggleButton(WallVisionButton,Teleport.WallVision,"穿墙视野:开启","穿墙视野:关闭")if Teleport.WallVision then Teleport.OriginalTransparency={}for _,part in ipairs(workspace:GetDescendants())do if part:IsA("BasePart")and part.Transparency<0.5 then Teleport.OriginalTransparency[part]=part.Transparency part.Transparency=0.7 end end ShowNotification("穿墙视野已启用",Color3.fromRGB(0,200,255))else for part,transparency in pairs(Teleport.OriginalTransparency)do if part:IsA("BasePart")then part.Transparency=transparency end end Teleport.OriginalTransparency={}ShowNotification("穿墙视野已禁用",Color3.fromRGB(255,100,0))end end
WallVisionButton.MouseButton1Click:Connect(ToggleWallVision)
local function StartTeleport()if Teleport.Active then return end if not Teleport.Target then ShowNotification("请先选择目标玩家",Color3.fromRGB(255,50,50))return end Teleport.Active=true if Teleport.Mode=="LockBehind" then Teleport.Connection=RunService.Heartbeat:Connect(function()LockBehindRoutine()task.wait(0.001)end)ShowNotification("背后锁定已启动 - 目标: "..Teleport.Target.Name,Color3.fromRGB(0,255,100))else Teleport.Connection=RunService.Heartbeat:Connect(function()TeleportRoutine()task.wait(0.001)end)ShowNotification("传送已启动 - 目标: "..Teleport.Target.Name,Color3.fromRGB(0,255,100))end Status.BackgroundColor3=Color3.fromRGB(0,255,100)end
StartButton.MouseButton1Click:Connect(StartTeleport)
local function ToggleTeleportMode()if Teleport.Mode=="Follow" then Teleport.Mode="LockBehind" ModeButton.Text="背后" ShowNotification("切换为: 锁敌背后(零延迟)",Color3.fromRGB(0,200,255))else Teleport.Mode="Follow" ModeButton.Text="脚下" ShowNotification("切换为: 脚下跟随",Color3.fromRGB(0,200,255))end end
ModeButton.MouseButton1Click:Connect(ToggleTeleportMode)
local function StopTeleport()if Teleport.Active then Teleport.Active=false if Teleport.Connection then Teleport.Connection:Disconnect()Teleport.Connection=nil end local myChar=player.Character if myChar then local myRoot=myChar:FindFirstChild("HumanoidRootPart")local myHumanoid=myChar:FindFirstChildOfClass("Humanoid")if sethiddenproperty and myRoot then pcall(function()sethiddenproperty(myRoot,"PhysicsRepRootPart",nil)end)end if myRoot then pcall(function()myRoot.AssemblyLinearVelocity=Vector3.zero end)pcall(function()myRoot.AssemblyAngularVelocity=Vector3.zero end)pcall(function()myRoot.Velocity=Vector3.zero end)pcall(function()myRoot.RotVelocity=Vector3.zero end)end if myHumanoid then pcall(function()myHumanoid.AutoRotate=true end)end end ShowNotification("传送已停止",Color3.fromRGB(255,100,0))Status.BackgroundColor3=Color3.fromRGB(255,50,50)else ShowNotification("传送未启动",Color3.fromRGB(255,150,0))end AutoCombo.Executing=false if Teleport.FlingLoopActive then Teleport.FlingLoopActive=false if Teleport.FlingLoopConnection then Teleport.FlingLoopConnection:Disconnect()Teleport.FlingLoopConnection=nil end UpdateToggleButton(FlingLoopButton,false,"循环甩飞:开启","循环甩飞:关闭")end if Teleport.TouchFlingActive then Teleport.TouchFlingActive=false if Teleport.TouchFlingConnection then Teleport.TouchFlingConnection:Disconnect()Teleport.TouchFlingConnection=nil end flingThread=nil UpdateToggleButton(TouchFlingButton,false,"触碰甩飞:开启","触碰甩飞:关闭")end if Teleport.HorizontalOrbitActive then StopParallelOrbit()end end
StopButton.MouseButton1Click:Connect(StopTeleport)
local function StartParallelOrbit()if Teleport.HorizontalOrbitActive then return end if not Teleport.Target then ShowNotification("请先选择目标玩家",Color3.fromRGB(255,50,50))return end Teleport.HorizontalOrbitActive=true Teleport.HorizontalAngle=0 Teleport.HorizontalOrbitConnection=RunService.Heartbeat:Connect(function()ParallelOrbitRoutine()task.wait(0.001)end)UpdateToggleButton(ParallelOrbitButton,true,"平行环绕:开启","平行环绕:关闭")ShowNotification("平行环绕已启动",Color3.fromRGB(0,200,255))Status.BackgroundColor3=Color3.fromRGB(0,200,255)end
local function StopParallelOrbit()if not Teleport.HorizontalOrbitActive then ShowNotification("平行环绕未启动",Color3.fromRGB(255,150,0))return end Teleport.HorizontalOrbitActive=false if Teleport.HorizontalOrbitConnection then Teleport.HorizontalOrbitConnection:Disconnect()Teleport.HorizontalOrbitConnection=nil end UpdateToggleButton(ParallelOrbitButton,false,"平行环绕:开启","平行环绕:关闭")ShowNotification("平行环绕已停止",Color3.fromRGB(255,100,0))if not Teleport.Active then Status.BackgroundColor3=Color3.fromRGB(255,50,50)end end
local function ToggleParallelOrbit()if Teleport.HorizontalOrbitActive then StopParallelOrbit()else StartParallelOrbit()end end
ParallelOrbitButton.MouseButton1Click:Connect(ToggleParallelOrbit)
local function randomOffset()local angle=math.random()*math.pi*2 local dist=math.random()*SupaTech.RandomRadius return Vector3.new(math.cos(angle)*dist,0,math.sin(angle)*dist)end
local function isPlayingAnim(hum,animId)if not hum then return false end for _,track in ipairs(hum:GetPlayingAnimationTracks())do local anim=track.Animation if anim then local id=anim.AnimationId if id and string.find(id,animId)then return true end end end return false end
local function getNearestEnemy()local char=player.Character if not char then return nil,nil end local root=char:FindFirstChild("HumanoidRootPart")if not root then return nil,nil end local nearest=nil local nearestRoot=nil local nearestDist=math.huge local myPos=root.Position for _,other in ipairs(Players:GetPlayers())do if other~=player then local oChar=other.Character if oChar then local oRoot=oChar:FindFirstChild("HumanoidRootPart")if oRoot then local dist=(myPos-oRoot.Position).Magnitude if dist<nearestDist then nearestDist=dist nearest=oChar nearestRoot=oRoot end end end end end for _,obj in ipairs(Workspace:GetDescendants())do if obj:IsA("Model")and obj~=char then local hum=obj:FindFirstChild("Humanoid")local oRoot=obj:FindFirstChild("HumanoidRootPart")if hum and oRoot then local dist=(myPos-oRoot.Position).Magnitude if dist<nearestDist then nearestDist=dist nearest=obj nearestRoot=oRoot end end end end if nearest and nearestRoot then return nearest,nearestRoot end return nil,nil end
local function doDash()local char=player.Character if not char then return end local comm=char:FindFirstChild("Communicate")if comm then local args={{Dash=Enum.KeyCode.W,Key=Enum.KeyCode.Q,Goal="KeyPress",MousePos=CFrame.new(-36.971492767333984,438.15667724609375,86.00199127197266,-0.9908232092857361,-0.0044507840648293495,0.1350911408662796,-4.656612873077393e-10,0.999457836151123,0.03292866051197052,-0.13516442477703094,0.03262647986412048,-0.9902859330177307)}}comm:FireServer(unpack(args))SupaTech.IsCooldown=true SupaTech.CooldownEndTime=tick()+SupaTech.CooldownTime end end
local function updateSupaCooldown()if SupaTech.IsCooldown then local remaining=SupaTech.CooldownEndTime-tick()if remaining<=0 then SupaTech.IsCooldown=false end end if SupaStatusLabel then if SupaTech.IsCooldown then local remaining=SupaTech.CooldownEndTime-tick()if remaining>0 then SupaStatusLabel.Text=string.format("冷却:%.1f秒",remaining)SupaStatusLabel.TextColor3=Color3.fromRGB(255,200,100)else SupaStatusLabel.Text="就绪"SupaStatusLabel.TextColor3=Color3.fromRGB(150,255,150)end else SupaStatusLabel.Text="就绪"SupaStatusLabel.TextColor3=Color3.fromRGB(150,255,150)end end end
local function startTeleportLoop(enemyChar,enemyRoot)local startTime=tick()local myChar=player.Character if not myChar then return end local myRoot=myChar:FindFirstChild("HumanoidRootPart")if not myRoot then return end local myHum=myChar:FindFirstChild("Humanoid")if not myHum then return end local enemyHum=enemyChar:FindFirstChild("Humanoid")if not enemyHum then return end myHum.PlatformStand=true local fixedOffset=randomOffset()local myPos=myRoot.Position local enemyPos=enemyRoot.Position local dirToEnemy=(enemyPos-myPos).Unit local facePos=enemyPos-dirToEnemy*SupaTech.FaceDistance facePos=Vector3.new(facePos.X,enemyPos.Y,facePos.Z)myRoot.CFrame=CFrame.new(facePos+fixedOffset)*CFrame.Angles(math.rad(SupaTech.UpwardAngle),0,0)task.wait(0.1)local footPos=enemyRoot.Position-Vector3.new(0,SupaTech.TeleportOffset,0)myRoot.CFrame=CFrame.new(footPos+fixedOffset)*CFrame.Angles(math.rad(SupaTech.UpwardAngle),0,0)while tick()-startTime<SupaTech.TeleportDuration do if not SupaTech.Enabled then break end if not enemyRoot or not enemyRoot.Parent then break end if not myRoot or not myRoot.Parent then break end if not myHum then break end local currentEnemyHum=enemyChar:FindFirstChild("Humanoid")if not currentEnemyHum then break end if isPlayingAnim(currentEnemyHum,SupaTech.EndAnimId)or isPlayingAnim(currentEnemyHum,SupaTech.RagdollAnimId)then break end local newFootPos=enemyRoot.Position-Vector3.new(0,SupaTech.TeleportOffset,0)myRoot.CFrame=CFrame.new(newFootPos+fixedOffset)*CFrame.Angles(math.rad(SupaTech.UpwardAngle),0,0)task.wait()end if enemyRoot and enemyRoot.Parent and myRoot and myRoot.Parent then local finalFootPos=enemyRoot.Position-Vector3.new(0,SupaTech.VerticalOffset,0)myRoot.CFrame=CFrame.new(finalFootPos+fixedOffset)*CFrame.Angles(math.rad(SupaTech.UpwardAngle),0,0)end myHum.PlatformStand=false end
local function executeSupaTech()if SupaTech.IsExecuting then return end if SupaTech.IsCooldown then return end SupaTech.IsExecuting=true local enemyChar,enemyRoot=getNearestEnemy()if not enemyChar or not enemyRoot then SupaTech.IsExecuting=false return end local enemyHumCheck=enemyChar:FindFirstChild("Humanoid")if enemyHumCheck and(isPlayingAnim(enemyHumCheck,SupaTech.RagdollAnimId)or isPlayingAnim(enemyHumCheck,SupaTech.EndAnimId))then SupaTech.IsExecuting=false return end task.wait(SupaTech.WaitBeforeAction)if not enemyChar.Parent or not enemyRoot.Parent then SupaTech.IsExecuting=false return end local enemyHum2=enemyChar:FindFirstChild("Humanoid")if enemyHum2 and(isPlayingAnim(enemyHum2,SupaTech.RagdollAnimId)or isPlayingAnim(enemyHum2,SupaTech.EndAnimId))then SupaTech.IsExecuting=false return end doDash()startTeleportLoop(enemyChar,enemyRoot)SupaTech.IsExecuting=false end
local function ToggleSupaTech()SupaTech.Enabled=not SupaTech.Enabled UpdateToggleButton(SupaTechButton,SupaTech.Enabled,"SupaTech:开启","SupaTech:关闭")if SupaTech.Enabled then if OreoData.Enabled then ToggleOreoTech()end ShowNotification("Supa Tech 已启用",Color3.fromRGB(0,255,100))else ShowNotification("Supa Tech 已禁用",Color3.fromRGB(255,100,0))SupaTech.IsExecuting=false end end
