local AntiFling={Enabled=false,MaxLinear=200,MaxAngular=100,SafeCFrame=nil,BodyMovers={"BodyVelocity","BodyAngularVelocity","BodyForce","BodyThrust","BodyPosition","BodyGyro"},Conns={},HeartbeatCon=nil,OriginalCanCollide={},RestoreTask=nil}
local function RecordOriginalCollide()local char=player.Character if not char then return end AntiFling.OriginalCanCollide={}for _,part in ipairs(char:GetDescendants())do if part:IsA("BasePart")then AntiFling.OriginalCanCollide[part]=part.CanCollide end end end
local function RestoreOriginalCollide()if AntiFling.RestoreTask then task.cancel(AntiFling.RestoreTask)AntiFling.RestoreTask=nil end for part,original in pairs(AntiFling.OriginalCanCollide)do if part and part.Parent then part.CanCollide=original part.AssemblyLinearVelocity=Vector3.zero part.AssemblyAngularVelocity=Vector3.zero part.Velocity=Vector3.zero part.RotVelocity=Vector3.zero end end AntiFling.OriginalCanCollide={}local char=player.Character if char then for _,part in ipairs(char:GetDescendants())do if part:IsA("BasePart")then part.AssemblyLinearVelocity=Vector3.zero part.AssemblyAngularVelocity=Vector3.zero part.Velocity=Vector3.zero part.RotVelocity=Vector3.zero end end end end
local function FlingNeutralize()if not AntiFling.Enabled then return end local char=player.Character if not char then return end for _,obj in ipairs(char:GetDescendants())do if table.find(AntiFling.BodyMovers,obj.ClassName)then pcall(function()obj:Destroy()end)end end for _,part in ipairs(char:GetDescendants())do if part:IsA("BasePart")then part.CanCollide=false part.AssemblyLinearVelocity=Vector3.zero part.AssemblyAngularVelocity=Vector3.zero part.Velocity=Vector3.zero part.RotVelocity=Vector3.zero end end local root=char:FindFirstChild("HumanoidRootPart")if root and AntiFling.SafeCFrame then root.CFrame=AntiFling.SafeCFrame char:SetPrimaryPartCFrame(AntiFling.SafeCFrame)end if AntiFling.RestoreTask then task.cancel(AntiFling.RestoreTask)end AntiFling.RestoreTask=task.delay(0.4,function()if char and char.Parent then for part,original in pairs(AntiFling.OriginalCanCollide)do if part and part.Parent then part.CanCollide=original end end end AntiFling.RestoreTask=nil end)ShowNotification("检测到被甩飞，已 neutralize",Color3.fromRGB(255,100,0))end
local function WatchBodyMovers(char)local con=char.DescendantAdded:Connect(function(child)if not AntiFling.Enabled then return end if table.find(AntiFling.BodyMovers,child.ClassName)then child:Destroy()ShowNotification("拦截异常 "..child.ClassName,Color3.fromRGB(255,100,0))FlingNeutralize()end end)table.insert(AntiFling.Conns,con)end
local function AntiFlingHeartbeat()if not AntiFling.Enabled then return end local char=player.Character if not char then return end local root=char:FindFirstChild("HumanoidRootPart")if not root then return end local linear=root.AssemblyLinearVelocity.Magnitude local angular=root.AssemblyAngularVelocity.Magnitude if linear<60 and angular<40 then AntiFling.SafeCFrame=root.CFrame end if linear>AntiFling.MaxLinear or angular>AntiFling.MaxAngular then FlingNeutralize()end end
local function SetupAntiFling(char)for _,con in ipairs(AntiFling.Conns)do pcall(function()con:Disconnect()end)end AntiFling.Conns={}task.wait(0.3)if char and char.Parent then WatchBodyMovers(char)if AntiFling.Enabled then RecordOriginalCollide()end end end
if player.Character then SetupAntiFling(player.Character)end
player.CharacterAdded:Connect(SetupAntiFling)
AntiFling.HeartbeatCon=RunService.Heartbeat:Connect(AntiFlingHeartbeat)
local function ToggleAntiFling()AntiFling.Enabled=not AntiFling.Enabled UpdateToggleButton(AntiFlingButton,AntiFling.Enabled,"防甩飞:开启","防甩飞:关闭")if AntiFling.Enabled then ShowNotification("防甩飞已启用",Color3.fromRGB(0,255,100))if not AntiFling.HeartbeatCon then AntiFling.HeartbeatCon=RunService.Heartbeat:Connect(AntiFlingHeartbeat)end local char=player.Character if char then SetupAntiFling(char)end else ShowNotification("防甩飞已禁用",Color3.fromRGB(255,100,0))if AntiFling.HeartbeatCon then AntiFling.HeartbeatCon:Disconnect()AntiFling.HeartbeatCon=nil end for _,con in ipairs(AntiFling.Conns)do pcall(function()con:Disconnect()end)end AntiFling.Conns={}if AntiFling.RestoreTask then task.cancel(AntiFling.RestoreTask)AntiFling.RestoreTask=nil end RestoreOriginalCollide()AntiFling.SafeCFrame=nil end end
AntiFlingButton.MouseButton1Click:Connect(ToggleAntiFling)
local flingThread=nil
local function SetupTouchFling()
    if flingThread then return end
    flingThread = task.spawn(function()
        local flingPower = 2500
        local movel = 0.05
        while Teleport.TouchFlingActive do
            local char = player.Character
            if not char then task.wait(0.1); continue end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then task.wait(0.1); continue end
            RunService.Heartbeat:Wait()
            local originalVelocity = hrp.Velocity
            hrp.Velocity = originalVelocity * 1.5 + Vector3.new(0, flingPower, 0)
            RunService.RenderStepped:Wait()
            hrp.Velocity = originalVelocity * 0.8
            RunService.Stepped:Wait()
            hrp.Velocity = originalVelocity + Vector3.new(0, movel, 0)
            movel = -movel
        end
        flingThread = nil
    end)
end
local function ToggleTouchFling()
    Teleport.TouchFlingActive = not Teleport.TouchFlingActive
    UpdateToggleButton(TouchFlingButton, Teleport.TouchFlingActive, "触碰甩飞:开启", "触碰甩飞:关闭")
    if Teleport.TouchFlingActive then
        SetupTouchFling()
        ShowNotification("触碰甩飞已启动", Color3.fromRGB(0, 200, 255))
    else
        flingThread = nil
        ShowNotification("触碰甩飞已停止", Color3.fromRGB(255, 100, 0))
    end
end
TouchFlingButton.MouseButton1Click:Connect(ToggleTouchFling)
local function FlingPlayer(TargetPlayer)local Character=player.Character local Humanoid=Character and Character:FindFirstChildOfClass("Humanoid")local RootPart=Humanoid and Humanoid.RootPart if not TargetPlayer or not TargetPlayer.Character then ShowNotification("目标无效",Color3.fromRGB(255,50,50))return end local TCharacter=TargetPlayer.Character local THumanoid local TRootPart local THead local Accessory local Handle if TCharacter:FindFirstChildOfClass("Humanoid")then THumanoid=TCharacter:FindFirstChildOfClass("Humanoid")end if THumanoid and THumanoid.RootPart then TRootPart=THumanoid.RootPart end if TCharacter:FindFirstChild("Head")then THead=TCharacter.Head end if TCharacter:FindFirstChildOfClass("Accessory")then Accessory=TCharacter:FindFirstChildOfClass("Accessory")end if Accessory and Accessory:FindFirstChild("Handle")then Handle=Accessory.Handle end if Character and Humanoid and RootPart then if RootPart.Velocity.Magnitude<50 then local OldPos=RootPart.CFrame getgenv().OldPos=OldPos end if THumanoid and THumanoid.Sit then ShowNotification("目标正在坐着",Color3.fromRGB(255,200,0))return end local targetStartPos=(TRootPart or THead or Handle).Position if THead then workspace.CurrentCamera.CameraSubject=THead elseif not THead and Handle then workspace.CurrentCamera.CameraSubject=Handle elseif THumanoid and TRootPart then workspace.CurrentCamera.CameraSubject=THumanoid end if not TCharacter:FindFirstChildWhichIsA("BasePart")then ShowNotification("目标缺少部件",Color3.fromRGB(255,50,50))return end local oldFPDH=workspace.FallenPartsDestroyHeight workspace.FallenPartsDestroyHeight=0/0 local FPos=function(BasePart,Pos,Ang)RootPart.CFrame=CFrame.new(BasePart.Position)*Pos*Ang Character:SetPrimaryPartCFrame(CFrame.new(BasePart.Position)*Pos*Ang)RootPart.Velocity=Vector3.new(9e7,9e7*10,9e7)RootPart.RotVelocity=Vector3.new(9e8,9e8,9e8)end local SFBasePart=function(BasePart)local TimeToWait=2 local Time=tick()local Angle=0 repeat if(BasePart.Position-targetStartPos).Magnitude>100 then workspace.CurrentCamera.CameraSubject=Humanoid ShowNotification("目标飞出太远，视角已恢复",Color3.fromRGB(255,200,100))break end if RootPart and THumanoid then if BasePart.Velocity.Magnitude<50 then Angle=Angle+100 FPos(BasePart,CFrame.new(0,1.5,0)+THumanoid.MoveDirection*BasePart.Velocity.Magnitude/1.25,CFrame.Angles(math.rad(Angle),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,0)+THumanoid.MoveDirection*BasePart.Velocity.Magnitude/1.25,CFrame.Angles(math.rad(Angle),0,0))task.wait()FPos(BasePart,CFrame.new(2.25,1.5,-2.25)+THumanoid.MoveDirection*BasePart.Velocity.Magnitude/1.25,CFrame.Angles(math.rad(Angle),0,0))task.wait()FPos(BasePart,CFrame.new(-2.25,-1.5,2.25)+THumanoid.MoveDirection*BasePart.Velocity.Magnitude/1.25,CFrame.Angles(math.rad(Angle),0,0))task.wait()FPos(BasePart,CFrame.new(0,1.5,0)+THumanoid.MoveDirection,CFrame.Angles(math.rad(Angle),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,0)+THumanoid.MoveDirection,CFrame.Angles(math.rad(Angle),0,0))task.wait()else FPos(BasePart,CFrame.new(0,1.5,THumanoid.WalkSpeed),CFrame.Angles(math.rad(90),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,-THumanoid.WalkSpeed),CFrame.Angles(0,0,0))task.wait()FPos(BasePart,CFrame.new(0,1.5,THumanoid.WalkSpeed),CFrame.Angles(math.rad(90),0,0))task.wait()FPos(BasePart,CFrame.new(0,1.5,TRootPart.Velocity.Magnitude/1.25),CFrame.Angles(math.rad(90),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,-TRootPart.Velocity.Magnitude/1.25),CFrame.Angles(0,0,0))task.wait()FPos(BasePart,CFrame.new(0,1.5,TRootPart.Velocity.Magnitude/1.25),CFrame.Angles(math.rad(90),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,0),CFrame.Angles(math.rad(90),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,0),CFrame.Angles(0,0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,0),CFrame.Angles(math.rad(-90),0,0))task.wait()FPos(BasePart,CFrame.new(0,-1.5,0),CFrame.Angles(0,0,0))task.wait()end else break end until BasePart.Velocity.Magnitude>500 or BasePart.Parent~=TargetPlayer.Character or TargetPlayer.Parent~=Players or not TargetPlayer.Character==TCharacter or THumanoid.Sit or Humanoid.Health<=0 or tick()>Time+TimeToWait workspace.CurrentCamera.CameraSubject=Humanoid end local BV=Instance.new("BodyVelocity")BV.Name="EpixVel"BV.Parent=RootPart BV.Velocity=Vector3.new(9e8,9e8,9e8)BV.MaxForce=Vector3.new(1/0,1/0,1/0)Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated,false)if TRootPart and THead then if(TRootPart.CFrame.p-THead.CFrame.p).Magnitude>5 then SFBasePart(THead)else SFBasePart(TRootPart)end elseif TRootPart and not THead then SFBasePart(TRootPart)elseif not TRootPart and THead then SFBasePart(THead)elseif not TRootPart and not THead and Accessory and Handle then SFBasePart(Handle)else ShowNotification("目标缺少可用部件",Color3.fromRGB(255,50,50))BV:Destroy()Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated,true)workspace.CurrentCamera.CameraSubject=Humanoid workspace.FallenPartsDestroyHeight=oldFPDH return end BV:Destroy()Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated,true)workspace.CurrentCamera.CameraSubject=Humanoid local oldPos=getgenv().OldPos or RootPart.CFrame repeat RootPart.CFrame=oldPos*CFrame.new(0,.5,0)Character:SetPrimaryPartCFrame(oldPos*CFrame.new(0,.5,0))Humanoid:ChangeState("GettingUp")for _,part in ipairs(Character:GetChildren())do if part:IsA("BasePart")then part.Velocity=Vector3.new()part.RotVelocity=Vector3.new()end end task.wait()until(RootPart.Position-oldPos.p).Magnitude<25 RootPart.CFrame=oldPos Character:SetPrimaryPartCFrame(oldPos)for _,part in ipairs(Character:GetChildren())do if part:IsA("BasePart")then part.Velocity=Vector3.new()part.RotVelocity=Vector3.new()end end workspace.FallenPartsDestroyHeight=oldFPDH ShowNotification("甩飞完成",Color3.fromRGB(100,200,255))else ShowNotification("角色或 Humanoid 丢失",Color3.fromRGB(255,50,50))end end
