local function setupAutoComboListener()
    local char = player.Character
    if not char then return end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    if AutoCombo.Connection then
        pcall(function() AutoCombo.Connection:Disconnect() end)
        AutoCombo.Connection = nil
    end
    AutoCombo.Connection = humanoid.AnimationPlayed:Connect(function(track)
        if not AutoCombo.Enabled then return end
        if AutoCombo.Executing then return end
        local animId = track.Animation.AnimationId
        if animId:match("12272894215") then
            AutoCombo.Executing = true
            task.spawn(function()
                local success, err = pcall(function()
                    local myChar = player.Character
                    if not myChar then return end
                    local communicate = myChar:FindFirstChild("Communicate")
                    if not communicate then return end
                    local backpack = player:FindFirstChild("Backpack")
                    if not backpack then return end
                    local tool1 = backpack:FindFirstChild("Flowing Water")
                    local tool2 = backpack:FindFirstChild("Lethal Whirlwind Stream")
                    if not tool1 or not tool2 then
                        ShowNotification("未找到技能: Flowing Water / Lethal Whirlwind Stream", Color3.fromRGB(255,50,50))
                        return
                    end
                    communicate:FireServer({Tool = tool1, Goal = "Console Move"})
                    task.wait(2.2)
                    communicate:FireServer({Tool = tool2, Goal = "Console Move"})
                    local hrp = myChar:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local tween = TweenService:Create(hrp, TweenInfo.new(0.1), {CFrame = hrp.CFrame + hrp.CFrame.LookVector * 17})
                        tween:Play()
                        tween.Completed:Wait()
                    end
                end)
                if not success then
                    ShowNotification("自动1+2出错: " .. tostring(err), Color3.fromRGB(255,50,50))
                end
                AutoCombo.Executing = false
            end)
        end
    end)
end

local function ToggleAutoCombo()
    AutoCombo.Enabled = not AutoCombo.Enabled
    UpdateToggleButton(AutoComboButton, AutoCombo.Enabled, "自动1+2(饿狼):开启", "自动1+2(饿狼):关闭")
    if AutoCombo.Enabled then
        ShowNotification("自动1+2(饿狼)已开启", Color3.fromRGB(0,255,100))
        setupAutoComboListener()
    else
        ShowNotification("自动1+2(饿狼)已禁用", Color3.fromRGB(255,100,0))
        if AutoCombo.Connection then
            pcall(function() AutoCombo.Connection:Disconnect() end)
            AutoCombo.Connection = nil
        end
        AutoCombo.Executing = false
    end
end

local function Invis_RefreshParts()InvisData.char=player.Character or player.CharacterAdded:Wait()InvisData.hum=InvisData.char:WaitForChild('Humanoid')InvisData.root=InvisData.char:WaitForChild('HumanoidRootPart')InvisData.parts={}for _,part in ipairs(InvisData.char:GetDescendants())do if part:IsA('BasePart')and part.Transparency==0 then table.insert(InvisData.parts,part)end end end
local function Invis_Toggle()InvisData.enabled=not InvisData.enabled for _,part in ipairs(InvisData.parts)do if part and part.Parent then part.Transparency=InvisData.enabled and 0.5 or 0 end end UpdateToggleButton(InvisButton,InvisData.enabled,"隐身:开启","隐身:关闭")ShowNotification(InvisData.enabled and"隐身已开启"or"隐身已关闭",InvisData.enabled and Color3.fromRGB(0,255,100)or Color3.fromRGB(255,100,0))end
