local function SaitamaTeleportLoop()if not SaitamaDetect.TeleportActive then return end local elapsed=tick()-SaitamaDetect.TeleportStartTime if elapsed>=10 then StopSaitamaTeleport()ShowNotification("防止大招传送已结束（10秒）",Color3.fromRGB(0,255,100))return end local char=player.Character if not char then return end local hrp=char:FindFirstChild("HumanoidRootPart")if not hrp then return end hrp.CFrame=CFrame.new(SaitamaDetect.TargetPos)for _,partName in ipairs({"Head","UpperTorso","LowerTorso","HumanoidRootPart","Torso"})do local part=char:FindFirstChild(partName)if part and part:IsA("BasePart")then part.AssemblyLinearVelocity=Vector3.zero part.AssemblyAngularVelocity=Vector3.zero end end end
