rue)shrinkBtn.Text="+"else frame:TweenSize(UDim2.new(0,300,0,150),"Out","Quad",0.2,true)shrinkBtn.Text="−"end end)local closeBtn=Instance.new("TextButton")closeBtn.Size=UDim2.new(0,25,0,25)closeBtn.Position=UDim2.new(1,-30,0,2.5)closeBtn.BackgroundColor3=Color3.fromRGB(200,50,50)closeBtn.Text="✕"closeBtn.TextColor3=Color3.fromRGB(255,255,255)closeBtn.TextSize=14 closeBtn.Font=Enum.Font.GothamBold closeBtn.Parent=titleBar local closeCorner=Instance.new("UICorner")closeCorner.CornerRadius=UDim.new(0,4)closeCorner.Parent=closeBtn closeBtn.MouseButton1Click:Connect(function()CloseSaitamaPopupUI()ShowNotification("已手动关闭弹窗，传送不受影响",Color3.fromRGB(255,200,0))end)local protectBtn=Instance.new("TextButton")protectBtn.Size=UDim2.new(0,150,0,40)protectBtn.Position=UDim2.new(0.5,-75,0.6,0)protectBtn.BackgroundColor3=Color3.fromRGB(0,120,255)protectBtn.Text="防止大招"protectBtn.TextColor3=Color3.fromRGB(255,255,255)protectBtn.TextSize=16 protectBtn.Font=Enum.Font.GothamBold protectBtn.Parent=frame local protectCorner=Instance.new("UICorner")protectCorner.CornerRadius=UDim.new(0,8)protectCorner.Parent=protectBtn local protectStroke=Instance.new("UIStroke")protectStroke.Color=Color3.fromRGB(255,200,0)protectStroke.Thickness=2 protectStroke.Parent=protectBtn protectBtn.MouseButton1Click:Connect(function()if not SaitamaDetect.TeleportActive then StartSaitamaTeleport()else ShowNotification("传送已激活",Color3.fromRGB(255,200,0))end end)local statusLabel=Instance.new("TextLabel")statusLabel.Name="StatusLabel"statusLabel.Size=UDim2.new(1,-20,0,25)statusLabel.Position=UDim2.new(0,10,0.35,0)statusLabel.BackgroundTransparency=1 statusLabel.Text="检测到敌人"statusLabel.TextColor3=Color3.fromRGB(200,200,255)statusLabel.TextSize=12 statusLabel.Font=Enum.Font.Gotham statusLabel.Parent=frame frame.StatusLabel=statusLabel task.delay(30,function()if SaitamaDetect.PopupGUI then CloseSaitamaPopupUI()ShowNotification("弹窗已自动关闭（30秒），传送不受影响",Color3.fromRGB(200,200,200))end end)end
local function UpdateSaitamaPopupStatus(count)local gui=SaitamaDetect.PopupGUI if gui then local frame=gui:FindFirstChild("PopupFrame")if frame and frame:FindFirstChild("StatusLabel")then frame.StatusLabel.Text="检测到 "..count.." 名玩家开启大招"end end end
local function CheckSaitamaUsers()if not SaitamaDetect.Enabled then if SaitamaDetect.PopupGUI then CloseSaitamaPopupUI()ShowNotification("大招检测已关闭",Color3.fromRGB(255,100,0))end StopSaitamaTeleport()ClearSaitamaHighlights()SaitamaDetect.WarnedPlayers={} return end local live=Workspace:FindFirstChild("Live")if not live then if SaitamaDetect.PopupGUI then CloseSaitamaPopupUI()end ClearSaitamaHighlights()return end local currentUsers={}for _,child in ipairs(live:GetChildren())do if child:IsA("Model")or child:IsA("Folder")then local counter=child:FindFirstChild("Counter")if counter then local playerName=child.Name local plr=Players:FindFirstChild(playerName)if plr and plr~=player then local char=plr.Character if char then table.insert(currentUsers,{Player=plr,Character=char})end end end end end ClearSaitamaHighlights()for _,user in ipairs(currentUsers)do local char=user.Character local highlight=Instance.new("Highlight")highlight.Parent=char highlight.OutlineColor=Color3.fromRGB(255,0,0)highlight.FillColor=Color3.fromRGB(255,0,0)highlight.FillTransparency=0.5 highlight.Adornee=char local head=char:FindFirstChild("Head")or char:FindFirstChild("HumanoidRootPart")local billboard=Instance.new("BillboardGui")billboard.Parent=head billboard.Size=UDim2.new(0,220,0,40)billboard.Adornee=head billboard.AlwaysOnTop=true local label=Instance.new("TextLabel")label.Parent=billboard label.Size=UDim2.new(1,0,1,0)label.BackgroundTransparency=1 label.Text="⚠️ 琦玉大招已开启 ⚠️"label.TextColor3=Color3.fromRGB(255,50,50)label.TextScaled=true label.Font=Enum.Font.GothamBold label.TextStrokeTransparency=0.4 table.insert(SaitamaDetect.DetectedPlayers,{Player=user.Player,Highlight=highlight,Billboard=billboard})end local hasNew=false for _,user in ipairs(currentUsers)do local name=user.Player.Name if not SaitamaDetect.WarnedPlayers[name]then SaitamaDetect.WarnedPlayers[name]=true hasNew=true end end if hasNew then if not SaitamaDetect.PopupGUI then CreateSaitamaPopup()end ShowNotification("检测到 "..#currentUsers.." 名玩家开启琦玉大招！",Color3.fromRGB(255,200,0))end if SaitamaDetect.PopupGUI then UpdateSaitamaPopupStatus(#currentUsers)end local toRemove={}for name,_ in pairs(SaitamaDetect.WarnedPlayers)do local stillThere=false for _,user in ipairs(currentUsers)do if user.Player.Name==name then stillThere=true break end end if not stillThere then table.insert(toRemove,name)end end for _,name in ipairs(toRemove)do SaitamaDetect.WarnedPlayers[name]=nil end end
local SaitamaCheckConnection local function StartSaitamaCheck()if SaitamaCheckConnection then return end SaitamaCheckConnection=RunService.Heartbeat:Connect(CheckSaitamaUsers)end
