local playersService = game:GetService("Players")
local localPlayer = playersService.LocalPlayer
local baseFolder = "ZKAYHub"
local userFolder = "ZKAYHub/PublicFarm/"..localPlayer.Name
local settingsPath = userFolder.."/settings.json"

local function makeFolders()
	if not isfolder(baseFolder) then makefolder(baseFolder) end
	if not isfolder(userFolder) then makefolder(userFolder) end
end

local defaultSettings = { country = countries[1], hopOnCount = "1000" }
local farmSettings = table.clone(defaultSettings)

local function loadSettings()
	makeFolders()
	if not isfile(settingsPath) then return end
	local readOk, fileContent = pcall(readfile, settingsPath)
	if not readOk then warn("[ZKAYHub] Failed to read settings file:", fileContent) return end
	local decodeOk, decoded = pcall(httpService.JSONDecode, httpService, fileContent)
	if not decodeOk or type(decoded)~="table" then warn("[ZKAYHub] Failed to decode settings file, using defaults") return end
	for key, value in pairs(decoded) do
		if key=="hopOnCount" and tonumber(value) and tonumber(value)<=500 then farmSettings[key]="1000"
		else farmSettings[key]=value end
	end
end
loadSettings()

