-- 按钮悬停效果
local function setupButtonHover(button, baseColor, hoverColor)
	button.MouseEnter:Connect(function()
		createTween(button, {BackgroundColor3 = hoverColor}, 0.15):Play()
	end)
	button.MouseLeave:Connect(function()
		createTween(button, {BackgroundColor3 = baseColor}, 0.15):Play()
	end)
end
setupButtonHover(exitButton, Color3.fromRGB(35, 37, 50), Color3.fromRGB(50, 52, 70))
setupButtonHover(blackButton, Color3.fromRGB(35, 37, 50), Color3.fromRGB(50, 52, 70))

-- ===== UI拖动功能 =====
local dragging, dragInput, dragStart, startPos = false, nil, nil, nil

titleBar.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		dragging = true
		dragStart = input.Position
		startPos = mainFrame.Position
		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then
				dragging = false
			end
		end)
	end
end)

titleBar.InputChanged:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
		dragInput = input
	end
end)

game:GetService("UserInputService").InputChanged:Connect(function(input)
	if input == dragInput and dragging then
		local delta = input.Position - dragStart
		local newPos = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		mainFrame.Position = newPos
		glowContainer.Position = newPos
	end
end)

-- ===== Toggle开关逻辑 =====
local function updateToggleVisuals(enabled)
	if enabled then
		createTween(toggleContainer, {BackgroundColor3 = Color3.fromRGB(70, 200, 130)}, 0.2):Play()
		createTween(toggleKnob, {Position = UDim2.new(0, 29, 0.5, -10)}, 0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
		createTween(toggleGlow, {BackgroundTransparency = 0.7}, 0.2):Play()
		toggleStatus.Text = "ON"
		toggleStatus.TextColor3 = Color3.fromRGB(70, 200, 130)
	else
		createTween(toggleContainer, {BackgroundColor3 = Color3.fromRGB(45, 47, 60)}, 0.2):Play()
		createTween(toggleKnob, {Position = UDim2.new(0, 3, 0.5, -10)}, 0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
		createTween(toggleGlow, {BackgroundTransparency = 1}, 0.2):Play()
		toggleStatus.Text = "OFF"
		toggleStatus.TextColor3 = Color3.fromRGB(200, 70, 80)
	end
end

-- 定义 setFarmState
local function setFarmState(enabled)
	farmEnabled = enabled
	updateToggleVisuals(enabled)
	if not enabled then
		pcall(function()
			local character = localPlayer.Character
			local rootPart = character and character:FindFirstChild("HumanoidRootPart")
			if rootPart then rootPart.CFrame = CFrame.new(-42,1855,25227) end
		end)
	end
end

-- 初始化Toggle状态
updateToggleVisuals(farmEnabled)

-- Toggle点击事件
toggleContainer.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		setFarmState(not farmEnabled)
	end
end)
toggleKnob.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		setFarmState(not farmEnabled)
	end
end)
