local lastHealth = 100
local healthChangedConn, renderSteppedConn, characterAddedConn = nil, nil, nil

local function onCharacterAdded(character)
	if not character then return end
	local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid",3)
	local rootPart = character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart",3)
	if not humanoid or not rootPart then return end
	lastHealth = humanoid.Health
	if healthChangedConn then healthChangedConn:Disconnect(); healthChangedConn=nil end
	if renderSteppedConn then renderSteppedConn:Disconnect(); renderSteppedConn=nil end
	renderSteppedConn = runService.RenderStepped:Connect(function()
		local rootPart2 = character:FindFirstChild("HumanoidRootPart")
		if rootPart2 then lastHealth = humanoid.Health; killFloorPart.CFrame = CFrame.new(rootPart2.Position.X,-10008,rootPart2.Position.Z) end
	end)
	healthChangedConn = humanoid.HealthChanged:Connect(function(newHealth)
		local rootPart2 = character:FindFirstChild("HumanoidRootPart")
		if newHealth <= 0 and rootPart2 and rootPart2.CFrame.Y <= 0 then humanoid.Health = lastHealth end
	end)
end
onCharacterAdded(localPlayer2.Character)
characterAddedConn = localPlayer2.CharacterAdded:Connect(function(newCharacter) task.wait(0.1); onCharacterAdded(newCharacter) end)

local connections = {}
local ownedFolders = setmetatable({}, {__mode="k"})
local function ensureMovingExclusion(character)
	if not character then return nil end
	local existingFolder = character:FindFirstChild("MovingExclusion")
	if existingFolder then return existingFolder end
	local folder = Instance.new("Folder")
	folder.Name = "MovingExclusion"
	pcall(function() folder:SetAttribute("ZKAYOwned", true) end)
	folder.Parent = character
	ownedFolders[folder] = true
	return folder
end
local function hookMovingExclusion(character)
	if not character then return end
	ensureMovingExclusion(character)
	local childRemovedConn = character.ChildRemoved:Connect(function(child)
		if child.Name == "MovingExclusion" then task.defer(ensureMovingExclusion, character) end
	end)
	table.insert(connections, childRemovedConn)
end
hookMovingExclusion(localPlayer2.Character)
table.insert(connections, localPlayer2.CharacterAdded:Connect(function(newCharacter) task.wait(0.1); hookMovingExclusion(newCharacter) end))

