-- ========== 性能优化与反检测 ==========
local desyncProcessing = false
local desyncHeartbeat = runService.Heartbeat:Connect(function()
	if not farmEnabled then return end
	-- [全局虚空] 不再清除 desync，isUlted/isTeleporting 时仅暂停 CFrame 偏移
	local desyncActive = getgenv().desync ~= nil
	if not desyncActive then return end
	if desyncProcessing then return end
	desyncProcessing = true
	local myChar = localPlayer2.Character
	local myHumanoid = myChar and myChar:FindFirstChildOfClass("Humanoid")
	local myRootPart = myChar and myChar:FindFirstChild("HumanoidRootPart")
	if not myChar or not myHumanoid or not myRootPart then desyncProcessing=false return end
	if myHumanoid.Health <= 0 then desyncProcessing=false return end
	local myRootCFrame = myRootPart.CFrame
	local myVelocity = myRootPart.Velocity
	local currentCamera = workspace.CurrentCamera
	local desyncCFrame = getgenv().desync and getgenv().desync.CFrame or nil
	-- isUlted 或 isTeleporting 时使用当前位置，避免干扰大招/传送逻辑
	local effectiveDesyncCFrame = desyncCFrame
	if isUlted or isTeleporting then
		effectiveDesyncCFrame = myRootCFrame
	end
	if effectiveDesyncCFrame then
		if currentCamera then myChar:SetAttribute("NoHeadLerp", true) end
		if currentlyTargeting and targetCFrame then myRootPart.CFrame = targetCFrame else myRootPart.CFrame = effectiveDesyncCFrame end
	end
	runService.RenderStepped:Wait()
	if currentCamera then myChar:SetAttribute("NoHeadLerp", false) end
	if effectiveDesyncCFrame then
		if currentlyTargeting and targetCFrame then
			myRootPart.CFrame = targetCFrame
		elseif currentCamera and userInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
			local value = currentCamera.CFrame.LookVector
			local var = Vector3.new(value.X, 0, value.Z)
			if var.Magnitude > 0.001 then myRootPart.CFrame = CFrame.new(myRootCFrame.Position, myRootCFrame.Position + var)
			else myRootPart.CFrame = myRootCFrame end
		else myRootPart.CFrame = myRootCFrame end
	end
	myRootPart.Velocity = myVelocity
	desyncProcessing = false
end)

task.spawn(function()
	local function fn(arg)
		repeat task.wait() until (localPlayer2.Character == arg) and arg:FindFirstChild("HumanoidRootPart") and arg:FindFirstChildOfClass("Humanoid")
		if localPlayer2.Character ~= arg then return end
		local var = arg:FindFirstChild("HumanoidRootPart")
		task.spawn(function()
			while task.wait() and (not localPlayer2.Character or localPlayer2.Character == arg) do
				if getgenv().desync and not arg:FindFirstChild("AbsoluteImmortal") then
					local list = {}
					local afterimageOk, afterimageClone = pcall(function() return replicatedStorage.Resources.NinjaUlt.Afterimage_Despawn:Clone() end)
					local vanishingOk, vanishingClone = pcall(function() return replicatedStorage.Resources.VanishingKick.tpthing:Clone() end)
					if afterimageOk and afterimageClone then afterimageClone.Parent=var; list[1]=afterimageClone; for _,val in pairs(afterimageClone:GetChildren()) do if val:IsA("ParticleEmitter") then val.Enabled=true; val.Rate=100 end end end
					if vanishingOk and vanishingClone then vanishingClone.Parent=var; list[2]=vanishingClone; vanishingClone.Enabled=true; vanishingClone.Rate=100 end
					repeat if list[1] and list[1].Parent then list[1].CFrame = var.CFrame end; runService.RenderStepped:Wait() until not getgenv().desync or arg:FindFirstChild("AbsoluteImmortal")
					for _,val in pairs(list) do pcall(function() val:Destroy() end) end
				end
			end
		end)
		task.spawn(function()
			for _,val in pairs(arg:GetDescendants()) do
				if val:IsA("BasePart") and val ~= var and val.Transparency ~= 1 and not val.Name:lower():find("hitbox") then
					task.spawn(function()
						while task.wait() and (not localPlayer2.Character or localPlayer2.Character == arg) do
							if val and (getgenv().desync and not arg:FindFirstChild("AbsoluteImmortal")) then
								val.Transparency = 0.5
								repeat runService.RenderStepped:Wait() until (not getgenv().desync or arg:FindFirstChild("AbsoluteImmortal")) or (localPlayer2.Character and localPlayer2.Character ~= arg)
								val.Transparency = 0
							end
						end
					end)
				end
			end
		end)
	end
	if localPlayer2.Character then task.spawn(fn, localPlayer2.Character) end
	localPlayer2.CharacterAdded:Connect(function(arg) task.spawn(fn, arg) end)
end)

