local optimizers = {}
optimizers[1] = function()
	local trailColor = Color3.fromRGB(0,85,190)
	local function styleTrail(instance)
		if instance:IsA("Trail") then instance.Color=ColorSequence.new(trailColor); instance.Texture=""; instance.LightEmission=0.8
		elseif instance:IsA("ParticleEmitter") then instance.Color=ColorSequence.new(trailColor); instance.LightEmission=0.75 end
	end
	local function styleCharacterFX(character)
		for _,child in ipairs(character:GetDescendants()) do if child:IsA("Trail") or child:IsA("ParticleEmitter") then styleTrail(child) end end
		safeConnect(character.DescendantAdded, function(newDescendant) if newDescendant:IsA("Trail") or newDescendant:IsA("ParticleEmitter") then styleTrail(newDescendant) end end)
	end
	if localPlayer2.Character then styleCharacterFX(localPlayer2.Character) end
	safeConnect(localPlayer2.CharacterAdded, styleCharacterFX)
end
