-- ========== 第二部分：战斗逻辑、切换、循环 ==========
local desyncActive = false

local function getCharacter(input)
	if typeof(input) == "Instance" then
		if input:IsA("Player") then return input.Character
		elseif input:IsA("Model") then return input end
	end
	return nil
end
local function getRootPart(model) return model and model:FindFirstChild(("HumanoidRoot".."Part")) or nil end
local function getHumanoid(model) return model and model:FindFirstChildOfClass("Humanoid") or nil end
local function getOtherPlayers()
	local playersList = playersService2:GetPlayers()
	local selfIndex = table.find(playersList, localPlayer2)
	if selfIndex then table.remove(playersList, selfIndex) end
	return playersList
end
local function hasAnimation(humanoid, animIdPattern)
	if not humanoid then return false end
	for _, track in pairs(humanoid:GetPlayingAnimationTracks()) do
		if track.Animation.AnimationId:match(animIdPattern) then return true end
	end
	return false
end

local function findWeakestTarget()
	local weakestPlayer, lowestHealth = nil, math.huge
	for _, player in ipairs(playersService2:GetPlayers()) do
		if player == localPlayer2 or player == currentTarget then continue end
		local char = player.Character
		if not char then continue end
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then continue end
		local humanoid = char:FindFirstChildOfClass("Humanoid")
		if not humanoid or not humanoid.Health then continue end
		local torso = char:FindFirstChild("Torso")
		if not torso or torso.Transparency == 1 then continue end
		if hasAnimation(humanoid, "15128849047") then continue end
		if char:FindFirstChildWhichIsA("ForceField") then continue end
		if (char:GetAttribute("Ulted") and (char:GetAttribute("Character")=="Batter" or char:GetAttribute("Character")=="Bald")) or char:FindFirstChild("Counter") then continue end
		local rootPos = char.HumanoidRootPart.Position
		if not (rootPos.X >= -500 and rootPos.X <= 800 and rootPos.Z >= -600 and rootPos.Z <= 700) then continue end
		local health = humanoid.Health
		if health > 0 and health < lowestHealth then lowestHealth = health; weakestPlayer = player end
	end
	return weakestPlayer
end

