			end)
			return conn
		end
		local ultHeartbeatConn, ultRenderConn, myRoot, targetRoot, ultFinished = nil, nil, nil, nil, false
		local function detachPhysics()
			if ultHeartbeatConn then ultHeartbeatConn:Disconnect(); ultHeartbeatConn=nil end
			if ultRenderConn then ultRenderConn:Disconnect(); ultRenderConn=nil end
			if sethiddenproperty then
				if myRoot and myRoot.Parent then pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", nil) end) end
				if targetRoot and targetRoot.Parent then pcall(function() sethiddenproperty(targetRoot, "PhysicsRepRootPart", nil) end) end
			end
			if myRoot and myRoot.Parent then
				myRoot.CFrame = CFrame.new(myRoot.Position)
				myRoot.AssemblyLinearVelocity = Vector3.zero; myRoot.AssemblyAngularVelocity = Vector3.zero
				pcall(function() myRoot.Velocity=Vector3.zero end); pcall(function() myRoot.RotVelocity=Vector3.zero end)
				local myHumanoid = myRoot.Parent:FindFirstChildOfClass("Humanoid")
				if myHumanoid then pcall(function() myHumanoid.AutoRotate = true end) end
			end
