			if ultHeartbeatConn then ultHeartbeatConn:Disconnect(); ultHeartbeatConn=nil end
			if myRoot and myRoot.Parent then
				myRoot.AssemblyLinearVelocity=Vector3.zero; myRoot.AssemblyAngularVelocity=Vector3.zero
