					heartbeatConn:Disconnect()
					if ultHeartbeatConn == heartbeatConn then ultHeartbeatConn = nil end
					if sethiddenproperty then
						if myRoot2 and myRoot2.Parent then pcall(function() sethiddenproperty(myRoot2,"PhysicsRepRootPart",nil) end) end
						if targetRoot2 and targetRoot2.Parent then pcall(function() sethiddenproperty(targetRoot2,"PhysicsRepRootPart",nil) end) end
					end
					if myRoot2 and myRoot2.Parent then
						myRoot2.AssemblyLinearVelocity=Vector3.zero; myRoot2.AssemblyAngularVelocity=Vector3.zero
						pcall(function() myRoot2.Velocity=Vector3.zero end); pcall(function() myRoot2.RotVelocity=Vector3.zero end)
					end
					return
				end
				myRoot2.CFrame = targetRoot2.CFrame * CFrame.new(0,0,5)
				myRoot2.AssemblyLinearVelocity = Vector3.zero; myRoot2.AssemblyAngularVelocity = Vector3.zero
				if sethiddenproperty then pcall(function() sethiddenproperty(myRoot2,"PhysicsRepRootPart",targetRoot2) end) end
			end)
			ultHeartbeatConn = heartbeatConn
		end
