					pcall(function() localPlayer2.Character.HumanoidRootPart.CFrame = CFrame.new(150,441,32) end)
					ultKeyReady = true
					pcall(function() localPlayer2.Character.HumanoidRootPart.CFrame = CFrame.new(0,-29000,0) end)
					task.wait(1.5)
					pcall(function() localPlayer2.Character.HumanoidRootPart.CFrame = CFrame.new(150,441,32) end)
					isTeleporting = false
					task.wait(5)
					pcall(function() localPlayer2.Character.HumanoidRootPart.CFrame = CFrame.new(-42,1855,25227) end)
				end)
				local freezeConn = freezeVelocityWhile(function() return ultActive end)
				local doneTargets = {}
				local currentTarget2 = nil
				local targetSince = tick()
				local savedMyCFrame = nil
				do
					local myChar2 = getCharacter(localPlayer2)
					local myRoot2 = myChar2 and getRootPart(myChar2)
					if myRoot2 then savedMyCFrame = myRoot2.CFrame end
				end
				local function resolveCharacter(input)
					if not input then return nil end
					if input:IsA("Player") then return getCharacter(input) end
					return nil
				end
				local function getHumanoidOf(input) return getHumanoid(resolveCharacter(input)) end
				local function getRootOf(input) return getRootPart(resolveCharacter(input)) end
				local function isInvulnerable(char)
					if not char then return false end
					return char:FindFirstChild("ForceField") or char:FindFirstChild("AbsoluteImmortal") or char:FindFirstChild("BeingGrabbed") or char:FindFirstChild("HunterCounter") or char:FindFirstChild("AtomicCounter") or char:FindFirstChild("forcefield")
				end
				local function isTargetInvalid(target)
					local targetChar = resolveCharacter(target)
					local targetHumanoid = targetChar and getHumanoid(targetChar)
					local targetRoot2 = targetChar and getRootPart(targetChar)
					if not targetChar or not targetHumanoid or not targetRoot2 then return true end
					if targetHumanoid.Health <= 0 then return true end
					if target:IsA("Player") then
						if isInvulnerable(targetChar) or targetChar:FindFirstChild("Counter") or hasAnimation(targetHumanoid,"15128849047") then return true end
						if targetChar:GetAttribute("Ulted") and targetChar:GetAttribute("Character")=="Batter" then return true end
					end
					local targetRootPos = targetChar.HumanoidRootPart.Position
					if not (targetRootPos.X >= -500 and targetRootPos.X <= 800 and targetRootPos.Z >= -600 and targetRootPos.Z <= 700) then return true end
					return false
				end
				local function isCounteringTarget(target)
					local targetHumanoid = getHumanoidOf(target)
					return targetHumanoid and (hasAnimation(targetHumanoid,"18896222853") or hasAnimation(targetHumanoid,"137434257516014"))
				end
				local function hasCounter(player)
					if not player or not player:IsA("Player") then return false end
					local char = getCharacter(player)
					local humanoid2 = char and getHumanoid(char)
					if not char or not humanoid2 then return false end
					if humanoid2.Health <= 0 then return false end
					if hasAnimation(humanoid2,"15128849047") then return false end
					return isInvulnerable(char)
				end
				local function findWeakestDummy()
					local dummy = workspace.Live:FindFirstChild("Weakest Dummy")
					if not dummy then return nil end
					local dummyHumanoid = getHumanoid(dummy)
					if not dummyHumanoid or dummyHumanoid.Health <= 0 then return nil end
					return dummy
				end
				local function findNextTarget(excludedTarget)
					local hunterTargets, otherTargets = {}, {}
					for _, player in pairs(getOtherPlayers()) do
						if player == excludedTarget or doneTargets[player] then continue end
						local root = getRootOf(player)
						if not isTargetInvalid(player) and not isCounteringTarget(player) and root then
							if isHunterClass(player) then table.insert(hunterTargets, player) else table.insert(otherTargets, player) end
						end
					end
					if #hunterTargets > 0 then return hunterTargets[math.random(1,#hunterTargets)] end
					if #otherTargets > 0 then return otherTargets[math.random(1,#otherTargets)] end
					local dummy = findWeakestDummy()
					if dummy and dummy ~= excludedTarget and not doneTargets[dummy] then return dummy end
					return nil
				end
				local function restoreMyPosition()
					if not savedMyCFrame then return end
					local myChar2 = getCharacter(localPlayer2)
					local myRoot2 = myChar2 and getRootPart(myChar2)
					if myRoot2 then pcall(function() myRoot2.CFrame = savedMyCFrame end) end
				end
				local function restoreAutoRotate()
					local myChar2 = getCharacter(localPlayer2)
					local myHumanoid = myChar2 and getHumanoid(myChar2)
					if myHumanoid then pcall(function() myHumanoid.AutoRotate = true end) end
				end
				local function anyCounteringPlayer()
					for _, player in pairs(getOtherPlayers()) do
						if doneTargets[player] then continue end
						if hasCounter(player) then return true end
					end
					return false
				end
				local cleanedUp = false
				local function endUlt()
					if cleanedUp then return end
					cleanedUp = true
					detachPhysics(); restoreAutoRotate()
					if _ffWatchConn then pcall(function() _ffWatchConn:Disconnect() end) end
					if _dummyRespawnConn then pcall(function() _dummyRespawnConn:Disconnect() end) end
					if _currentTargetAnimConn then pcall(function() _currentTargetAnimConn:Disconnect() end); _currentTargetAnimConn=nil end
					ultActive = false
					detachPhysicsAll()
				end
				local targetAnimConn = nil
				local function setTarget(target)
					if targetAnimConn then pcall(function() targetAnimConn:Disconnect() end); targetAnimConn=nil end
					detachPhysics()
					currentTarget2 = target; targetSince = tick()
					if target then
						local myChar2 = getCharacter(localPlayer2)
						local myRoot2 = myChar2 and getRootPart(myChar2)
						local targetRoot2 = getRootOf(target)
						if myRoot2 and targetRoot2 then
							attachPhysicsTo(myRoot2, targetRoot2)
							local targetHumanoid = getHumanoidOf(target)
							if targetHumanoid then
								local targetAnimator = targetHumanoid:FindFirstChildOfClass("Animator")
								local animPlayedSignal = targetAnimator and targetAnimator.AnimationPlayed or targetHumanoid.AnimationPlayed
								targetAnimConn = animPlayedSignal:Connect(function(track2)
									local animId2 = track2.Animation.AnimationId
									if animId2:match("18896222853") or animId2:match("137434257516014") then
										if not ultActive then return end
										local currentVictim = currentTarget2
										if not currentVictim then return end
										doneTargets[currentVictim] = true
										detachPhysics()
										local nextTarget = findNextTarget(currentVictim)
										if nextTarget then
											setTarget(nextTarget)
											if findNextTarget(nextTarget) == nil and not anyCounteringPlayer() then task.wait(0.1); doneTargets[nextTarget]=true; _everybodyDone=true; endUlt() end
										else
											if anyCounteringPlayer() then detachPhysics(); currentTarget2=nil else _everybodyDone=true; endUlt() end
										end
									end
								end)
							end
						end
					end
				end
				local dummyAddedConn = workspace.Live.ChildAdded:Connect(function(newChild) if newChild.Name=="Weakest Dummy" then doneTargets[newChild]=nil end end)
				local respawnScanConn = runService.RenderStepped:Connect(function()
					for _, player in pairs(getOtherPlayers()) do
						if not doneTargets[player] then continue end
						local char = getCharacter(player)
						local humanoid2 = char and getHumanoid(char)
						if char and humanoid2 and humanoid2.Health > 0 and not isInvulnerable(char) then
							doneTargets[player] = nil
							if not currentTarget2 then setTarget(player) end
						end
					end
				end)
				local ultEnded = false
				local firstTarget = findNextTarget(nil)
				if firstTarget then
					setTarget(firstTarget)
					if findNextTarget(firstTarget) == nil then task.wait(0.1); doneTargets[firstTarget]=true; ultEnded=true; endUlt(); return end
				end
				while track.IsPlaying and tick() < ultDeadline do
					if ultFinished then ultEnded=true; endUlt(); break end
					runService.Heartbeat:Wait()
					local now = tick()
					local needRetarget = false
					if not currentTarget2 then needRetarget = true
					else
						if isTargetInvalid(currentTarget2) then
							if not hasCounter(currentTarget2) then doneTargets[currentTarget2]=true end
							needRetarget = true
						elseif now - targetSince >= 0.8 then doneTargets[currentTarget2]=true; needRetarget=true end
					end
					if needRetarget then
						local nextTarget = findNextTarget(currentTarget2)
						if not nextTarget then
							if anyCounteringPlayer() then detachPhysics(); currentTarget2=nil else ultEnded=true; endUlt(); break end
						else
							setTarget(nextTarget)
							if findNextTarget(nextTarget) == nil and not anyCounteringPlayer() then task.wait(0.1); doneTargets[nextTarget]=true; ultEnded=true; endUlt(); break end
						end
					end
				end
				endUlt()
			end)
		end
	end)
end

