local function queueTeleportScript()
	local teleportCode = string.format('getgenv().TimeFarmed=%d\010getgenv().SavedCarriedKills=%d\010getgenv().SavedEmotes=%d\010getgenv().SavedSessionStart=%d\010getgenv().renderEnabled=%s\010getgenv().PYKey = %q\010', getgenv().TimeFarmed, carriedKills, savedEmotes, sessionStartTime, tostring(getgenv().renderEnabled or false), tostring(getgenv().PYKey or ""))
	pcall(queue_on_teleport, teleportCode)
