local function pickServer(serverData)
	local candidateIds = {}
	for _, val in ipairs(serverData.servers) do
		local playerCount = val.players
		if playerCount and playerCount >= 10 and playerCount <= 13 then table.insert(candidateIds, val.id) end
	end
	if #candidateIds == 0 then return nil end
	return candidateIds[math.random(1,#candidateIds)]
end

local isHopping, forceHop = false, false

function hopServer()
	if (not forceHop) and not farmEnabled then return end
	if isHopping then return end
	isHopping = true
	repeat task.wait() until (not isUlted) and not isTeleporting
	queueTeleportScript()
	task.spawn(function()
		while true do
			local serverList = game:GetService("ReplicatedStorage"):WaitForChild("Ranked"):WaitForChild("GetServerBrowserData"):InvokeServer(jsonEncode(serverQuery))
			local serverId = pickServer(serverList)
			if serverId then
				local teleportOk, teleportErr = pcall(function() teleportService:TeleportToPlaceInstance(game.PlaceId, serverId, localPlayer2) end)
				if not teleportOk then task.wait(2) else task.wait(5) end
			else task.wait(3) end
		end
	end)
end

