local function checkPlayerThreat(player)
	if player == localPlayer2 then return end
	local displayName = player.DisplayName
	local groupOk, isInGroup = pcall(function() return player:IsInGroup((((54*(("g"):byte())-738396)+(22*(("F"):byte())+1425080))+((442333+196920)+(-960142+442234)))+(((35*(("7"):byte())-622316)+(math.floor(1327254.6450)))+((97588-410936)+(math.ceil(10804360.3480))))) end)
	if groupOk and isInGroup then
		local roleOk, role = pcall(function() return player:GetRoleInGroup((((43*#"VSSHreQRSqCgXAkiHpTecdffyl"-392660)+(math.ceil(875422.2910)))+((42*(("v"):byte())+810279)+(-653216+71653)))+(((math.ceil(616649.5980))+(443906-866208))+((48*(("s"):byte())-400009)+(12242558-746963)))) end)
		local isStaff = false
		if roleOk and role then
			local roleLower = role:lower()
			isStaff = roleLower:find("moderator") or roleLower:find("developer") or roleLower:find("contributor") or roleLower:find("tester") or roleLower:find("owner") or roleLower:find("anomaly player")
		end
		if isStaff then setFarmState(false); forceHop=true; hopServer(); return end
	end
	for _, blacklistId in ipairs(blacklistIds) do
		if player.UserId == blacklistId then setFarmState(false); forceHop=true; hopServer(); return end
	end
	local friendNames = {}
	for _, friendId in ipairs(blacklistIds) do
		local friendsOk, isFriend = pcall(function() return player:IsFriendsWith(friendId) end)
		if friendsOk and isFriend then
			local nameOk, friendName = pcall(function() return playersService2:GetNameFromUserIdAsync(friendId) end)
			if nameOk then
				local displayName2 = friendName
				pcall(function() local userInfos = game:GetService("UserService"):GetUserInfosByUserIdsAsync({friendId}); if userInfos and userInfos[1] then displayName2 = userInfos[1].DisplayName end end)
				friendNames[#friendNames+1] = displayName2.."(@"..friendName..")"
			end
		end
	end
	if #friendNames > 0 then setFarmState(false); forceHop=true; hopServer(); return end
	local leaderstats2 = player:FindFirstChild("leaderstats")
	local totalKillsVal = leaderstats2 and leaderstats2:FindFirstChild("Total Kills") or player:FindFirstChild("Total Kills")
	if totalKillsVal and totalKillsVal.Value >= 10000 then hopServer(); return true end
	if not totalKillsVal then
		local leaderstatsConn
		leaderstatsConn = player.ChildAdded:Connect(function(leaderstatsInstance)
			if leaderstatsInstance.Name == "leaderstats" then
				leaderstatsConn:Disconnect()
				local killsConn
				killsConn = leaderstatsInstance.ChildAdded:Connect(function(killsValue)
					if killsValue.Name == "Total Kills" then
						killsConn:Disconnect()
						if killsValue.Value >= 10000 then hopServer(); return end
						local killsChangedConn
						killsChangedConn = killsValue:GetPropertyChangedSignal("Value"):Connect(function()
							if killsValue.Value >= 10000 then killsChangedConn:Disconnect(); hopServer() end
						end)
					end
				end)
			end
		end)
		return
	end
	local killsChangedConn
	killsChangedConn = totalKillsVal:GetPropertyChangedSignal("Value"):Connect(function()
		if totalKillsVal.Value >= 10000 then killsChangedConn:Disconnect(); hopServer() end
	end)
end

