            stroke.Transparency = 0.55
            stroke.Thickness = 1.3
            return btn
        end

        local function applyStroke(btn, thickness, transparency)
            local old = btn:FindFirstChildOfClass("UIStroke")
            if old then old:Destroy() end
            local s = Instance.new("UIStroke", btn)
            s.Color = Color3.fromRGB(255, 255, 255)
            s.Thickness = thickness or 2
            s.Transparency = transparency or 0.15
            s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            return btn
        end

        local function bindTap(btn, onTap)
            local pressStart, moved
            btn.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    pressStart = i.Position; moved = false
                    btn.BackgroundTransparency = 0.4
                end
            end)
            btn.InputChanged:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch and pressStart and not moved then
                    if (i.Position - pressStart).Magnitude > 14 then
                        moved = true
                        btn.BackgroundTransparency = 0.72
                    end
                end
            end)
            btn.InputEnded:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.Touch then return end
                btn.BackgroundTransparency = 0.72
                if pressStart and not moved then onTap() end
                pressStart = nil
            end)
        end

        local function makeHold(btn, onDown, onUp)
            local active = false
            btn.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    active = true
                    btn.BackgroundTransparency = 0.4
                    if onDown then onDown() end
                end
            end)
            btn.InputEnded:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    active = false
                    btn.BackgroundTransparency = 0.72
                    if onUp then onUp() end
                end
            end)
            btn.InputChanged:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch and active then
                    local ap = btn.AbsolutePosition
                    local as = btn.AbsoluteSize
                    if not (i.Position.X >= ap.X - 30 and i.Position.X <= ap.X + as.X + 30
                    and i.Position.Y >= ap.Y - 30 and i.Position.Y <= ap.Y + as.Y + 30) then
                        active = false
                        btn.BackgroundTransparency = 0.72
                        if onUp then onUp() end
                    end
                end
            end)
        end

