            UDim2.fromScale(0.52, 0.86), UDim2.fromScale(0.42, 0.13), "锁定", 12)

        local dragY, dragX = nil, nil
        local dirTargetY, dirTargetX = 0, 0

        local function currentHand()
            if selHand == "L" then return handDir.L end
            return handDir.R
        end

        local function refreshHandLbl()
            handLbl.Text = "控制手：" .. (selHand == "L" and "左手" or selHand == "R" and "右手" or "双手")
        end

        local function syncSliders()
            local hd = currentHand()
            dirTargetX = hd.x; dirTargetY = hd.y
            dirSliderX = hd.x; dirSliderY = hd.y
            sliderXKnob.Position = UDim2.new((hd.x * 0.5) + 0.5, 0, 0.5, 0)
            sliderYKnob.Position = UDim2.new((hd.y * 0.5) + 0.5, 0, 0.5, 0)
            dirLockBtn.Text = hd.locked and "已锁" or "锁定"
        end

        local function commitHand()
            local hd = currentHand()
            hd.x = dirSliderX
            hd.y = dirSliderY
        end

        bindTap(tagL, function()
            commitHand()
            selHand = "L"; refreshHandTags(); refreshHandLbl(); syncSliders()
        end)
        bindTap(tagR, function()
            commitHand()
            selHand = "R"; refreshHandTags(); refreshHandLbl(); syncSliders()
        end)
        bindTap(tagB, function()
            commitHand()
            selHand = "B"; refreshHandTags(); refreshHandLbl(); syncSliders()
        end)
        refreshHandLbl()
        syncSliders()

        local function updateSliderY(pos)
            local absPos = sliderYBar.AbsolutePosition
            local absSize = sliderYBar.AbsoluteSize
            local tt = math.clamp((pos.X - absPos.X) / absSize.X, 0, 1)
            sliderYKnob.Position = UDim2.new(tt, 0, 0.5, 0)
            dirTargetY = (tt - 0.5) * 2
        end
        local function updateSliderX(pos)
            local absPos = sliderXBar.AbsolutePosition
            local absSize = sliderXBar.AbsoluteSize
            local tt = math.clamp((pos.X - absPos.X) / absSize.X, 0, 1)
            sliderXKnob.Position = UDim2.new(tt, 0, 0.5, 0)
            dirTargetX = (tt - 0.5) * 2
        end

        UIS.TouchStarted:Connect(function(i)
            local p = i.Position
            local aY = sliderYBar.AbsolutePosition; local sY = sliderYBar.AbsoluteSize
            if p.X >= aY.X and p.X <= aY.X + sY.X and p.Y >= aY.Y and p.Y <= aY.Y + sY.Y then
                dragY = i; updateSliderY(p); return
            end
            local aX = sliderXBar.AbsolutePosition; local sX = sliderXBar.AbsoluteSize
            if p.X >= aX.X and p.X <= aX.X + sX.X and p.Y >= aX.Y and p.Y <= aX.Y + sX.Y then
                dragX = i; updateSliderX(p); return
            end
        end)
        UIS.TouchMoved:Connect(function(i)
            if i == dragY then updateSliderY(i.Position) end
            if i == dragX then updateSliderX(i.Position) end
        end)
        UIS.TouchEnded:Connect(function(i)
            if i == dragY then dragY = nil end
            if i == dragX then dragX = nil end
            commitHand()
        end)

        RunService.RenderStepped:Connect(function(dt)
            local kk = 1 - math.exp(-8 * dt)
            dirSliderY = dirSliderY + (dirTargetY - dirSliderY) * kk
            dirSliderX = dirSliderX + (dirTargetX - dirSliderX) * kk
            local hd = currentHand()
            hd.x = dirSliderX
            hd.y = dirSliderY
        end)

        local function fadeIn(guiObj)
