-- ===== 移速强制保持循环：每帧盯梢，服务器敢拉回就按回去 =====
-- 只在选择了非默认移速时工作；恢复默认后完全撒手，交给游戏自己管
RunService.Heartbeat:Connect(function()
    if selectedSpeed == DEFAULT_SPEED then return end
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 and hum.WalkSpeed ~= selectedSpeed then
        hum.WalkSpeed = selectedSpeed
    end
end)

-- ===== 自动跳跃核心（着地期间持续请求，空中零干预） =====
RunService.Heartbeat:Connect(function()
    if not getgenv().AutoJumpOn then return end
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 then return end

    if hum.FloorMaterial == Enum.Material.Air then return end

    if hum.EvaluateStateMachine then
        hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
        hum.Jump = true
        hum:ChangeState(Enum.HumanoidStateType.Jumping)
    else
        local jumpSpeed = (hum.JumpPower and hum.JumpPower > 0) and hum.JumpPower or 50
        root.AssemblyLinearVelocity = Vector3.new(
            root.AssemblyLinearVelocity.X, jumpSpeed, root.AssemblyLinearVelocity.Z
        )
    end
end)

