-- ============================================================
-- MM2 全功能系统（移植）
-- ============================================================

local LP = LocalPlayer

-- 连接追踪（用于 Ctrl+M 总开关）
local ActiveConnections = {
    RenderStepped = {},
    Stepped = {},
    Heartbeat = {},
    PlayerRemoving = {},
    ChildAdded = {},
}
local ScriptEnabled = true
local CtrlPressed = false

-- 角色名中英文映射
local RoleNames = {
    Murderer = "杀手",
    Sheriff = "警长",
    Innocent = "平民",
    Hero = "英雄"
}

-- ---------- MM2 角色数据 + ESP 系统（替换原 WX HUB 透视） ----------
local ESP = {
    Enabled = false,
    HighlightMurderer = false,
    HighlightInnocent = false,
    HighlightSheriff = false,
    NameESP = false,
    BoxESP = false,
    TracerESP = false,
    Alerts = true,
    Roles = {},
    Murder = nil, Sheriff = nil, Hero = nil,
    KnownMurderer = nil,
}

local ESPDrawings = {}

local function ESP_IsAlive(player)
    for name, data in pairs(ESP.Roles) do
        if player.Name == name then
            return not data.Killed and not data.Dead
        end
    end
    return false
end

local function ESP_CreateDrawings(player)
    local drawings = {}
    drawings.Box = Drawing.new("Square")
    drawings.Box.Visible = false
    drawings.Box.Color = Color3.new(1, 1, 1)
    drawings.Box.Thickness = 1
    drawings.Box.Filled = false

    drawings.Name = Drawing.new("Text")
    drawings.Name.Visible = false
    drawings.Name.Color = Color3.new(1, 1, 1)
    drawings.Name.Size = 16
    drawings.Name.Center = true
    drawings.Name.Outline = true

    drawings.Tracer = Drawing.new("Line")
    drawings.Tracer.Visible = false
    drawings.Tracer.Color = Color3.new(1, 1, 1)
    drawings.Tracer.Thickness = 1

    ESPDrawings[player] = drawings
end

for _, player in pairs(Players:GetPlayers()) do
    if player ~= LP then ESP_CreateDrawings(player) end
end

table.insert(ActiveConnections.ChildAdded, Players.PlayerAdded:Connect(function(player)
    ESP_CreateDrawings(player)
end))

function ESP_CreateHighlight(player)
    if ((player ~= LP) and player.Character and not player.Character:FindFirstChild("WXHUB_Highlight")) then
        local highlight = Instance.new("Highlight");
        highlight.Name = "WXHUB_Highlight"
        highlight.Parent = player.Character;
        highlight.Adornee = player.Character;
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
        return highlight;
    end
    return player.Character and player.Character:FindFirstChild("WXHUB_Highlight");
end

function ESP_RemoveAll()
    for _, player in pairs(Players:GetPlayers()) do
        if (player.Character and player.Character:FindFirstChild("WXHUB_Highlight")) then
            player.Character.WXHUB_Highlight:Destroy();
        end
        if ESPDrawings[player] then
            ESPDrawings[player].Box.Visible = false
            ESPDrawings[player].Name.Visible = false
            ESPDrawings[player].Tracer.Visible = false
        end
    end
end

function ESP_UpdateHighlights()
    for _, player in pairs(Players:GetPlayers()) do
        if ((player ~= LP) and player.Character) then
            local highlight = player.Character:FindFirstChild("WXHUB_Highlight");
            local drawings = ESPDrawings[player]

            local shouldHighlight = false;
            local color = Color3.new(0, 1, 0);

            if ((player.Name == ESP.Murder) and ESP_IsAlive(player) and (ESP.HighlightMurderer or ESP.NameESP or ESP.BoxESP or ESP.TracerESP)) then
                color = Color3.fromRGB(255, 0, 0);
                shouldHighlight = true;
            elseif ((player.Name == ESP.Sheriff) and ESP_IsAlive(player) and (ESP.HighlightSheriff or ESP.NameESP or ESP.BoxESP or ESP.TracerESP)) then
                color = Color3.fromRGB(0, 0, 255);
                shouldHighlight = true;
            elseif (ESP.HighlightInnocent and ESP_IsAlive(player) and (player.Name ~= ESP.Murder) and (player.Name ~= ESP.Sheriff) and (player.Name ~= ESP.Hero)) then
                color = Color3.fromRGB(0, 255, 0);
                shouldHighlight = true;
            elseif ((player.Name == ESP.Hero) and ESP_IsAlive(player) and not ESP_IsAlive(Players[ESP.Sheriff]) and (ESP.HighlightSheriff or ESP.NameESP or ESP.BoxESP or ESP.TracerESP)) then
                color = Color3.fromRGB(255, 250, 0);
                shouldHighlight = true;
            end

            if shouldHighlight then
                if highlight and (ESP.HighlightMurderer or ESP.HighlightSheriff or ESP.HighlightInnocent) then
                    highlight.FillColor = color;
                    highlight.OutlineColor = color;
                    highlight.Enabled = true;
                elseif not highlight and (ESP.HighlightMurderer or ESP.HighlightSheriff or ESP.HighlightInnocent) then
                    highlight = ESP_CreateHighlight(player);
                    if highlight then
                        highlight.FillColor = color;
                        highlight.OutlineColor = color;
                        highlight.Enabled = true;
                    end
                elseif highlight and not (ESP.HighlightMurderer or ESP.HighlightSheriff or ESP.HighlightInnocent) then
                    highlight.Enabled = false
                end

                if drawings then
                    local root = player.Character:FindFirstChild("HumanoidRootPart")
                    local head = player.Character:FindFirstChild("Head")
                    if root and head then
                        local pos, onScreen = CurrentCamera:WorldToViewportPoint(root.Position)
                        local headPos, headOnScreen = CurrentCamera:WorldToViewportPoint(head.Position + Vector3.new(0, 0.5, 0))
                        local legPos, legOnScreen = CurrentCamera:WorldToViewportPoint(root.Position - Vector3.new(0, 3, 0))

                        if onScreen then
                            if ESP.BoxESP then
                                drawings.Box.Size = Vector2.new(2000 / pos.Z, headPos.Y - legPos.Y)
                                drawings.Box.Position = Vector2.new(pos.X - drawings.Box.Size.X / 2, legPos.Y)
                                drawings.Box.Color = color
                                drawings.Box.Visible = true
                            else
                                drawings.Box.Visible = false
                            end

                            if ESP.NameESP then
                                drawings.Name.Text = player.Name
                                drawings.Name.Position = Vector2.new(headPos.X, headPos.Y - 20)
                                drawings.Name.Color = color
                                drawings.Name.Visible = true
                            else
                                drawings.Name.Visible = false
                            end

                            if ESP.TracerESP then
                                drawings.Tracer.From = Vector2.new(CurrentCamera.ViewportSize.X / 2, CurrentCamera.ViewportSize.Y)
                                drawings.Tracer.To = Vector2.new(pos.X, pos.Y)
                                drawings.Tracer.Color = color
                                drawings.Tracer.Visible = true
                            else
                                drawings.Tracer.Visible = false
                            end
                        else
                            drawings.Box.Visible = false
                            drawings.Name.Visible = false
                            drawings.Tracer.Visible = false
                        end
                    else
                        drawings.Box.Visible = false
                        drawings.Name.Visible = false
                        drawings.Tracer.Visible = false
                    end
                end
            else
                if highlight then highlight.Enabled = false end
                if drawings then
                    drawings.Box.Visible = false
                    drawings.Name.Visible = false
                    drawings.Tracer.Visible = false
                end
            end
        end
    end
end

local function ESP_UpdateRoles()
    local success, result = pcall(function()
        return ReplicatedStorage:FindFirstChild("GetPlayerData", true):InvokeServer();
    end);
    if success then
        ESP.Roles = result or {};
        for name, data in pairs(ESP.Roles) do
            if (data.Role == "Murderer") then
                ESP.Murder = name;
                if ESP.Alerts and ESP.KnownMurderer ~= name then
                    ESP.KnownMurderer = name
                    Notify("⚠️ 检测到杀手 ⚠️", name .. " 是本局的杀手！", 6)
                end
            elseif (data.Role == "Sheriff") then
                ESP.Sheriff = name;
            elseif (data.Role == "Hero") then
                ESP.Hero = name;
            end
        end
    end
end

-- 掉落枪高亮
local gunDropESPEnabled = false;

local function createGunDropHighlight(gunDrop)
    if (gunDropESPEnabled and gunDrop and not gunDrop:FindFirstChild("WXHUB_GunDropHighlight")) then
        local highlight = Instance.new("Highlight");
        highlight.Name = "WXHUB_GunDropHighlight";
        highlight.FillColor = Color3.fromRGB(255, 215, 0);
        highlight.OutlineColor = Color3.fromRGB(255, 165, 0);
        highlight.Adornee = gunDrop;
        highlight.Parent = gunDrop;
    end
end

local function updateGunDropESP()
    for _, child in pairs(workspace:GetDescendants()) do
        if child.Name == "GunDrop" then
            if gunDropESPEnabled then
                createGunDropHighlight(child)
            else
                if child:FindFirstChild("WXHUB_GunDropHighlight") then
                    child.WXHUB_GunDropHighlight:Destroy()
                end
            end
        end
    end
end

table.insert(ActiveConnections.ChildAdded, workspace.DescendantAdded:Connect(function(child)
    if child.Name == "GunDrop" then
        task.wait(1);
        updateGunDropESP();
    end
end));

-- ESP + 角色数据主循环
local roleUpdateAccumulator = 0
table.insert(ActiveConnections.RenderStepped, RunService.RenderStepped:Connect(function(dt)
    if not ScriptEnabled then return end
    roleUpdateAccumulator += dt
    if roleUpdateAccumulator >= 0.5 then
        roleUpdateAccumulator = 0
        ESP_UpdateRoles()
    end
    if ESP.Enabled then
        ESP_UpdateHighlights()
    end
end));

table.insert(ActiveConnections.PlayerRemoving, Players.PlayerRemoving:Connect(function(player)
    if ESPDrawings[player] then
        ESPDrawings[player].Box:Remove()
        ESPDrawings[player].Name:Remove()
        ESPDrawings[player].Tracer:Remove()
        ESPDrawings[player] = nil
    end
    if CurrentTarget == player then CurrentTarget = nil end
end));

-- ---------- 镜头自瞄 ----------
local AimbotConfig = {
    SmoothAim = false,
    Smoothness = 0.5
}
local isCameraLocked = false;
local isSpectating = false;
local lockedRole = nil;
local originalCameraType = Enum.CameraType.Custom;
local originalCameraSubject = nil;

local function GetTargetPosition()
    if not lockedRole then return nil; end
    local targetName = ((lockedRole == "警长") and ESP.Sheriff) or ESP.Murder;
    if not targetName then return nil; end
    local player = Players:FindFirstChild(targetName);
    if (not player or not ESP_IsAlive(player)) then return nil; end
    local character = player.Character;
    if not character then return nil; end
    local head = character:FindFirstChild("Head");
    return (head and head.Position) or nil;
end

local function UpdateSpectate()
    if (not isSpectating or not lockedRole) then return; end
    local targetPos = GetTargetPosition();
    if not targetPos then return; end
    local offset = CFrame.new(0, 2, 8);
    local tp = Players:FindFirstChild(((lockedRole == "警长") and ESP.Sheriff) or ESP.Murder)
    local targetChar = tp and tp.Character;
    if targetChar then
        local root = targetChar:FindFirstChild("HumanoidRootPart");
        if root then
            CurrentCamera.CFrame = root.CFrame * offset;
        end
    end
end

local function UpdateLockCamera()
    if (not isCameraLocked or not lockedRole) then return; end
    local targetPos = GetTargetPosition();
    if not targetPos then return; end
    local currentPos = CurrentCamera.CFrame.Position;
    if AimbotConfig.SmoothAim then
        CurrentCamera.CFrame = CurrentCamera.CFrame:Lerp(CFrame.new(currentPos, targetPos), AimbotConfig.Smoothness)
    else
        CurrentCamera.CFrame = CFrame.new(currentPos, targetPos);
    end
end

table.insert(ActiveConnections.RenderStepped, RunService.RenderStepped:Connect(function()
    if not ScriptEnabled then return end
    if isSpectating then
        UpdateSpectate();
    elseif isCameraLocked then
        UpdateLockCamera();
    end
end));

-- ---------- 静默自瞄 ----------
local SilentAimbot = {
    Enabled = false,
    TargetPart = "Head",
    FOV = 100,
    WallCheck = true,
    Prediction = 0.165,
    CircleVisible = true,
    CircleColor = Color3.fromRGB(255, 255, 255),
    Connection = nil
}

local FOVCircle = Drawing.new("Circle")
FOVCircle.Visible = false
FOVCircle.Thickness = 1.5
FOVCircle.NumSides = 64
FOVCircle.Radius = 100
FOVCircle.Color = Color3.fromRGB(255, 255, 255)
FOVCircle.Filled = false

local function GetClosestTargetToMouse()
    local closestPlayer = nil
    local shortestDistance = SilentAimbot.FOV

    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LP and player.Character and player.Name == ESP.Murder then
            local targetPart = player.Character:FindFirstChild(SilentAimbot.TargetPart)
            if targetPart then
                local pos, onScreen = CurrentCamera:WorldToViewportPoint(targetPart.Position)
                if onScreen then
                    local distance = (Vector2.new(pos.X, pos.Y) - UserInputService:GetMouseLocation()).Magnitude
                    if distance <= SilentAimbot.FOV then
                        if ESP_IsAlive(player) then
                            if SilentAimbot.WallCheck then
                                local ray = Ray.new(CurrentCamera.CFrame.Position, (targetPart.Position - CurrentCamera.CFrame.Position).Unit * 1000)
                                local hit = workspace:FindPartOnRayWithIgnoreList(ray, {LP.Character, player.Character})
                                if not hit or hit:IsDescendantOf(player.Character) then
                                    closestPlayer = player
                                    shortestDistance = distance
                                end
                            else
                                closestPlayer = player
                                shortestDistance = distance
                            end
                        end
                    end
                end
            end
        end
    end

    return closestPlayer
end

local lastAutoShoot = 0
local autoShootCooldown = 1.2

local function StartSilentAimbot()
    SilentAimbot.Connection = RunService.RenderStepped:Connect(function()
        FOVCircle.Position = UserInputService:GetMouseLocation()
        FOVCircle.Radius = SilentAimbot.FOV
        FOVCircle.Color = SilentAimbot.CircleColor
        FOVCircle.Visible = SilentAimbot.CircleVisible and SilentAimbot.Enabled

        if SilentAimbot.Enabled then
            local target = GetClosestTargetToMouse()
            if target and target.Character then
                local targetPart = target.Character:FindFirstChild(SilentAimbot.TargetPart)
                if targetPart then
                    local targetVelocity = target.Character:FindFirstChild("HumanoidRootPart") and target.Character.HumanoidRootPart.Velocity or Vector3.new(0, 0, 0)
                    local predictedPosition = targetPart.Position + (targetVelocity * SilentAimbot.Prediction)

                    local gun = LP.Character and LP.Character:FindFirstChild("Gun")
                    if gun and gun:FindFirstChild("KnifeLocal") then
                        if tick() - lastAutoShoot >= autoShootCooldown then
                            pcall(function()
                                gun.KnifeLocal.CreateBeam.RemoteFunction:InvokeServer(1, predictedPosition, "AH2")
                                lastAutoShoot = tick()
                            end)
                        end
                    end
                end
            end
        end
    end)
    table.insert(ActiveConnections.RenderStepped, SilentAimbot.Connection)
end

local function StopSilentAimbot()
    if SilentAimbot.Connection then
        SilentAimbot.Connection:Disconnect()
        SilentAimbot.Connection = nil
    end
    FOVCircle.Visible = false
end

-- ---------- 移速 / 跳跃 ----------
local CharacterSettings = {
    WalkSpeed = { Value = 16, Default = 16, Locked = false },
    JumpPower = { Value = 50, Default = 50, Locked = false }
}

local function updateCharacter()
    local character = LP.Character;
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid");
    if humanoid then
        if not CharacterSettings.WalkSpeed.Locked then
            humanoid.WalkSpeed = CharacterSettings.WalkSpeed.Value;
        end
        if not CharacterSettings.JumpPower.Locked then
            humanoid.JumpPower = CharacterSettings.JumpPower.Value;
        end
    end
end

table.insert(ActiveConnections.ChildAdded, LP.CharacterAdded:Connect(function(char)
    char:WaitForChild("Humanoid", 5)
    task.wait(0.5)
    updateCharacter()
end));

-- ---------- 传送 ----------
local teleportTarget = nil;
local teleportDropdown = nil;

local function updateTeleportPlayers()
    local playersList = { "选择玩家" };
    for _, player in pairs(Players:GetPlayers()) do
        if (player ~= LP) then
            table.insert(playersList, player.Name);
        end
    end
    return playersList;
end

local function teleportToPlayer()
    if (teleportTarget and teleportTarget.Character) then
        local targetRoot = teleportTarget.Character:FindFirstChild("HumanoidRootPart");
        local localRoot = LP.Character:FindFirstChild("HumanoidRootPart");
        if (targetRoot and localRoot) then
            localRoot.CFrame = targetRoot.CFrame;
            Notify("传送", "已成功传送到 " .. teleportTarget.Name)
        end
    else
        Notify("错误", "目标不存在或不可用")
    end
end

local function teleportToLobby()
    local lobby = workspace:FindFirstChild("Lobby");
    if not lobby then
        Notify("传送", "找不到大厅！")
        return;
    end
    local spawnPoint = lobby:FindFirstChild("SpawnPoint") or lobby:FindFirstChildOfClass("SpawnLocation");
    if not spawnPoint then
        spawnPoint = lobby:FindFirstChildWhichIsA("BasePart") or lobby;
    end
    if (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")) then
        LP.Character.HumanoidRootPart.CFrame = CFrame.new(spawnPoint.Position + Vector3.new(0, 3, 0));
        Notify("传送", "已传送到大厅！")
    end
end

local function teleportToRole(roleName, playerName)
    ESP_UpdateRoles();
    if playerName then
        local plr = Players:FindFirstChild(playerName);
        if (plr and plr.Character) then
            local targetRoot = plr.Character:FindFirstChild("HumanoidRootPart");
            local localRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart");
            if (targetRoot and localRoot) then
                localRoot.CFrame = targetRoot.CFrame;
                Notify("传送", "已传送到" .. roleName .. " " .. playerName)
            end
        else
            Notify("错误", roleName .. "不存在或不可用")
        end
    else
        Notify("错误", "当前对局没有" .. roleName)
    end
end

table.insert(ActiveConnections.ChildAdded, Players.PlayerAdded:Connect(function()
    task.wait(1);
    if teleportDropdown then teleportDropdown:Refresh(updateTeleportPlayers()); end
end));
table.insert(ActiveConnections.ChildAdded, Players.PlayerRemoving:Connect(function()
    if teleportDropdown then teleportDropdown:Refresh(updateTeleportPlayers()); end
end));

-- ---------- 自动农场 ----------
local AutoFarm = {
    Enabled = false,
    EggEnabled = false,
    Mode = "瞬间传送",
    TeleportDelay = 0,
    MoveSpeed = 50,
    WalkSpeed = 32,
    Connection = nil,
    EggConnection = nil,
    CoinCheckInterval = 0.5,
    CoinContainers = {
        "Factory", "Hospital3", "MilBase", "House2", "Workplace",
        "Mansion2", "BioLab", "Hotel", "Bank2", "PoliceStation",
        "ResearchFacility", "Lobby"
    }
};

local function findNearestCoin()
    local closestCoin = nil;
    local shortestDistance = math.huge;
    local character = LP.Character;
    local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart");
    if not humanoidRootPart then return nil; end

    for _, containerName in ipairs(AutoFarm.CoinContainers) do
        local container = workspace:FindFirstChild(containerName);
        if container then
            local coinContainer = ((containerName == "Lobby") and container) or container:FindFirstChild("CoinContainer");
            if coinContainer then
                for _, coin in ipairs(coinContainer:GetChildren()) do
                    local cv = coin:FindFirstChild("CoinVisual")
                    if cv and not cv:GetAttribute("Collected") and coin:IsA("BasePart") then
                        local distance = (humanoidRootPart.Position - coin.Position).Magnitude;
                        if distance < shortestDistance then
                            shortestDistance = distance;
                            closestCoin = coin;
                        end
                    end
                end
            end
        end
    end
    return closestCoin;
end

local function findNearestEgg()
    local closestEgg = nil;
    local shortestDistance = math.huge;
    local character = LP.Character;
    local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart");
    if not humanoidRootPart then return nil; end

    for _, item in pairs(workspace:GetDescendants()) do
        if item:IsA("BasePart") and (string.find(string.lower(item.Name), "egg") or string.find(string.lower(item.Name), "rareegg")) then
            local distance = (humanoidRootPart.Position - item.Position).Magnitude;
            if distance < shortestDistance then
                shortestDistance = distance;
                closestEgg = item;
            end
        end
    end
    return closestEgg;
end

local function moveToItem(item)
    if (not item or not LP.Character) then return; end
    local humanoidRootPart = LP.Character:FindFirstChild("HumanoidRootPart");
    if not humanoidRootPart then return; end

    if AutoFarm.Mode == "瞬间传送" then
        humanoidRootPart.CFrame = CFrame.new(item.Position + Vector3.new(0, 3, 0));
        task.wait(AutoFarm.TeleportDelay);
    elseif AutoFarm.Mode == "平滑移动" then
        local startTime = tick();
        local startPos = humanoidRootPart.Position;
        local endPos = item.Position + Vector3.new(0, 3, 0);
        local distance = (startPos - endPos).Magnitude;
        local duration = distance / AutoFarm.MoveSpeed;
        while (tick() - startTime) < duration and (AutoFarm.Enabled or AutoFarm.EggEnabled) do
            if (not item or not item.Parent) then break; end
            local progress = math.min((tick() - startTime) / duration, 1);
            humanoidRootPart.CFrame = CFrame.new(startPos:Lerp(endPos, progress));
            task.wait();
        end
    else
        local humanoid = LP.Character:FindFirstChildOfClass("Humanoid");
        if not humanoid then return; end
        humanoid.WalkSpeed = AutoFarm.WalkSpeed;
        humanoid:MoveTo(item.Position + Vector3.new(0, 0, 3));
        local startTime = tick();
        while (AutoFarm.Enabled or AutoFarm.EggEnabled) and (humanoid.MoveDirection.Magnitude > 0) and (tick() - startTime) < 10 do
            task.wait(0.5);
        end
    end
end

local function collectItem(item)
    if (not item or not LP.Character) then return; end
    local humanoidRootPart = LP.Character:FindFirstChild("HumanoidRootPart");
    if not humanoidRootPart then return; end
    firetouchinterest(humanoidRootPart, item, 0);
    firetouchinterest(humanoidRootPart, item, 1);
end

local function farmLoop()
    while AutoFarm.Enabled do
        local coin = findNearestCoin();
        if coin then
            moveToItem(coin);
            collectItem(coin);
        else
            task.wait(2);
        end
        task.wait(AutoFarm.CoinCheckInterval);
    end
end

local function eggFarmLoop()
    while AutoFarm.EggEnabled do
        local egg = findNearestEgg();
        if egg then
            moveToItem(egg);
            collectItem(egg);
        else
            task.wait(2);
        end
        task.wait(AutoFarm.CoinCheckInterval);
    end
end

-- ---------- 平民：枪械 + 凶手躲避 ----------
local GunSystem = {
    AutoGrabEnabled = false,
    GunDropCheckInterval = 1,
    ActiveGunDrops = {},
};

local function ScanForGunDrops()
    GunSystem.ActiveGunDrops = {};
    for _, child in pairs(workspace:GetDescendants()) do
        if child.Name == "GunDrop" then
            table.insert(GunSystem.ActiveGunDrops, child);
        end
    end
end

local function EquipGun()
    if LP.Character and LP.Character:FindFirstChild("Gun") then return true; end
    local gun = LP.Backpack:FindFirstChild("Gun");
    if gun then
        gun.Parent = LP.Character;
        task.wait(0.1);
        return LP.Character:FindFirstChild("Gun") ~= nil;
    end
    return false;
end

local function GrabGun(gunDrop)
    if not gunDrop then
        ScanForGunDrops();
        if #GunSystem.ActiveGunDrops == 0 then
            Notify("枪械系统", "没有可拾取的枪！")
            return false;
        end
        local nearestGun = nil;
        local minDistance = math.huge;
        local humanoidRootPart = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart");
        if humanoidRootPart then
            for _, drop in ipairs(GunSystem.ActiveGunDrops) do
                local distance = (humanoidRootPart.Position - drop.Position).Magnitude;
                if distance < minDistance then
                    minDistance = distance;
                    nearestGun = drop;
                end
            end
        end
        gunDrop = nearestGun;
    end

    if gunDrop and LP.Character then
        local humanoidRootPart = LP.Character:FindFirstChild("HumanoidRootPart");
        if humanoidRootPart then
            humanoidRootPart.CFrame = gunDrop.CFrame;
            task.wait(0.3);
            local prompt = gunDrop:FindFirstChildOfClass("ProximityPrompt");
            if prompt then
                fireproximityprompt(prompt);
                Notify("枪械系统", "已拿到枪！")
                return true;
            end
        end
    end
    return false;
end

local function AutoGrabGun()
    while GunSystem.AutoGrabEnabled do
        ScanForGunDrops();
        if #GunSystem.ActiveGunDrops > 0 and LP.Character then
            local humanoidRootPart = LP.Character:FindFirstChild("HumanoidRootPart");
            if humanoidRootPart then
                local nearestGun = nil;
                local minDistance = math.huge;
                for _, gunDrop in ipairs(GunSystem.ActiveGunDrops) do
                    local distance = (humanoidRootPart.Position - gunDrop.Position).Magnitude;
                    if distance < minDistance then
                        nearestGun = gunDrop;
                        minDistance = distance;
                    end
                end
                if nearestGun then
                    humanoidRootPart.CFrame = nearestGun.CFrame;
                    task.wait(0.3);
                    local prompt = nearestGun:FindFirstChildOfClass("ProximityPrompt");
                    if prompt then
                        fireproximityprompt(prompt);
                        task.wait(1);
                    end
                end
            end
        end
        task.wait(GunSystem.GunDropCheckInterval);
    end
end

local EvasionSystem = { Enabled = false, TriggerDistance = 35, Connection = nil }

local function StartEvasion()
    EvasionSystem.Connection = RunService.Heartbeat:Connect(function()
        if not ScriptEnabled or not EvasionSystem.Enabled then return end
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local murderer = ESP.Murder and Players:FindFirstChild(ESP.Murder)
        local mroot = murderer and murderer.Character and murderer.Character:FindFirstChild("HumanoidRootPart")
        if root and hum and mroot and (root.Position - mroot.Position).Magnitude <= EvasionSystem.TriggerDistance then
            local dir = root.Position - mroot.Position
            if dir.Magnitude > 0 then
                hum:MoveTo(root.Position + dir.Unit * 40)
            end
        end
    end)
    table.insert(ActiveConnections.Heartbeat, EvasionSystem.Connection)
end

local function StopEvasion()
    if EvasionSystem.Connection then EvasionSystem.Connection:Disconnect(); EvasionSystem.Connection = nil end
end

-- ---------- 杀手：全部击杀 + 预判躲枪 ----------
local killActive = false;
local attackDelay = 0.5;

local function equipKnife()
    local character = LP.Character;
    if not character then return false; end
    if character:FindFirstChild("Knife") then return true; end
    local knife = LP.Backpack:FindFirstChild("Knife");
    if knife then
        knife.Parent = character;
        return true;
    end
    return false;
end

local function getNearestTarget()
    local targets = {};
    local success, roles = pcall(function()
        return ReplicatedStorage:FindFirstChild("GetPlayerData", true):InvokeServer();
    end);
    local localRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart");
    if not localRoot then return nil; end

    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LP and player.Character then
            local role = nil;
            if success and roles and roles[player.Name] then
                role = roles[player.Name].Role;
            end
            local humanoid = player.Character:FindFirstChild("Humanoid");
            local targetRoot = player.Character:FindFirstChild("HumanoidRootPart");
            if role and humanoid and humanoid.Health > 0 and targetRoot then
                if role ~= "Murderer" then
                    table.insert(targets, {
                        Player = player,
                        Distance = (localRoot.Position - targetRoot.Position).Magnitude
                    });
                end
            end
        end
    end
    table.sort(targets, function(a, b) return a.Distance < b.Distance; end);
    return targets[1] and targets[1].Player or nil;
end

local function attackTarget(target)
    if not target or not target.Character then return false; end
    local humanoid = target.Character:FindFirstChild("Humanoid");
    if not humanoid or humanoid.Health <= 0 then return false; end
    if not equipKnife() then return false; end

    local targetRoot = target.Character:FindFirstChild("HumanoidRootPart");
    local localRoot = LP.Character:FindFirstChild("HumanoidRootPart");
    if targetRoot and localRoot then
        localRoot.CFrame = CFrame.new(targetRoot.Position + ((localRoot.Position - targetRoot.Position).Unit * 2), targetRoot.Position);
    end

    local knife = LP.Character:FindFirstChild("Knife");
    if knife and knife:FindFirstChild("Stab") then
        for i = 1, 3 do
            knife.Stab:FireServer("Down");
        end
        return true;
    end
    return false;
end

local function killTargets()
    if killActive then return; end
    killActive = true;
    Notify("全部击杀", "开始击杀...")
    task.spawn(function()
        while killActive do
            local target = getNearestTarget();
            if not target then
                killActive = false;
                Notify("全部击杀", "没有可击杀的目标！")
                break;
            end
            attackTarget(target);
            task.wait(attackDelay);
        end
    end);
end

local function stopKilling()
    killActive = false;
    Notify("全部击杀", "已停止")
end

local MurdSystem = { PredictiveDodge = false, DodgeConnection = nil }

local function StartDodge()
    MurdSystem.DodgeConnection = RunService.Heartbeat:Connect(function()
        if not ScriptEnabled or not MurdSystem.PredictiveDodge or LP.Name ~= ESP.Murder then return end
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local sheriff = ESP.Sheriff and Players:FindFirstChild(ESP.Sheriff)
        local shead = sheriff and sheriff.Character and sheriff.Character:FindFirstChild("Head")
        local sgun = sheriff and sheriff.Character and sheriff.Character:FindFirstChild("Gun")
        if root and shead and sgun then
            local delta = root.Position - shead.Position
            if delta.Magnitude > 0 and shead.CFrame.LookVector:Dot(delta.Unit) > 0.85 then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum:MoveTo(root.Position + shead.CFrame.RightVector * (math.random(0, 1) == 0 and -18 or 18))
                    hum.Jump = true
                end
            end
        end
    end)
    table.insert(ActiveConnections.Heartbeat, MurdSystem.DodgeConnection)
end

local function StopDodge()
    if MurdSystem.DodgeConnection then MurdSystem.DodgeConnection:Disconnect(); MurdSystem.DodgeConnection = nil end
end

