                local args = {[1] = 10, [2] = targetPart.Position, [3] = "AH2"};
                gun.KnifeLocal.CreateBeam.RemoteFunction:InvokeServer(unpack(args));
            end
        end
    end);

    shotButton.Parent = shotButtonFrame;
    shotButtonFrame.Parent = screenGui;
    shotButtonActive = true;
end

-- ---------- 服务器 ----------
local function ServerHop(joinLowest)
    local success, result = pcall(function()
        return HttpService:JSONDecode(game:HttpGet("https://games.roproxy.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100"));
    end);
    if success and result and result.data then
        local servers = {};
        for _, server in ipairs(result.data) do
            if server.id ~= game.JobId and (not joinLowest or server.playing < server.maxPlayers) then
                table.insert(servers, server);
            end
        end
        if joinLowest then
            table.sort(servers, function(a, b) return a.playing < b.playing; end);
        end
        if #servers > 0 then
            local picked = joinLowest and servers[1] or servers[math.random(#servers)];
            TeleportService:TeleportToPlaceInstance(game.PlaceId, picked.id);
        else
            TeleportService:Teleport(game.PlaceId);
        end
    else
        TeleportService:Teleport(game.PlaceId);
    end
end

