                if root then
                    if not box then
                        box = Instance.new("BoxHandleAdornment");
                        box.Adornee = root;
                        box.Size = Vector3.new(Settings.Hitbox.Size, Settings.Hitbox.Size, Settings.Hitbox.Size);
                        box.Color3 = Settings.Hitbox.Color;
                        box.Transparency = 0.4;
                        box.ZIndex = 10;
                        box.Parent = root;
