    local layout = Instance.new("UIListLayout") layout.SortOrder = Enum.SortOrder.LayoutOrder layout.Padding = UDim.new(0, 4) layout.Parent = scroll

    local others = {}
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then table.insert(others, p) end
    end
    table.sort(others, function(a, b) return a.Name < b.Name end)

    for i, p in ipairs(others) do
        local btn = Instance.new("TextButton")
        btn.Size = UDim2.new(1, 0, 0, 32)
        btn.BackgroundColor3 = Color3.fromRGB(28, 30, 42)
        btn.BackgroundTransparency = 0.1
        btn.TextColor3 = Color3.fromRGB(220, 222, 240)
        btn.Font = Enum.Font.Gotham
        btn.TextSize = 12
        btn.Text = p.DisplayName .. " (@" .. p.Name .. ")"
        btn.BorderSizePixel = 0
        btn.LayoutOrder = i
        btn.Parent = scroll
        local bc = Instance.new("UICorner") bc.CornerRadius = UDim.new(0, 8) bc.Parent = btn
        local bst = Instance.new("UIStroke") bst.Thickness = 1 bst.Color = Color3.fromRGB(60, 62, 80) bst.Parent = btn
        btn.MouseButton1Click:Connect(function()
            callback(p)
            gui:Destroy()
            if PlayerPickerGui == gui then PlayerPickerGui = nil end
        end)
    end
    scroll.CanvasSize = UDim2.new(0, 0, 0, #others * 36)

    local close = Instance.new("TextButton")
    close.Size = UDim2.new(0, 100, 0, 28)
    close.Position = UDim2.new(0.5, -50, 1, -36)
    close.BackgroundColor3 = Color3.fromRGB(120, 40, 40)
    close.TextColor3 = Color3.fromRGB(255, 255, 255)
    close.Font = Enum.Font.GothamBold
    close.TextSize = 12
    close.Text = "关闭"
    close.BorderSizePixel = 0
    close.Parent = frame
    local cc = Instance.new("UICorner") cc.CornerRadius = UDim.new(0, 8) cc.Parent = close
    close.MouseButton1Click:Connect(function()
        gui:Destroy()
        if PlayerPickerGui == gui then PlayerPickerGui = nil end
    end)
end

local function PickPlayer(callback)
    CreatePlayerPicker(function(p)
        CurrentTarget = p
        Notify("选择目标", "已选择目标: " .. p.DisplayName .. " (@" .. p.Name .. ")")
        if callback then callback(p) end
    end)
end

-- ============================================================
-- 栏目：甩飞
-- ============================================================
local FlingLoopActive = false
local FlingLoopConnection = nil
local FlingLoopAllActive = false
local FlingLoopAllConnection = nil
local FlingLastTime = 0
local FlingInterval = 0.5

local function FlingPlayer(TargetPlayer)
    local Character = LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    local RootPart = Humanoid and Humanoid.RootPart
    if not TargetPlayer or not TargetPlayer.Character then
        Notify("错误", "目标无效")
        return
    end
    local TCharacter = TargetPlayer.Character
    local THumanoid, TRootPart, THead, Accessory, Handle
    if TCharacter:FindFirstChildOfClass("Humanoid") then THumanoid = TCharacter:FindFirstChildOfClass("Humanoid") end
    if THumanoid and THumanoid.RootPart then TRootPart = THumanoid.RootPart end
    if TCharacter:FindFirstChild("Head") then THead = TCharacter.Head end
    if TCharacter:FindFirstChildOfClass("Accessory") then Accessory = TCharacter:FindFirstChildOfClass("Accessory") end
    if Accessory and Accessory:FindFirstChild("Handle") then Handle = Accessory.Handle end

    if Character and Humanoid and RootPart then
        if RootPart.Velocity.Magnitude < 50 then
            getgenv().OldPos = RootPart.CFrame
        end
        if THumanoid and THumanoid.Sit then
            Notify("提示", "目标正在坐着")
            return
        end
        local targetStartPos = (TRootPart or THead or Handle).Position
        if THead then
            workspace.CurrentCamera.CameraSubject = THead
        elseif not THead and Handle then
            workspace.CurrentCamera.CameraSubject = Handle
        elseif THumanoid and TRootPart then
            workspace.CurrentCamera.CameraSubject = THumanoid
        end
        if not TCharacter:FindFirstChildWhichIsA("BasePart") then
            Notify("错误", "目标缺少部件")
            return
        end

        local oldFPDH = workspace.FallenPartsDestroyHeight
        workspace.FallenPartsDestroyHeight = 0/0

        local function FPos(BasePart, Pos, Ang)
            RootPart.CFrame = CFrame.new(BasePart.Position) * Pos * Ang
            Character:SetPrimaryPartCFrame(CFrame.new(BasePart.Position) * Pos * Ang)
            RootPart.Velocity = Vector3.new(9e7, 9e7*10, 9e7)
            RootPart.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
        end

        local function SFBasePart(BasePart)
            local TimeToWait = 2
            local Time = tick()
            local Angle = 0
            repeat
                if (BasePart.Position - targetStartPos).Magnitude > 100 then
                    workspace.CurrentCamera.CameraSubject = Humanoid
                    Notify("提示", "目标飞出太远，视角已恢复")
                    break
                end
                if RootPart and THumanoid then
                    if BasePart.Velocity.Magnitude < 50 then
                        Angle = Angle + 100
                        FPos(BasePart, CFrame.new(0, 1.5, 0) + THumanoid.MoveDirection * BasePart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(Angle), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, 0) + THumanoid.MoveDirection * BasePart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(Angle), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(2.25, 1.5, -2.25) + THumanoid.MoveDirection * BasePart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(Angle), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(-2.25, -1.5, 2.25) + THumanoid.MoveDirection * BasePart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(Angle), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, 1.5, 0) + THumanoid.MoveDirection, CFrame.Angles(math.rad(Angle), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, 0) + THumanoid.MoveDirection, CFrame.Angles(math.rad(Angle), 0, 0)) task.wait()
                    else
                        FPos(BasePart, CFrame.new(0, 1.5, THumanoid.WalkSpeed), CFrame.Angles(math.rad(90), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, -THumanoid.WalkSpeed), CFrame.Angles(0, 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, 1.5, THumanoid.WalkSpeed), CFrame.Angles(math.rad(90), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, 1.5, TRootPart.Velocity.Magnitude / 1.25), CFrame.Angles(math.rad(90), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, -TRootPart.Velocity.Magnitude / 1.25), CFrame.Angles(0, 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, 1.5, TRootPart.Velocity.Magnitude / 1.25), CFrame.Angles(math.rad(90), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, 0), CFrame.Angles(math.rad(90), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, 0), CFrame.Angles(0, 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, 0), CFrame.Angles(math.rad(-90), 0, 0)) task.wait()
                        FPos(BasePart, CFrame.new(0, -1.5, 0), CFrame.Angles(0, 0, 0)) task.wait()
                    end
                else
                    break
                end
            until BasePart.Velocity.Magnitude > 500
                or BasePart.Parent ~= TargetPlayer.Character
                or TargetPlayer.Parent ~= Players
                or not TargetPlayer.Character == TCharacter
                or THumanoid.Sit
                or Humanoid.Health <= 0
                or tick() > Time + TimeToWait
            workspace.CurrentCamera.CameraSubject = Humanoid
        end

        local BV = Instance.new("BodyVelocity")
        BV.Name = "EpixVel"
        BV.Parent = RootPart
        BV.Velocity = Vector3.new(9e8, 9e8, 9e8)
        BV.MaxForce = Vector3.new(1/0, 1/0, 1/0)
        Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)

        if TRootPart and THead then
            if (TRootPart.CFrame.p - THead.CFrame.p).Magnitude > 5 then
                SFBasePart(THead)
            else
                SFBasePart(TRootPart)
            end
        elseif TRootPart and not THead then
            SFBasePart(TRootPart)
        elseif not TRootPart and THead then
            SFBasePart(THead)
        elseif not TRootPart and not THead and Accessory and Handle then
            SFBasePart(Handle)
        else
            Notify("错误", "目标缺少可用部件")
            BV:Destroy()
            Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
            workspace.CurrentCamera.CameraSubject = Humanoid
            workspace.FallenPartsDestroyHeight = oldFPDH
            return
        end

        BV:Destroy()
        Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
        workspace.CurrentCamera.CameraSubject = Humanoid

        local oldPos = getgenv().OldPos or RootPart.CFrame
        repeat
            RootPart.CFrame = oldPos * CFrame.new(0, .5, 0)
            Character:SetPrimaryPartCFrame(oldPos * CFrame.new(0, .5, 0))
            Humanoid:ChangeState("GettingUp")
            for _, part in ipairs(Character:GetChildren()) do
                if part:IsA("BasePart") then
                    part.Velocity = Vector3.new()
                    part.RotVelocity = Vector3.new()
                end
            end
            task.wait()
        until (RootPart.Position - oldPos.p).Magnitude < 25

        RootPart.CFrame = oldPos
        Character:SetPrimaryPartCFrame(oldPos)
        for _, part in ipairs(Character:GetChildren()) do
            if part:IsA("BasePart") then
                part.Velocity = Vector3.new()
                part.RotVelocity = Vector3.new()
            end
        end
        workspace.FallenPartsDestroyHeight = oldFPDH
        Notify("甩飞", "甩飞完成: " .. TargetPlayer.Name)
    else
        Notify("错误", "角色或 Humanoid 丢失")
    end
end

local function StopFlingLoop()
    FlingLoopActive = false
    if FlingLoopConnection then FlingLoopConnection:Disconnect() FlingLoopConnection = nil end
end

local function StartFlingLoop()
    if not CurrentTarget then
        Notify("错误", "请先选择目标玩家")
        return
    end
    FlingLoopActive = true
    FlingLoopConnection = RunService.Heartbeat:Connect(function()
        if not FlingLoopActive then return end
        if not CurrentTarget then StopFlingLoop() return end
        local now = tick()
        if now - FlingLastTime >= FlingInterval then
            FlingLastTime = now
            local tChar = CurrentTarget.Character
            if tChar then
                local tRoot = tChar:FindFirstChild("HumanoidRootPart")
                if tRoot and tRoot.AssemblyLinearVelocity.Magnitude > 100 then return end
            end
            FlingPlayer(CurrentTarget)
        end
    end)
    Notify("甩飞", "循环甩飞已启动（间隔 0.5 秒）")
end

local function FlingAllPlayers()
    local count = 0
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer and p.Character then
            count = count + 1
            task.spawn(function()
                FlingPlayer(p)
            end)
            task.wait(0.3)
        end
    end
    Notify("甩飞", "已对所有玩家发起甩飞（共 " .. count .. " 人）")
end

local function StopFlingAllLoop()
    FlingLoopAllActive = false
    if FlingLoopAllConnection then FlingLoopAllConnection:Disconnect() FlingLoopAllConnection = nil end
end

local function StartFlingAllLoop()
    FlingLoopAllActive = true
    Notify("甩飞", "循环甩飞所有玩家已启动")
    task.spawn(function()
        while FlingLoopAllActive do
            for _, p in ipairs(Players:GetPlayers()) do
                if not FlingLoopAllActive then break end
                if p ~= LocalPlayer and p.Character then
                    local tRoot = p.Character:FindFirstChild("HumanoidRootPart")
                    if tRoot and tRoot.AssemblyLinearVelocity.Magnitude <= 100 then
                        pcall(FlingPlayer, p)
                    end
                end
            end
            task.wait(FlingInterval)
        end
    end)
end

-- ---------- 触碰甩飞 ----------
local TouchFlingActive = false
local TouchFlingThread = nil

local function TouchFling_Stop()
    TouchFlingActive = false
    TouchFlingThread = nil
    Notify("触碰甩飞", "已关闭")
end

local function TouchFling_Start()
    if TouchFlingThread then return end
    TouchFlingActive = true
    Notify("触碰甩飞", "已开启：碰到谁谁起飞（隐藏式）")
    TouchFlingThread = task.spawn(function()
        local movel = 0.1
        while TouchFlingActive do
            local char = LocalPlayer.Character
            if not char then task.wait(0.1) continue end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then task.wait(0.1) continue end
            RunService.Heartbeat:Wait()
            local vel = hrp.Velocity
            hrp.Velocity = vel * 10000 + Vector3.new(0, 10000, 0)
            RunService.RenderStepped:Wait()
            hrp.Velocity = vel
            RunService.Stepped:Wait()
            hrp.Velocity = vel + Vector3.new(0, movel, 0)
            movel = -movel
        end
        TouchFlingThread = nil
    end)
end

-- ---------- 防甩飞 ----------
local AntiFling = {
    Enabled = false,
    MaxLinear = 200, MaxAngular = 100,
    SafeCFrame = nil,
    BodyMovers = { "BodyVelocity", "BodyAngularVelocity", "BodyForce", "BodyThrust", "BodyPosition", "BodyGyro" },
    Conns = {},
    HeartbeatCon = nil,
    OriginalCanCollide = {},
    RestoreTask = nil,
}

local function AF_RecordOriginalCollide()
    local char = LocalPlayer.Character
    if not char then return end
    AntiFling.OriginalCanCollide = {}
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then AntiFling.OriginalCanCollide[part] = part.CanCollide end
    end
end

local function AF_RestoreOriginalCollide()
    if AntiFling.RestoreTask then task.cancel(AntiFling.RestoreTask) AntiFling.RestoreTask = nil end
    for part, original in pairs(AntiFling.OriginalCanCollide) do
        if part and part.Parent then
            part.CanCollide = original
            part.AssemblyLinearVelocity = Vector3.zero
            part.AssemblyAngularVelocity = Vector3.zero
            part.Velocity = Vector3.zero
            part.RotVelocity = Vector3.zero
        end
    end
    AntiFling.OriginalCanCollide = {}
    local char = LocalPlayer.Character
    if char then
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                part.AssemblyLinearVelocity = Vector3.zero
                part.AssemblyAngularVelocity = Vector3.zero
                part.Velocity = Vector3.zero
                part.RotVelocity = Vector3.zero
            end
        end
    end
end

local function AF_Neutralize()
    if not AntiFling.Enabled then return end
    local char = LocalPlayer.Character
    if not char then return end
    for _, obj in ipairs(char:GetDescendants()) do
        if table.find(AntiFling.BodyMovers, obj.ClassName) then
            pcall(function() obj:Destroy() end)
        end
    end
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            part.CanCollide = false
            part.AssemblyLinearVelocity = Vector3.zero
            part.AssemblyAngularVelocity = Vector3.zero
            part.Velocity = Vector3.zero
            part.RotVelocity = Vector3.zero
        end
    end
    local root = char:FindFirstChild("HumanoidRootPart")
    if root and AntiFling.SafeCFrame then
        root.CFrame = AntiFling.SafeCFrame
        char:SetPrimaryPartCFrame(AntiFling.SafeCFrame)
    end
    if AntiFling.RestoreTask then task.cancel(AntiFling.RestoreTask) end
    AntiFling.RestoreTask = task.delay(0.4, function()
        if char and char.Parent then
            for part, original in pairs(AntiFling.OriginalCanCollide) do
                if part and part.Parent then part.CanCollide = original end
            end
        end
        AntiFling.RestoreTask = nil
    end)
    Notify("防甩飞", "检测到被甩飞，已自动回位")
end

local function AF_WatchBodyMovers(char)
    local con = char.DescendantAdded:Connect(function(child)
        if not AntiFling.Enabled then return end
        if table.find(AntiFling.BodyMovers, child.ClassName) then
            child:Destroy()
            Notify("防甩飞", "拦截异常 " .. child.ClassName)
            AF_Neutralize()
        end
    end)
    table.insert(AntiFling.Conns, con)
end

local function AF_Heartbeat()
    if not AntiFling.Enabled then return end
    local char = LocalPlayer.Character
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local linear = root.AssemblyLinearVelocity.Magnitude
    local angular = root.AssemblyAngularVelocity.Magnitude
    if linear < 60 and angular < 40 then
        AntiFling.SafeCFrame = root.CFrame
    end
    if linear > AntiFling.MaxLinear or angular > AntiFling.MaxAngular then
        AF_Neutralize()
    end
end

local function AF_Setup(char)
    for _, con in ipairs(AntiFling.Conns) do pcall(function() con:Disconnect() end) end
    AntiFling.Conns = {}
    task.wait(0.3)
    if char and char.Parent then
        AF_WatchBodyMovers(char)
        if AntiFling.Enabled then AF_RecordOriginalCollide() end
    end
end

local function AF_Toggle(enabled)
    AntiFling.Enabled = enabled
    if enabled then
        if not AntiFling.HeartbeatCon then
            AntiFling.HeartbeatCon = RunService.Heartbeat:Connect(AF_Heartbeat)
        end
        local char = LocalPlayer.Character
        if char then AF_Setup(char) end
        Notify("防甩飞", "已开启")
    else
        if AntiFling.HeartbeatCon then
            AntiFling.HeartbeatCon:Disconnect()
            AntiFling.HeartbeatCon = nil
        end
        for _, con in ipairs(AntiFling.Conns) do pcall(function() con:Disconnect() end) end
        AntiFling.Conns = {}
        if AntiFling.RestoreTask then task.cancel(AntiFling.RestoreTask) AntiFling.RestoreTask = nil end
        AF_RestoreOriginalCollide()
        AntiFling.SafeCFrame = nil
        Notify("防甩飞", "已关闭")
    end
end

if LocalPlayer.Character then AF_Setup(LocalPlayer.Character) end
LocalPlayer.CharacterAdded:Connect(AF_Setup)

-- ============================================================
-- 栏目：背后传送（零延迟锁定）
-- ============================================================
local LockBehind = {
    Active = false,
    Connection = nil,
    PredictEnabled = false,
    PredictDelay = 0.125,
}

local function LockBehind_Stop(notify)
    if not LockBehind.Active then
        if notify then Notify("背后传送", "未启动") end
        return
    end
    LockBehind.Active = false
    if LockBehind.Connection then LockBehind.Connection:Disconnect() LockBehind.Connection = nil end
    local myChar = LocalPlayer.Character
    if myChar then
        local myRoot = myChar:FindFirstChild("HumanoidRootPart")
        local myHumanoid = myChar:FindFirstChildOfClass("Humanoid")
        if sethiddenproperty and myRoot then
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", nil) end)
        end
        if myRoot then
            pcall(function() myRoot.AssemblyLinearVelocity = Vector3.zero end)
            pcall(function() myRoot.AssemblyAngularVelocity = Vector3.zero end)
            pcall(function() myRoot.Velocity = Vector3.zero end)
            pcall(function() myRoot.RotVelocity = Vector3.zero end)
        end
        if myHumanoid then pcall(function() myHumanoid.AutoRotate = true end) end
    end
    if notify then Notify("背后传送", "已停止") end
end

local function GetPredictedPosition(rootPart)
    if not LockBehind.PredictEnabled then return rootPart.Position end
    local vel = rootPart.AssemblyLinearVelocity
    if vel.Magnitude < 0.5 then return rootPart.Position end
    return rootPart.Position + vel * LockBehind.PredictDelay
end

local function LockBehind_Routine()
    if not LockBehind.Active then return end
    local myChar = LocalPlayer.Character
    local targetChar = CurrentTarget and CurrentTarget.Character
    if not myChar or not targetChar then LockBehind_Stop(false) return end
    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
    local targetRoot = targetChar:FindFirstChild("HumanoidRootPart")
    local myHumanoid = myChar:FindFirstChildOfClass("Humanoid")
    if not myRoot or not targetRoot or not myHumanoid then LockBehind_Stop(false) return end

    local targetPos = GetPredictedPosition(targetRoot)
    local targetCFrameAtPos = CFrame.new(targetPos) * (targetRoot.CFrame - targetRoot.CFrame.Position)
    local rx, ry, rz = targetCFrameAtPos:ToEulerAnglesYXZ()
    local yawCFrame = CFrame.fromEulerAnglesYXZ(0, ry, 0)
    local offsetCFrame = CFrame.new(targetCFrameAtPos.Position) * yawCFrame * CFrame.new(0, 0, 5)
    local offsetPos = offsetCFrame.Position
    local finalCFrame = CFrame.new(offsetPos) * yawCFrame

    myHumanoid.AutoRotate = false
    myRoot.AssemblyLinearVelocity = Vector3.zero
    myRoot.AssemblyAngularVelocity = Vector3.zero
    myRoot.CFrame = finalCFrame
    if sethiddenproperty then
        pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", targetRoot) end)
    end
end

local function LockBehind_Start()
    if LockBehind.Active then return end
    if not CurrentTarget then
        Notify("错误", "请先选择目标玩家")
        return
    end
    LockBehind.Active = true
    LockBehind.Connection = RunService.Heartbeat:Connect(function()
        LockBehind_Routine()
        task.wait(0.001)
    end)
    Notify("背后传送", "已启动（零延迟）- 目标: " .. CurrentTarget.Name)
end

LocalPlayer.CharacterAdded:Connect(function(char)
    char:WaitForChild("Humanoid").Died:Connect(function()
        LockBehind_Stop(false)
    end)
end)

-- ============================================================
-- 栏目：隐身
-- ============================================================
local INVIS_TARGET_POS = Vector3.new(36.53, 504.96, -39.93)

local InvisData = {
    Enabled = false,
    Char = nil, Hum = nil, Root = nil,
    Parts = {},
    Offset = Vector3.new(0, -200000, 0),
}

local function Invis_RefreshParts()
    InvisData.Char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    InvisData.Hum = InvisData.Char:WaitForChild("Humanoid")
    InvisData.Root = InvisData.Char:WaitForChild("HumanoidRootPart")
    InvisData.Parts = {}
    for _, part in ipairs(InvisData.Char:GetDescendants()) do
        if part:IsA("BasePart") and part.Transparency == 0 then
            table.insert(InvisData.Parts, part)
        end
    end
end

local function Invis_ApplyTransparency(value)
    for _, part in ipairs(InvisData.Parts) do
        if part and part.Parent then
            part.Transparency = value
        end
    end
end

local function Invis_Toggle(enabled)
    InvisData.Enabled = enabled
    if enabled then
        Invis_RefreshParts()
        if InvisData.Root then
            InvisData.Offset = INVIS_TARGET_POS - InvisData.Root.Position
        end
        Invis_ApplyTransparency(0.5)
        Notify("隐身", "已开启：本体藏在 " .. tostring(INVIS_TARGET_POS))
    else
        Invis_ApplyTransparency(0)
        Notify("隐身", "已关闭")
    end
end

RunService.Heartbeat:Connect(function()
    if not InvisData.Enabled then return end
    if not InvisData.Root or not InvisData.Hum then return end
    local currentCFrame = InvisData.Root.CFrame
    local currentOffset = InvisData.Hum.CameraOffset
    local targetCFrame = currentCFrame * CFrame.new(InvisData.Offset)
    local posOffset = targetCFrame:ToObjectSpace(CFrame.new(currentCFrame.Position)).Position
    InvisData.Root.CFrame = targetCFrame
    InvisData.Hum.CameraOffset = posOffset
    RunService.RenderStepped:Wait()
    InvisData.Root.CFrame = currentCFrame
    InvisData.Hum.CameraOffset = currentOffset
end)

LocalPlayer.CharacterAdded:Connect(function()
    if InvisData.Enabled then
        InvisData.Enabled = false
        task.wait(0.5)
        Invis_Toggle(true)
    end
end)

