local ESPSection = Window:Section({ Title = "透视" })
local AimSection = Window:Section({ Title = "自瞄" })
local CharSection = Window:Section({ Title = "角色" })
local TPSection = Window:Section({ Title = "传送" })
local FarmSection = Window:Section({ Title = "自动农场" })
local InnocentSection = Window:Section({ Title = "平民" })
local MurderSection = Window:Section({ Title = "杀手" })
local SheriffSection = Window:Section({ Title = "警长" })
