-- ===== 栏目一：透视（MM2 ESP） =====
do
    local Tab = ESPSection:Tab({
        Title = "透视功能",
        Desc = "角色高亮 + 名字/方框/追踪线 ESP",
        Icon = "eye",
        IconColor = makeRainbowColor(0),
        IconShape = "Square",
        Border = true,
    })

    Tab:Section({ Title = "人物高亮", TextSize = 16, FontWeight = Enum.FontWeight.SemiBold })
    Tab:Toggle({
        Title = "开启透视总开关",
        Desc = "关闭时会清掉所有高亮与绘图 ESP",
        Default = false,
        Callback = function(value)
            ESP.Enabled = value
            if not value then
                ESP_RemoveAll()
                Notify("透视", "已关闭")
            else
                Notify("透视", "已开启")
            end
        end,
    })
    Tab:Toggle({ Title = "高亮杀手", Default = false, Callback = function(s) ESP.HighlightMurderer = s; if not s then ESP_UpdateHighlights(); end end })
    Tab:Toggle({ Title = "高亮平民", Default = false, Callback = function(s) ESP.HighlightInnocent = s; if not s then ESP_UpdateHighlights(); end end })
    Tab:Toggle({ Title = "高亮警长", Default = false, Callback = function(s) ESP.HighlightSheriff = s; if not s then ESP_UpdateHighlights(); end end })
    Tab:Space()

    Tab:Section({ Title = "绘图 ESP", TextSize = 16, FontWeight = Enum.FontWeight.SemiBold })
    Tab:Toggle({ Title = "名字 ESP", Default = false, Callback = function(s) ESP.NameESP = s; if not s then ESP_UpdateHighlights(); end end })
    Tab:Toggle({ Title = "方框 ESP", Default = false, Callback = function(s) ESP.BoxESP = s; if not s then ESP_UpdateHighlights(); end end })
    Tab:Toggle({ Title = "追踪线 ESP", Default = false, Callback = function(s) ESP.TracerESP = s; if not s then ESP_UpdateHighlights(); end end })
    Tab:Toggle({ Title = "凶手出现提醒", Default = true, Callback = function(s) ESP.Alerts = s end })
    Tab:Toggle({
        Title = "掉落枪械高亮",
        Default = false,
        Callback = function(s) gunDropESPEnabled = s; updateGunDropESP(); end
    })
    Tab:Space()
    Tab:Paragraph({
        Title = "颜色说明",
        Desc = "红=杀手 蓝=警长 黄=英雄（警长死后） 绿=平民 灰=已死",
        ImageSize = 32,
    })
end

-- ===== 栏目二：自瞄 =====
do
    local Tab = AimSection:Tab({
        Title = "自瞄",
        Desc = "镜头自瞄 + 静默自动射击",
        Icon = "crosshair",
        IconColor = makeRainbowColor(60),
        IconShape = "Square",
        Border = true,
    })

    Tab:Section({ Title = "镜头自瞄", TextSize = 16, FontWeight = Enum.FontWeight.SemiBold })
    Tab:Dropdown({
        Title = "目标身份",
        Values = { "无", "警长", "杀手" },
        Value = "无",
        Callback = function(selected)
            lockedRole = ((selected ~= "无") and selected) or nil;
        end
    })
    Tab:Toggle({
        Title = "观察模式",
        Default = false,
        Callback = function(state)
            isSpectating = state;
            if state then
                originalCameraType = CurrentCamera.CameraType;
                originalCameraSubject = CurrentCamera.CameraSubject;
                CurrentCamera.CameraType = Enum.CameraType.Scriptable;
            else
                CurrentCamera.CameraType = originalCameraType;
                CurrentCamera.CameraSubject = originalCameraSubject;
            end
        end
    })
    Tab:Toggle({
        Title = "锁定镜头",
        Default = false,
        Callback = function(state)
            isCameraLocked = state;
            if (not state and not isSpectating) then
                CurrentCamera.CameraType = originalCameraType;
                CurrentCamera.CameraSubject = originalCameraSubject;
            end
        end
    })
    Tab:Toggle({ Title = "平滑自瞄", Default = false, Callback = function(s) AimbotConfig.SmoothAim = s end })
    Tab:Slider({
        Title = "平滑度（越小越慢）",
        Step = 0.05,
        Value = { Min = 0.05, Max = 1, Default = 0.5 },
        Callback = function(v) AimbotConfig.Smoothness = v end
    })
    Tab:Space()

    Tab:Section({ Title = "静默自瞄（只对杀手生效）", TextSize = 16, FontWeight = Enum.FontWeight.SemiBold })
    Tab:Toggle({
        Title = "静默自动射击",
        Desc = "开启后凶手进入 FOV 圈自动开枪，镜头不抖动",
        Default = false,
        Callback = function(state)
            SilentAimbot.Enabled = state
            if state then
                StartSilentAimbot()
                Notify("静默自瞄", "已开启！凶手进圈自动射击，记得把手枪拿在手上。")
            else
                StopSilentAimbot()
            end
        end,
    })
    Tab:Dropdown({
        Title = "目标部位（游戏部件名）",
        Values = { "Head", "HumanoidRootPart", "Torso" },
        Value = "Head",
        Callback = function(selected) SilentAimbot.TargetPart = selected end
    })
    Tab:Slider({
        Title = "FOV 半径",
        Value = { Min = 50, Max = 500, Default = 100 },
        Callback = function(v) SilentAimbot.FOV = v end
    })
    Tab:Slider({
        Title = "预判系数",
        Step = 0.01,
        Value = { Min = 0, Max = 0.5, Default = 0.165 },
        Callback = function(v) SilentAimbot.Prediction = v end
    })
    Tab:Toggle({
        Title = "显示 FOV 圈",
        Default = true,
        Callback = function(s)
            SilentAimbot.CircleVisible = s
            if SilentAimbot.Enabled then FOVCircle.Visible = s end
        end
    })
    Tab:Colorpicker({
        Title = "FOV 圈颜色",
        Default = Color3.fromRGB(255, 255, 255),
        Callback = function(c) SilentAimbot.CircleColor = c end
    })
    Tab:Toggle({ Title = "墙体检测", Default = true, Callback = function(s) SilentAimbot.WallCheck = s end })
end

