            end
        end,
    })
end

-- ===== 栏目六：平民 =====
do
    local Tab = InnocentSection:Tab({
        Title = "平民功能",
        Desc = "捡枪 / 自动捡枪 / 凶手躲避",
        Icon = "shield",
        IconColor = makeRainbowColor(300),
        IconShape = "Square",
        Border = true,
    })

    Tab:Section({ Title = "枪械功能", TextSize = 16, FontWeight = Enum.FontWeight.SemiBold })
    Tab:Toggle({
        Title = "掉落枪械提醒 / 高亮",
        Default = true,
        Callback = function(state) gunDropESPEnabled = state; updateGunDropESP(); end
    })
    Tab:Button({ Title = "捡枪", Callback = function() GrabGun(); end })
    Tab:Toggle({
        Title = "自动捡枪",
        Default = false,
        Callback = function(state)
            GunSystem.AutoGrabEnabled = state;
            if state then coroutine.wrap(AutoGrabGun)(); end
        end,
    })
    Tab:Button({
        Title = "捡枪并射击杀手",
        Callback = function()
            if not (LP.Character and LP.Character:FindFirstChild("Gun")) then
                if not GrabGun() then return; end
                task.wait(0.1);
            end
            if not EquipGun() then return; end

            ESP_UpdateRoles();
            local murderer = ESP.Murder and Players:FindFirstChild(ESP.Murder);
            if not murderer or not murderer.Character then
                Notify("枪械系统", "找不到杀手！")
                return;
            end

            local targetRoot = murderer.Character:FindFirstChild("HumanoidRootPart");
            local localRoot = LP.Character:FindFirstChild("HumanoidRootPart");
            if targetRoot and localRoot then
                localRoot.CFrame = targetRoot.CFrame * CFrame.new(0, 0, -4);
                task.wait(0.1);
            end

            local gun = LP.Character:FindFirstChild("Gun");
            if gun and gun:FindFirstChild("KnifeLocal") then
                local args = {[1] = 1, [2] = targetRoot.Position, [3] = "AH2"};
                gun.KnifeLocal.CreateBeam.RemoteFunction:InvokeServer(unpack(args));
                Notify("枪械系统", "已射击杀手！")
            end
        end,
    })
    Tab:Space()

    Tab:Section({ Title = "凶手躲避", TextSize = 16, FontWeight = Enum.FontWeight.SemiBold })
    Tab:Toggle({
        Title = "凶手躲避系统",
        Desc = "杀手靠近时自动反向逃跑",
        Default = false,
        Callback = function(state)
            EvasionSystem.Enabled = state
            if state then StartEvasion() else StopEvasion() end
        end,
    })
    Tab:Slider({
        Title = "躲避半径",
        Value = { Min = 15, Max = 100, Default = 35 },
        Callback = function(v) EvasionSystem.TriggerDistance = v end
    })
end

