    miniTopGrad.Transparency = NumberSequence.new(0.55, 1)
    miniTopGrad.Rotation = 90
    miniTopGrad.Parent = miniTopGlow

    local miniBottomGlow = Instance.new("Frame")
    miniBottomGlow.Name = "MiniBottomGlow"
    miniBottomGlow.Size = UDim2.new(1, 0, 0.45, 0)
    miniBottomGlow.Position = UDim2.new(0, 0, 0.55, 0)
    miniBottomGlow.BackgroundTransparency = 1
    miniBottomGlow.ZIndex = glowContainer.ZIndex
    miniBottomGlow.Parent = glowContainer

    local miniBottomGrad = Instance.new("UIGradient")
    miniBottomGrad.Color = makeRainbowColorSequence(180, 1, 1, 6)
    miniBottomGrad.Transparency = NumberSequence.new(1, 0.55)
    miniBottomGrad.Rotation = 90
    miniBottomGrad.Parent = miniBottomGlow

    task.spawn(function()
        while glowContainer and glowContainer.Parent do
            task.wait(0.05)
            glowGrad.Color = makeRainbowColorSequence(0, 1, 1, 8)
            glowStrokeGrad.Color = makeRainbowColorSequence(180, 1, 0.9, 6)
            miniTopGrad.Color = makeRainbowColorSequence(0, 1, 1, 6)
            miniBottomGrad.Color = makeRainbowColorSequence(180, 1, 1, 6)
        end
    end)
end)

