    Values = {"生肉块", "生牛排", "熟肉块", "熟牛排"},
    Value  = {},
    Multi  = true,
    Callback = function(options)
        selectedItems = {}
        for _, option in ipairs(options) do
            selectedItems[foodItems[option]] = true
        end
    end
