RunTest("writefile", function()
	Global.writefile("WXHUB_Test_File", "example")
	assert(Global.isfile("WXHUB_Test_File") == true, "Failed to create a file")
	assert(Global.readfile("WXHUB_Test_File") == "example", "File does not contain expected data")
end)

RunTest("isfile", function()
	assert(Global.isfile("WXHUB_Test_File") == true, "Did not return true for a valid file")
end)

RunTest("readfile", function()
	assert(Global.readfile("WXHUB_Test_File") == "example", "Did not return the expected data")
end)

RunTest("appendfile", function()
