  ApplySettingsTab = loadstring([[
return function(Window)
	local function CloneReference(Object)
		if WXHUB and WXHUB.Environment.cloneref then
			return WXHUB.Environment.cloneref(Object)
		else
			return Object
		end
	end
	
	local Services = setmetatable({}, {
		__index = function(self, Name)
			return CloneReference(game:GetService(Name))
		end
	})

	local Library = WXHUB.Interface.Library
	local SaveManager = WXHUB.Interface.SaveManager
	local ThemeManager = WXHUB.Interface.ThemeManager
	
	local Toggles = Library.Toggles
	local Options = Library.Options
	
	local SettingsTab = Window:AddTab("设置", "settings")
	local MenuGroup = SettingsTab:AddLeftGroupbox("菜单")
	
	MenuGroup:AddToggle("KeybindMenuOpen", {
		Default = Library.KeybindFrame.Visible,
		Text = "打开键位菜单",
		Callback = function(value)
			Library.KeybindFrame.Visible = value
		end,
	})
	MenuGroup:AddToggle("ShowCustomCursor", {
		Text = "自定义光标",
		Default = false,
		Callback = function(Value)
			Library.ShowCustomCursor = Value
		end,
	})

	MenuGroup:AddDropdown("UILibrary", {
		Text = "界面风格",
		Values = {
			"Obsidian",
			"Linoria"
		},
		Default = (WXHUB.UILibrary == "Linoria" and 2 or 1),
		Callback = function(Value)
			if WXHUB.Environment.writefile and WXHUB.Environment.readfile then
				if not WXHUB.Environment.isfile("WXHUB/UserData.json") then
					local Data = {
						TotalExecutions = 0,
						UILibrary = "Obsidian"
					}
					WXHUB.Environment.writefile("WXHUB/UserData.json", Services.HttpService:JSONEncode(Data))
				end

				local UserData = WXHUB.Environment.readfile("WXHUB/UserData.json")
				local Decoded = Services.HttpService:JSONDecode(UserData)
				Decoded.UILibrary = Value

				if not Decoded.UILibrary then
					Decoded.UILibrary = "Obsidian"
				end

				WXHUB.TotalExecutions = Decoded.TotalExecutions
				WXHUB.UILibrary = Decoded.UILibrary

				WXHUB.Environment.writefile("WXHUB/UserData.json", Services.HttpService:JSONEncode(Decoded))
			end
		end
	})
	
	MenuGroup:AddDropdown("DPIDropdown", {
		Values = { "50%", "75%", "100%", "125%", "150%", "175%", "200%" },
		Default = "100%",
	
		Text = "界面缩放",
	
		Callback = function(Value)
			Value = Value:gsub("%%", "")
			local DPI = tonumber(Value)
	
			Library:SetDPIScale(DPI)
		end,
	})
	MenuGroup:AddDivider()
	MenuGroup:AddLabel("菜单键位"):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = "菜单快捷键" })
	
	
	MenuGroup:AddButton("卸载", function()
		Library:Unload()
	end)
	
	Library.ToggleKeybind = Options.MenuKeybind
	
	ThemeManager:SetLibrary(Library)
	SaveManager:SetLibrary(Library)
	SaveManager:IgnoreThemeSettings()
	SaveManager:SetIgnoreIndexes({"UILibrary"})
	ThemeManager:SetFolder("WXHUB")
	SaveManager:SetFolder("WXHUB/" .. WXHUB.SavePath)
	SaveManager:BuildConfigSection(SettingsTab)
	ThemeManager:ApplyToTab(SettingsTab)
	SaveManager:LoadAutoloadConfig()
end

]])()
