--==============================================================================
-- WX HUB · 偷一个蛋（原 Chilli Hub 二改 · 原UI中文完整版）
-- 功能 100% 保留：自动偷蛋/摆蛋/传送带/孵化/装备/出售/融合/收藏/
--   Rift/Boss/Fractured/Dr Scramble 全模块 + 预测器 + 反守卫面板
-- 改动：
--   1) 删除官方 Discord（Webhook 上报模块 + DC 标签页，整块切除）
--   2) 删除 WebSocket 远程后门与远程守卫模块
--   3) 界面显示字符串全部中文化（选项/状态/预测器/设置栏）
--   4) 窗口更名 WX HUB · 偷一个蛋
--   5) 缩小图标替换为 W 圆圈，窗口加冰蓝色边框
--==============================================================================
-- ===== WX HUB 启动遮罩：加载期全屏黑幕，防原名/原图标闪现 =====
do
    local okGui, gui = pcall(function()
        local g = Instance.new("ScreenGui")
        g.Name = "WXHUB_BOOT"
        g.IgnoreGuiInset = true
        g.DisplayOrder = 10000
        g.ResetOnSpawn = false
        if typeof(gethui) == "function" then
            local ok, h = pcall(gethui)
            if ok and typeof(h) == "Instance" then
                g.Parent = h
                return g
            end
        end
        g.Parent = game:GetService("CoreGui")
        return g
    end)
    if okGui and gui then
        local f = Instance.new("Frame")
        f.Name = "BG"
        f.Size = UDim2.new(1, 0, 1, 0)
        f.BackgroundColor3 = Color3.new(0, 0, 0)
        f.BorderSizePixel = 0
        f.Parent = gui
        local t = Instance.new("TextLabel")
        t.BackgroundTransparency = 1
        t.Size = UDim2.new(0, 400, 0, 60)
        t.Position = UDim2.new(0.5, -200, 0.5, -34)
        t.Font = Enum.Font.GothamBlack
        t.Text = "WX HUB"
        t.TextColor3 = Color3.fromRGB(0, 170, 255)
        t.TextSize = 46
        t.Parent = f
        local t2 = Instance.new("TextLabel")
        t2.BackgroundTransparency = 1
        t2.Size = UDim2.new(0, 400, 0, 24)
        t2.Position = UDim2.new(0.5, -200, 0.5, 28)
        t2.Font = Enum.Font.Gotham
        t2.Text = "加载中，请稍候 ..."
        t2.TextColor3 = Color3.fromRGB(190, 190, 190)
        t2.TextSize = 16
        t2.Parent = f
        task.delay(4.5, function()
            pcall(function()
                local tw = game:GetService("TweenService")
                tw:Create(f, TweenInfo.new(0.6), { BackgroundTransparency = 1 }):Play()
                tw:Create(t, TweenInfo.new(0.6), { TextTransparency = 1 }):Play()
                tw:Create(t2, TweenInfo.new(0.6), { TextTransparency = 1 }):Play()
            end)
            task.wait(0.7)
            pcall(function() gui:Destroy() end)
        end)
    end
end

