        noteLabel.Visible = hasNote
        if hasNote then
            titleLabel.Position = UDim2.fromScale(0.025, 0.34)
            titleLabel.Size = UDim2.fromScale(0.65, 0.64 * noteVScale * NOTE_TITLE_SCALE)
