local function LoadChilliLibrary()
    local response = nil

    local function LoadChilliLibrary()
        if type(response) == "string" and #response > 0 then
            return response
        end
        response = ChilliLibrarySource
        return response
    end

    local function SafeRequire()
        local chilliHubSaeCleanup = (typeof(getgenv) == "function" and getgenv() or _G).ChilliHubSaeCleanup

        if type(chilliHubSaeCleanup) == "function" then
            pcall(chilliHubSaeCleanup)
        end

        local GameModules = { game:GetService("CoreGui") }

        if typeof(gethui) == "function" then
            local ok, result = pcall(gethui)
            ok = ok and typeof(result) == "Instance"

            if ok then
                table.insert(GameModules, result)
            end
        end

        local TaskLoop = {
            Settings = true,
            ChilliLeftCenter = true,
            ChilliLibrarySettings = true,
            ChilliLibraryLauncher = true,
        }
        local n = 0

        for _, v2 in ipairs(GameModules) do
            for _, child in ipairs(v2:GetChildren()) do
                if
                    child:IsA("ScreenGui")
                    and (child:GetAttribute("ChilliLibraryOwned") == true or TaskLoop[child.Name])
                then
                    pcall(function()
                        child:Destroy()
                    end)

                    n = n + 1
                end
            end
        end

        if n > 0 then
            DebugPrint("cleared " .. n .. " leftover Chilli UI screens")
        end
    end

    local function fn4()
        local chunk, v2 = loadstring((LoadChilliLibrary()))
        assert(chunk, v2)
        local v3 = chunk()
        assert(type(v3) == "function", "Chilli Library bootstrap is invalid.")
        local ScrambleSection = table.create(45)
        local n = 1

        for i = 1, 90, 2 do
            ScrambleSection[n] = string.char(
                bit32.bxor(
                    tonumber(
                        string.sub(
                            "306908100841206d474f00185f26635b2101387507010810127d7d477a473b6f435a0916573165562900226c00",
                            i,
                            i + 1
                        ),
                        16
                    ),
                    string.byte("s9K!2vQ#", (n - 1) % 8 + 1)
                )
            )
            n = n + 1
        end

        return v3(table.concat(ScrambleSection))
    end

    local str = "unknown"

    for i = 1, 6 do
        task.wait()
        pcall(SafeRequire)
        local ok, result = pcall(fn4)
        ok = ok and type(result) == "table"
        if ok then
            return result
        end
        str = tostring(result)

        if type(str) == "string" and string.find(str, "HttpGet", 1, true) then
            response = nil
        end

        DebugPrint("library load attempt " .. i .. " failed: " .. str)
        task.wait(1 + i * 0.5)
    end

    error("Chilli Library failed to load: " .. str, 0)
end

