        ["Close UI"] = "关闭界面", ["Open UI"] = "打开界面", ["UI Open Key"] = "界面开关键",
    }

    local DICT = {}
    for k, v in pairs(RAW) do
        DICT[k:lower()] = v
    end

    local function inScroller(inst)
        local p = inst.Parent
        while p and p ~= game do
            if p:IsA("ScrollingFrame") then return true end
            if p:IsA("ScreenGui") then return false end
            p = p.Parent
        end
        return false
    end

    -- 图标 → 去掉辣椒，放一个低调的小圆点（可见、可点按、无图案）
    local function makeCircle(icon)
        icon.Image = ""
        icon.BackgroundColor3 = Color3.fromRGB(24, 24, 28)
        icon.BackgroundTransparency = 0
        icon.BorderSizePixel = 0
        local c = icon:FindFirstChildOfClass("UICorner") or Instance.new("UICorner")
        c.CornerRadius = UDim.new(1, 0)
        c.Parent = icon
        local s = icon:FindFirstChildOfClass("UIStroke") or Instance.new("UIStroke")
        s.Color = Color3.fromRGB(150, 150, 160)
        s.Thickness = 1.5
        s.Transparency = 0.15
        s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        s.Parent = icon
        for _, ch in ipairs(icon:GetChildren()) do
            if ch:IsA("TextLabel") and ch.Name == "WXHUB_W" then
                ch:Destroy()
            end
        end
    end

    local function styleText(d)
        local t = d.Text
        if type(t) ~= "string" then return end
        if t:lower():find("hilli", 1, true) then
            if d.Text ~= "WX HUB" then
                d.Text = "WX HUB"
            end
            return
        end
        local zh = DICT[t:match("^%s*(.-)%s*$"):lower()]
        if zh and d.Text ~= zh then
            d.Text = zh
        end
    end

    local function styleStroke(d)
        local c = d.Color
        if c.R > 0.55 and c.G < 0.45 and c.B < 0.45 then
            d.Color = BLUE
        end
    end

    local function styleImage(d)
        if inScroller(d) then return end
        if math.max(d.AbsoluteSize.X, d.AbsoluteSize.Y) > 160 then return end
        local img = tostring(d.Image or "")
        if img ~= "" then
            makeCircle(d)
        end
    end

    local function styleInst(d)
        pcall(function()
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
                styleText(d)
            elseif d:IsA("UIStroke") then
                styleStroke(d)
            elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then
                styleImage(d)
            end
        end)
    end

    -- 全屋重刷（每轮都跑，库重绘也会被刷回）
    local isOurs
    local function fullPass(gui)
        for _, d in ipairs(gui:GetDescendants()) do
            styleInst(d)
        end
        local best, area = nil, 0
        for _, d in ipairs(gui:GetDescendants()) do
            if d:IsA("Frame") then
                local a = d.AbsoluteSize.X * d.AbsoluteSize.Y
                if a > area then best, area = d, a end
            end
        end
        if best and area > 40000 and isOurs(gui) then
            local s = best:FindFirstChildOfClass("UIStroke") or Instance.new("UIStroke")
            s.Color = BLUE
            s.Thickness = 2
            s.Transparency = 0.15
            s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            s.Parent = best
        end
    end

    local hooked = {}
    local function hookGui(gui)
        if hooked[gui] then return end
        hooked[gui] = true
        gui.DescendantAdded:Connect(function(d)
            task.defer(styleInst, d)
        end)
    end

    isOurs = function(gui)
        if gui:GetAttribute("ChilliLibraryOwned") == true then return true end
        local n = gui.Name
        if n:find("Chilli", 1, true) then return true end
        if n == "Settings" or n == "ChilliLeftCenter"
            or n == "ChilliLibraryLauncher" or n == "ChilliLibrarySettings" then
            return true
        end
        for _, d in ipairs(gui:GetDescendants()) do
            if d:IsA("TextLabel") and type(d.Text) == "string"
                and d.Text:lower():find("hilli", 1, true) then
                return true
            end
        end
        return false
    end

    local containers = {}
    local function refreshContainers()
        table.clear(containers)
        table.insert(containers, { c = game:GetService("CoreGui"), all = true })
        pcall(function()
            if typeof(gethui) == "function" then
                local h = gethui()
                if typeof(h) == "Instance" then table.insert(containers, { c = h, all = true }) end
            end
        end)
        pcall(function()
            if localPlayer and localPlayer.Parent then
                local pg = localPlayer:FindFirstChild("PlayerGui")
                if pg then table.insert(containers, { c = pg, all = false }) end
            end
        end)
    end

    local function scanAll()
        refreshContainers()
        for _, entry in ipairs(containers) do
            for _, gui in ipairs(entry.c:GetChildren()) do
                if not gui:IsA("ScreenGui") then continue end
                if entry.all or isOurs(gui) then
                    hookGui(gui)
                    fullPass(gui)
                end
            end
        end
    end

    -- 新 gui 一出生就接管 + 立刻全屋刷一遍
    local function watchContainer(c)
        pcall(function()
            c.ChildAdded:Connect(function(g)
                task.defer(function()
                    if g:IsA("ScreenGui") and isOurs(g) then
                        hookGui(g)
                        fullPass(g)
                    end
                end)
            end)
        end)
    end
    refreshContainers()
    for _, c in ipairs(containers) do watchContainer(c) end
    -- PlayerGui 可能晚到，单独等
    task.spawn(function()
        if localPlayer then
            local pg = localPlayer:WaitForChild("PlayerGui", 15)
            if pg then
                table.insert(containers, pg)
                watchContainer(pg)
                for _, g in ipairs(pg:GetChildren()) do
                    if g:IsA("ScreenGui") and isOurs(g) then
                        hookGui(g)
                        fullPass(g)
                    end
                end
            end
        end
    end)

    task.defer(scanAll)
    task.wait(0.5)
    while true do
        pcall(scanAll)
        task.wait(0.5)
    end
end)

