local RandomString

do
    local ScrambleSection = Random.new()
    local str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

    RandomString = function()
        local StealSection = ScrambleSection:NextInteger(12, 20)
        local PlaceSection = table.create(StealSection)

        for i = 1, StealSection do
            local TreadmillSection = ScrambleSection:NextInteger(1, #str)
            PlaceSection[i] =
                string.sub("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", TreadmillSection, TreadmillSection)
        end

        return table.concat(PlaceSection)
    end
end

--==============================================================================
-- 【小工具】  RegisterCleanup / DropdownShowAll / RandomString
--==============================================================================
local RegisterCleanup, DropdownShowAll

do
    local TaskLoop = {}

    RegisterCleanup = function(arg)
        table.insert(TaskLoop, arg)
    end

    local str = "All"

    DropdownShowAll = function(arg)
        if type(arg) ~= "table" then
            return arg
        end
        local value = rawget(arg, "Instance")
        if typeof(value) ~= "Instance" then
            return arg
        end
        local flag = false

        local function AveragePlacedPoints(arg2)
            if flag then
                return
            end

            if arg2.Text == "None" then
                flag = true
                arg2.Text = str
                flag = false
            end
        end

        local function WalkToInternal(arg2)
            if not arg2:IsA("TextLabel") or arg2.Name ~= "Value" then
                return
            end
            AveragePlacedPoints(arg2)

            local connection = arg2:GetPropertyChangedSignal("Text"):Connect(function()
                AveragePlacedPoints(arg2)
            end)

            RegisterCleanup(function()
                pcall(function()
                    connection:Disconnect()
                end)
            end)
        end

        for _, descendant in ipairs(value:GetDescendants()) do
            WalkToInternal(descendant)
        end

        local connection = value.DescendantAdded:Connect(WalkToInternal)

        RegisterCleanup(function()
            pcall(function()
                connection:Disconnect()
            end)
        end)

        return arg
    end

    local genv = typeof(getgenv) == "function" and getgenv() or _G
    local chilliHubSaeCleanup = genv.ChilliHubSaeCleanup

    if type(chilliHubSaeCleanup) == "function" then
        pcall(chilliHubSaeCleanup)
    end

    genv.ChilliHubSaeCleanup = function()
        for i = #TaskLoop, 1, -1 do
            pcall(TaskLoop[i])
        end

        table.clear(TaskLoop)
    end
end

do
    local n = 0
    local AveragePlacedPoints = nil

    AveragePlacedPoints = function(arg, arg2)
        local n2 = arg2 or 0

        if type(arg) == "table" then
            if 3 < n2 then
                return
            end
            local n3 = 0

            for k, ScrambleSection in pairs(arg) do
                n3 = n3 + 1

                if not (n3 > 20) then
                    AveragePlacedPoints(k, n2 + 1)
                    AveragePlacedPoints(ScrambleSection, n2 + 1)
                    continue
                end

                break
            end
        elseif typeof(arg) == "Instance" then
            pcall(arg.GetFullName, arg)
        else
            n = n + #tostring(arg)
        end
    end

    local TaskLoop = {}

    local function WalkToInternal(arg)
        local n2 = #TaskLoop + 1
        TaskLoop[n2] = arg
    end

    local function MutationLabel()
        for _, ScrambleSection in ipairs(TaskLoop) do
            pcall(function()
                ScrambleSection:Disconnect()
            end)
        end

        table.clear(TaskLoop)
    end

    local function ResetAutoSteal()
        MutationLabel()

        for _, ScrambleSection in ipairs({
            "RE/GearSatchel/Lost",
            "RE/GearSatchel/Gained",
            "RE/RigSync/ProbeSatchel",
            "RE/RigSync/SeedSatchel",
            "RE/RigSync/CorrectionBegan",
            "RE/RigSync/Refresh",
            "RE/ToolTrigger/Trigger",
            "RE/BatSwing/Trigger",
        }) do
            local StealSection = networking:FindFirstChild(ScrambleSection)

            if StealSection and StealSection:IsA("RemoteEvent") then
                WalkToInternal(StealSection.OnClientEvent:Connect(function(...)
                    AveragePlacedPoints({ ... })
                end))
            end
        end

        local function ResetAutoSteal(arg)
            if not arg then
                return
            end

            WalkToInternal(arg.ChildRemoved:Connect(function(arg2)
                if arg2:IsA("Tool") then
                    AveragePlacedPoints({ arg2.Name, arg2.Parent })
                end
            end))

            WalkToInternal(arg.ChildAdded:Connect(function(arg2)
                if arg2:IsA("Tool") then
                    AveragePlacedPoints({ arg2.Name })
                end
            end))
        end

        ResetAutoSteal(localPlayer:FindFirstChildOfClass("Backpack"))

        WalkToInternal(localPlayer.ChildAdded:Connect(function(arg)
            if arg:IsA("Backpack") then
                ResetAutoSteal(arg)
            end
        end))

        task.spawn(function()
            pcall(function()
                local ScrambleSection = require(ReplicatedStorage.Shared.Save).Get()
                AveragePlacedPoints({ ScrambleSection.GearInventory, ScrambleSection.Inventory }, 2)
            end)

            if type(getgc) == "function" then
                pcall(function()
                    for _, ScrambleSection in ipairs(getgc(false)) do
                        if type(ScrambleSection) == "function" and islclosure(ScrambleSection) then
                            pcall(debug.info, ScrambleSection, "n")
                        end
                    end
                end)
            end
        end)
    end

    local genv = typeof(getgenv) == "function" and getgenv() or _G
    genv.ChilliToolKeeper = ResetAutoSteal
    task.defer(ResetAutoSteal)
    RegisterCleanup(MutationLabel)
end

--==============================================================================
-- 【心跳任务调度器】  Heartbeat 任务队列 Add/Wake/Backoff
--==============================================================================
local TaskLoop

do
    local n = 0.35
    local n2 = 5
    local GlobalState = {}
    local flag = true

    TaskLoop = {
        Add = function(arg)
            local Hub = { Run = arg, Gap = n, Idle = n2, Repeat = false, Hold = 0 }
            table.insert(GlobalState, Hub)
            return Hub
        end,
        Wake = function()
            flag = true
        end,
        Backoff = function(arg, arg2)
            if arg then
                arg.Hold = tonumber(arg2) or 6
            end
        end,
    }

    local connection = RunService.Heartbeat:Connect(function(arg)
        local ScrambleSection = flag
        flag = false

        for _, StealSection in ipairs(GlobalState) do
            StealSection.Gap = StealSection.Gap + arg
            StealSection.Idle = StealSection.Idle + arg

            if 0 < StealSection.Hold then
                StealSection.Hold = StealSection.Hold - arg
            elseif StealSection.Gap >= n and (ScrambleSection or StealSection.Repeat or StealSection.Idle >= n2) then
                StealSection.Gap = 0
                StealSection.Idle = 0
                local ok, result = pcall(StealSection.Run, StealSection)
                ok = ok and result == true
                StealSection.Repeat = ok
            end
        end
    end)

    RegisterCleanup(function()
        connection:Disconnect()
    end)
end

