do
    local n = 0.5
    local v13 = nil
    local Hub = nil
    local BatNameHints = {}
    local flag = false
    local n2 = 0

    local function AveragePlacedPoints()
        for i = #BatNameHints, 1, -1 do
            local v14 = BatNameHints[i]

            if v14 and v14.Connected then
                v14:Disconnect()
            end

            BatNameHints[i] = nil
        end
    end

    local function WalkToInternal()
        AveragePlacedPoints()
        local v14 = v13
        local v15 = Hub
        v13 = nil
        Hub = nil
        if not v14 or not v14.Parent or not v15 then
            return
        end

        pcall(function()
            v14.BreakJointsOnDeath = v15.BreakJointsOnDeath
            v14.RequiresNeck = v15.RequiresNeck
            v14:SetStateEnabled(Enum.HumanoidStateType.Dead, v15.DeadEnabled)
        end)
    end

    local function MutationLabel(arg)
        if not arg or not arg.Parent then
            return false
        end

        local flag2 = pcall(function()
            arg.BreakJointsOnDeath = false
            arg.RequiresNeck = false
            arg:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        end) and arg.BreakJointsOnDeath == false and arg.RequiresNeck == false and arg:GetStateEnabled(
            Enum.HumanoidStateType.Dead
        ) == false

        return flag2
    end

    local function ResetAutoSteal(arg)
        if GlobalState.Paused or arg ~= v13 or not arg or not arg.Parent or flag then
            return false
        end
        local maxHealth = arg.MaxHealth
        if maxHealth <= 0 then
            return false
        end

        if maxHealth == math.huge or arg.Health >= maxHealth then
            return true
        end
        flag = true

        local ok = pcall(function()
            arg.Health = maxHealth
        end)

        flag = false
        ok = ok and arg.Health >= maxHealth
        return ok
    end

    local function fn12(arg)
        if arg == v13 and arg and arg.Parent then
            return true
        end
        WalkToInternal()
        if not arg or not arg:IsA("Humanoid") or not arg.Parent then
            return false
        end
        v13 = arg
        Hub = {
            BreakJointsOnDeath = arg.BreakJointsOnDeath,
            RequiresNeck = arg.RequiresNeck,
            DeadEnabled = arg:GetStateEnabled(Enum.HumanoidStateType.Dead),
        }
        if not MutationLabel(arg) then
            WalkToInternal()
            return false
        end
        ResetAutoSteal(arg)
        local n3 = #BatNameHints + 1

        BatNameHints[n3] = arg.HealthChanged:Connect(function()
            ResetAutoSteal(arg)
        end)

        local n4 = #BatNameHints + 1

        BatNameHints[n4] = arg:GetPropertyChangedSignal("MaxHealth"):Connect(function()
            ResetAutoSteal(arg)
        end)

        local n5 = #BatNameHints + 1

        BatNameHints[n5] = arg.StateChanged:Connect(function(arg2, arg3)
            if arg3 == Enum.HumanoidStateType.Dead and not GlobalState.Paused then
                MutationLabel(arg)
                ResetAutoSteal(arg)
            end
        end)

        n2 = os.clock()
        return true
    end

    local function fn13()
        local character = localPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid") or nil
        return humanoid
    end

    local connection = localPlayer.CharacterAdded:Connect(function()
        task.defer(function()
            fn12(fn13())
        end)
    end)

    local connection2 = RunService.Heartbeat:Connect(function()
        local now = os.clock()
        if GlobalState.Paused or now - n2 < n then
            return
        end
        n2 = now
        local v14 = fn13()
        if v14 ~= v13 then
            fn12(v14)
            return
        end

        if v14 then
            MutationLabel(v14)
            ResetAutoSteal(v14)
        end
    end)

    task.defer(function()
        fn12(fn13())
    end)

    RegisterCleanup(function()
        if connection then
            connection:Disconnect()
        end

        if connection2 then
            connection2:Disconnect()
        end

        WalkToInternal()
    end)
end

