	Text = "珠宝店提示",
	Default = false,
	Callback = function(val)
		if val then
			task.spawn(function()
				while Toggles.JewelNotify.Value do
					task.wait(0.1)
					local Ge = Workspace.GemRobbery:FindFirstChild("Rubble")
