local Remotes = ReplicatedStorage:WaitForChild("Remotes")
local PlayerCharRequest = Remotes:WaitForChild("PlayerCharacter"):WaitForChild("Request")
local QueueJumpRemote = PlayerCharRequest:WaitForChild("QueueJump")

