local noCooldownEnabled = false
local noCooldownConn
local noCooldownToolConn = nil

local function clearToolAnimations(tool)
    for _, obj in ipairs(tool:GetDescendants()) do
        if obj:IsA("Animation") then
            obj:Destroy()
        end
    end
    tool.Enabled = true
end

local function setupToolNoCooldown(tool)
    if noCooldownToolConn then noCooldownToolConn:Disconnect() end
    clearToolAnimations(tool)
    noCooldownToolConn = tool.Activated:Connect(function()
        if not noCooldownEnabled then return end
        tool.Enabled = true
        if humanoid then
            local animator = humanoid:FindFirstChildOfClass("Animator")
            if animator then
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                    track:Stop(0)
                end
            end
        end
        local handle = tool:FindFirstChild("Handle")
        if handle then
            local useSound = handle:FindFirstChild("UseSound")
            if useSound then useSound:Play() end
            local hitSound = handle:FindFirstChild("HitSound")
            if hitSound then hitSound:Play() end
        end
        local reps = ReplicatedStorage
        for _, obj in ipairs(reps:GetDescendants()) do
            if obj:IsA("RemoteEvent") then
                local nameLower = obj.Name:lower()
                if nameLower:find("attack") or nameLower:find("use") or nameLower:find("hit") or nameLower:find("shoot") or nameLower:find("swing") or nameLower:find("damage") then
                    pcall(function() obj:FireServer() end)
                end
            end
        end
    end)
end

MainLeft:AddToggle("武器无冷却", {
    Text = "武器无冷却",
    Default = false,
    Tooltip = "移除武器攻击动画延迟",
}):OnChanged(function(value)
    noCooldownEnabled = value
    if value then
        local tool = character:FindFirstChildOfClass("Tool")
        if tool then setupToolNoCooldown(tool) end
        noCooldownConn = RunService.Heartbeat:Connect(function()
            local tool = character:FindFirstChildOfClass("Tool")
            if tool then
                clearToolAnimations(tool)
                if not noCooldownToolConn then
                    setupToolNoCooldown(tool)
                end
            end
        end)
    else
        if noCooldownConn then noCooldownConn:Disconnect() end
        if noCooldownToolConn then noCooldownToolConn:Disconnect() end
        noCooldownToolConn = nil
    end
end)

