MainRight:AddToggle("自动躲怪", {
    Text = "自动躲怪",
    Default = false,
    Tooltip = "在怪物周围生成安全圈，人物无法踏入",
}):OnChanged(function(value)
    autoDodgeEnabled = value
    if value then
        dodgeConn = RunService.Heartbeat:Connect(function()
            if not humanoidRootPart then return end
            local myPos = humanoidRootPart.Position
            local monsters = getMonsterPositions()
            for _, monsterPos in ipairs(monsters) do
                local dist = (myPos - monsterPos).Magnitude
                if dist < safeRadius then
                    local pushDir = (myPos - monsterPos).Unit
                    if pushDir.Magnitude < 0.001 then
                        pushDir = Vector3.new(1, 0, 0)
                    end
                    local targetPos = monsterPos + pushDir * (safeRadius + 2)
                    humanoidRootPart.CFrame = CFrame.new(targetPos)
                    if humanoid then
                        humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end
                end
            end
        end)
    else
        if dodgeConn then dodgeConn:Disconnect() end
    end
end)

