        task.spawn(function()
            while autoScrapEnabled do
                if humanoidRootPart then
                    local scraps = getScraps()
                    for _, scrap in ipairs(scraps) do
                        if not autoScrapEnabled then break end
                        local prompt = scrap:FindFirstChild("ProximityPrompt")
                        if prompt and scrap.Parent then
