    lplr.CharacterAdded:Wait()
    task.wait(0.5)
    local newChar = lplr.Character
    if newChar then
        local newHrp = newChar:WaitForChild("HumanoidRootPart", 3)
        if newHrp then
            newHrp.CFrame = currentPos
