    Callback = function(Value)
        followEnabled = Value
        if followConn then
            followConn:Disconnect()
            followConn = nil
        end
        if Value then
            local targetPlayer = followTarget
            if not targetPlayer then return end
            local name = targetPlayer.Name
            if name == "UchihaBan91Edition" or name == "Ooosleoekeird" then
                Library:Notify({
                    Title = "锁定失败",
