local needleCache = {}

local function clearNeedleESP()
    for _, data in pairs(needleCache) do
        if data.Highlight then data.Highlight:Destroy() end
        if data.Billboard then data.Billboard:Destroy() end
    end
    needleCache = {}
end

local function createNeedleESP(needleObj)
    if needleCache[needleObj] then return end

    local targetPart = nil
    if needleObj:IsA("Model") then
        targetPart = needleObj:FindFirstChildWhichIsA("BasePart") or needleObj:FindFirstChildWhichIsA("UnionOperation") or needleObj:FindFirstChildWhichIsA("MeshPart")
        if not targetPart then
            for _, child in ipairs(needleObj:GetDescendants()) do
                if child:IsA("BasePart") or child:IsA("UnionOperation") or child:IsA("MeshPart") then
                    targetPart = child
                    break
                end
            end
        end
    elseif needleObj:IsA("BasePart") or needleObj:IsA("UnionOperation") or needleObj:IsA("MeshPart") then
        targetPart = needleObj
    end

    if not targetPart then return end

    local highlight = Instance.new("Highlight")
    highlight.Name = "NeedleHighlight"
    highlight.FillColor = Color3.fromRGB(0, 255, 0)
    highlight.OutlineColor = Color3.fromRGB(0, 200, 0)
    highlight.FillTransparency = 0.3
    highlight.OutlineTransparency = 0
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Adornee = needleObj
    highlight.Parent = needleObj

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "NeedleBillboard"
    billboard.Size = UDim2.new(0, 200, 0, 60)
    billboard.StudsOffset = Vector3.new(0, 3, 0)
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = 5000
    billboard.Parent = targetPart

    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(1, 0, 1, 0)
    frame.BackgroundTransparency = 1
    frame.Parent = billboard

    local nameLabel = Instance.new("TextLabel")
    nameLabel.Name = "NameLabel"
    nameLabel.Size = UDim2.new(1, 0, 0.5, 0)
    nameLabel.BackgroundTransparency = 1
    nameLabel.Text = "针"
    nameLabel.TextColor3 = Color3.fromRGB(0, 255, 0)
    nameLabel.TextStrokeTransparency = 0.2
    nameLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    nameLabel.Font = Enum.Font.GothamBold
    nameLabel.TextSize = 18
    nameLabel.Parent = frame

    local distLabel = Instance.new("TextLabel")
    distLabel.Name = "DistLabel"
    distLabel.Size = UDim2.new(1, 0, 0.5, 0)
    distLabel.Position = UDim2.new(0, 0, 0.5, 0)
    distLabel.BackgroundTransparency = 1
    distLabel.Text = "距离: 0 studs"
    distLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    distLabel.TextStrokeTransparency = 0.2
    distLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    distLabel.Font = Enum.Font.GothamBold
    distLabel.TextSize = 14
    distLabel.Parent = frame

    needleCache[needleObj] = {
        Highlight = highlight,
        Billboard = billboard,
        TargetPart = targetPart,
        DistLabel = distLabel
    }
end

local function scanNeedles()
    local found = {}
    local function checkObj(obj)
        if not obj then return end
        local name = obj.Name:lower()
        if name:find("needle") and not name:find("objectiveserver") then
            found[obj] = true
        end
    end
    checkObj(Workspace:FindFirstChild("The Needle"))
    checkObj(Workspace:FindFirstChild("HiddenNeedleClient"))
    for _, child in ipairs(Workspace:GetChildren()) do
        checkObj(child)
    end
    for obj, _ in pairs(found) do
        createNeedleESP(obj)
    end
end

local function updateNeedleESP()
    if not hrp then return end
    local playerPos = hrp.Position
    for obj, data in pairs(needleCache) do
        if not obj or not obj.Parent then
            if data.Highlight then data.Highlight:Destroy() end
            if data.Billboard then data.Billboard:Destroy() end
            needleCache[obj] = nil
        else
            local part = data.TargetPart
            if not part or not part.Parent then
                if data.Highlight then data.Highlight:Destroy() end
                if data.Billboard then data.Billboard:Destroy() end
                needleCache[obj] = nil
            else
                local dist = (part.Position - playerPos).Magnitude
                if dist > 5000 then
                    data.Billboard.Enabled = false
                    data.Highlight.Enabled = false
                else
                    data.Billboard.Enabled = true
                    data.Highlight.Enabled = true
                    if data.DistLabel then
                        data.DistLabel.Text = "距离: " .. math.floor(dist) .. " studs"
                    end
                end
            end
        end
    end
end

local espRunning = false
local espConnection = nil

local function startNeedleESP()
    if espRunning then return end
    espRunning = true
    scanNeedles()
    espConnection = RunService.RenderStepped:Connect(function()
        if Toggles.NeedleESP and Toggles.NeedleESP.Value then
            updateNeedleESP()
        end
    end)
end

local function stopNeedleESP()
    espRunning = false
    if espConnection then
        espConnection:Disconnect()
        espConnection = nil
    end
    clearNeedleESP()
end

if Toggles.NeedleESP then
    Toggles.NeedleESP:OnChanged(function(value)
        if value then
            startNeedleESP()
            Library:Notify({ Title = "针透视", Description = "已开启针透视", Time = 3 })
        else
            stopNeedleESP()
        end
    end)
end

Workspace.ChildAdded:Connect(function(child)
    if Toggles.NeedleESP and Toggles.NeedleESP.Value then
        if child.Name:lower():find("needle") then
            task.wait(0.5)
            createNeedleESP(child)
        end
    end
end)

if Toggles.NeedleESP and Toggles.NeedleESP.Value then
    startNeedleESP()
end

local function extractNumberFromName(name)
    local digits = name:gsub("%D", "")
    return tonumber(digits)
end

local function findAllHaystackCollisionFolders(parent)
    local results = {}
    local function scan(p)
        for _, child in ipairs(p:GetChildren()) do
            if child:IsA("Folder") and child.Name == "HaystackCollision" then
                table.insert(results, child)
            end
            scan(child)
        end
    end
    scan(parent)
    return results
end

local function getPickableItems()
    local items = {}
    if not character then return items end
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return items end
    local range = Options.PickRange and Options.PickRange.Value or 50
    local playerPos = root.Position

    local folders = findAllHaystackCollisionFolders(Workspace)
    for _, folder in ipairs(folders) do
        for _, obj in ipairs(folder:GetDescendants()) do
            if obj:IsA("BasePart") or obj:IsA("MeshPart") or obj:IsA("UnionOperation") then
                local num = extractNumberFromName(obj.Name)
                if num then
                    local dist = (obj.Position - playerPos).Magnitude
                    if dist <= range then
                        table.insert(items, {Obj = obj, Number = num, Distance = dist})
                    end
                end
            end
        end
    end

    table.sort(items, function(a, b) return a.Distance < b.Distance end)
    return items
end

local autoPickRunning = false

local function startAutoPick()
    if autoPickRunning then return end
    autoPickRunning = true
    task.spawn(function()
        while autoPickRunning and Toggles.AutoPick and Toggles.AutoPick.Value do
            local items = getPickableItems()
            if #items > 0 then
                local target = items[1]
                local pickEvent = ReplicatedStorage:WaitForChild("NeedleHaystack"):WaitForChild("PickHay")
                if Toggles.BypassDist and Toggles.BypassDist.Value and hrp then
                    local oldCF = hrp.CFrame
                    hrp.CFrame = CFrame.new(target.Obj.Position + Vector3.new(0, 3, 0))
                    pickEvent:FireServer(target.Number, {})
                    hrp.CFrame = oldCF
                else
                    pickEvent:FireServer(target.Number, {})
                end
            end
            local speed = Options.PickSpeed and Options.PickSpeed.Value or 0.5
            task.wait(speed)
        end
        autoPickRunning = false
    end)
end

local function stopAutoPick()
    autoPickRunning = false
end

if Toggles.AutoPick then
    Toggles.AutoPick:OnChanged(function(value)
        if value then
            startAutoPick()
            Library:Notify({ Title = "自动拾取", Description = "已开启自动拾取", Time = 3 })
        else
            stopAutoPick()
        end
    end)
end

local autoSellRunning = false

local function startAutoSell()
    if autoSellRunning then return end
    autoSellRunning = true
    task.spawn(function()
        while autoSellRunning and Toggles.AutoSell and Toggles.AutoSell.Value do
            local sellEvent = ReplicatedStorage:WaitForChild("NeedleHaystack"):WaitForChild("SellHay")
            sellEvent:FireServer()
            local interval = Options.SellInterval and Options.SellInterval.Value or 3
            task.wait(interval)
        end
        autoSellRunning = false
    end)
end

local function stopAutoSell()
    autoSellRunning = false
end

if Toggles.AutoSell then
    Toggles.AutoSell:OnChanged(function(value)
        if value then
            startAutoSell()
            Library:Notify({ Title = "自动出售", Description = "已开启自动出售", Time = 3 })
        else
            stopAutoSell()
        end
    end)
end
