do
    local borderConnection = nil
    local function ensureBlurElement()
        local mf = Window.UIElements and Window.UIElements.Main
        if not mf then return end
        local blur = mf:FindFirstChild("Blur")
        if not blur then
            blur = Instance.new("ImageLabel")
            blur.Name = "Blur"; blur.Size = UDim2.new(1, 0, 1, 0)
            blur.BackgroundTransparency = 1
            blur.Image = "rbxasset://textures/ui/GuiImagePlaceholder.png"
            blur.ImageTransparency = 0.15; blur.ZIndex = 0; blur.Parent = mf
        end
        return blur
    end
    local function applyRainbowBorderColor(c, transparency)
        transparency = transparency or 0.15
        local f = c.UIElements and c.UIElements.Main or c
        if not f then return false end
        local g = f:FindFirstChild("Blur", true)
        if g and g:IsA("ImageLabel") then
            g.ImageColor3 = makeRainbowColor(0); g.ImageTransparency = transparency
            local eg = g:FindFirstChild("WXHUBBorderGrad")
            if not eg then
                eg = Instance.new("UIGradient"); eg.Name = "WXHUBBorderGrad"
                eg.Color = makeRainbowColorSequence(0, 1, 1, 6); eg.Rotation = 0; eg.Parent = g
            else eg.Color = makeRainbowColorSequence(0, 1, 1, 6); eg.Rotation = 0 end
            return true
        end
        return false
    end
    local function startBorderAnimation()
        if borderConnection then borderConnection:Disconnect(); borderConnection = nil end
        ensureBlurElement()
        borderConnection = RunService.Heartbeat:Connect(function()
            local mf = Window.UIElements and Window.UIElements.Main
            if not mf or not mf.Visible then return end
            applyRainbowBorderColor(Window, 0.15)
        end)
    end
    local function stopBorderAnimation()
        if borderConnection then borderConnection:Disconnect(); borderConnection = nil end
    end
    local function setupVisibilityListener()
        local mf = Window.UIElements and Window.UIElements.Main
        if not mf then
            task.spawn(function()
                repeat task.wait() until Window.UIElements and Window.UIElements.Main
                setupVisibilityListener()
            end)
            return
        end
        if mf.Visible then startBorderAnimation() else stopBorderAnimation() end
        mf:GetPropertyChangedSignal("Visible"):Connect(function()
            if mf.Visible then startBorderAnimation() else stopBorderAnimation() end
        end)
    end
    setupVisibilityListener()
    Window:OnClose(function() stopBorderAnimation() end)
end

