-- ==================== WX HUB 彩虹界面（冰冷黄昏同款） ====================
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local WindUI = loadstring(game:HttpGet("https://raw.githubusercontent.com/Footagesus/WindUI/main/dist/main.lua"))()
local MarketplaceService = game:GetService("MarketplaceService")
local RunService = game:GetService("RunService")

local function getPlaceName()
    local ok, info = pcall(function() return MarketplaceService:GetProductInfo(game.PlaceId) end)
    return (ok and info and info.Name) or game.Name
end
local placeName = getPlaceName()

local function hsvToRgb(h, s, v)
    local r, g, b
    local i = math.floor(h / 60) % 6
    local f = (h / 60) - math.floor(h / 60)
    local p = v * (1 - s)
    local q = v * (1 - f * s)
    local t = v * (1 - (1 - f) * s)
    if i == 0 then r, g, b = v, t, p
    elseif i == 1 then r, g, b = q, v, p
    elseif i == 2 then r, g, b = p, v, t
    elseif i == 3 then r, g, b = p, q, v
    elseif i == 4 then r, g, b = t, p, v
    else r, g, b = v, p, q end
    return Color3.new(r, g, b)
end

local function makeRainbowColor(timeOffset, saturation, value)
    saturation = saturation or 1; value = value or 1
    local hue = (tick() * 60 + (timeOffset or 0)) % 360
    return hsvToRgb(hue, saturation, value)
end

local function makeRainbowColorSequence(timeOffset, saturation, value, count)
    saturation = saturation or 1; value = value or 1; count = count or 6
    local hueOffset = (tick() * 60 + (timeOffset or 0)) % 360
    local keypoints = {}
    for i = 0, count - 1 do
        local hue = (hueOffset + (i / count) * 360) % 360
        keypoints[i + 1] = ColorSequenceKeypoint.new(i / (count - 1), hsvToRgb(hue, saturation, value))
    end
    return ColorSequence.new(keypoints)
end

local function gradient3(text, color1, color2, color3)
    local result = ""
    local chars = {}
    for uchar in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do table.insert(chars, uchar) end
    local length = #chars
    for i = 1, length do
        local t = (i - 1) / math.max(length - 1, 1)
        local r, g, b
        if t < 0.5 then
            local s = t * 2
            r = color1.R + (color2.R - color1.R) * s
            g = color1.G + (color2.G - color1.G) * s
            b = color1.B + (color2.B - color1.B) * s
        else
            local s = (t - 0.5) * 2
            r = color2.R + (color3.R - color2.R) * s
            g = color2.G + (color3.G - color2.G) * s
            b = color2.B + (color3.B - color2.B) * s
        end
        result = result .. string.format('<font color="rgb(%d,%d,%d)">%s</font>',
            math.floor(r * 255), math.floor(g * 255), math.floor(b * 255), chars[i])
    end
    return result
end

local titleColor1 = hsvToRgb(0, 1, 1)
local titleColor2 = hsvToRgb(120, 1, 1)
local titleColor3 = hsvToRgb(240, 1, 1)

local Window = WindUI:CreateWindow({
    Title = gradient3("WX HUB", titleColor1, titleColor2, titleColor3),
    Author = gradient3("最终战场 | WX HUB", titleColor3, titleColor1, titleColor2),
    Icon = "wind",
    IconThemed = false,
    Folder = "WXHUB_KB",
    Size = UDim2.fromOffset(580, 420),
    Transparent = true,
    Theme = "Dark",
    SideBarWidth = 160,
    HideSearchBar = false,
    ScrollBarEnabled = true,
})

Window:Tag({ Title = placeName, Radius = 5, Color = makeRainbowColor(0) })

Window:EditOpenButton({
    Title = "WX HUB",
    Icon = "wind",
    CornerRadius = UDim.new(0, 8),
    StrokeThickness = 2,
    Color = makeRainbowColorSequence(0, 1, 1, 6),
    Glow = true,
    GlowColor = makeRainbowColor(180),
    GlowTransparency = 0.35,
    Draggable = true,
})

task.spawn(function()
    repeat task.wait() until Window.OpenButtonMain and Window.OpenButtonMain.Button
    local btn = Window.OpenButtonMain.Button
    local tl = btn:FindFirstChildWhichIsA("TextLabel")
    if tl then
        tl.TextColor3 = makeRainbowColor(0)
        tl.TextStrokeTransparency = 0.7
        tl.TextStrokeColor3 = Color3.fromRGB(30, 30, 30)
    end
    local ic = btn:FindFirstChildWhichIsA("ImageLabel")
    if ic then ic.ImageColor3 = makeRainbowColor(120) end
end)

do
    local borderConnection = nil
    local function ensureBlurElement()
        local mf = Window.UIElements and Window.UIElements.Main
        if not mf then return end
        local blur = mf:FindFirstChild("Blur")
        if not blur then
            blur = Instance.new("ImageLabel")
            blur.Name = "Blur"; blur.Size = UDim2.new(1, 0, 1, 0)
            blur.BackgroundTransparency = 1
            blur.Image = "rbxasset://textures/ui/GuiImagePlaceholder.png"
            blur.ImageTransparency = 0.15; blur.ZIndex = 0; blur.Parent = mf
        end
        return blur
    end
    local function applyRainbowBorderColor(c, transparency)
        transparency = transparency or 0.15
        local f = c.UIElements and c.UIElements.Main or c
        if not f then return false end
        local g = f:FindFirstChild("Blur", true)
        if g and g:IsA("ImageLabel") then
            g.ImageColor3 = makeRainbowColor(0); g.ImageTransparency = transparency
            local eg = g:FindFirstChild("WXHUBBorderGrad")
            if not eg then
                eg = Instance.new("UIGradient"); eg.Name = "WXHUBBorderGrad"
                eg.Color = makeRainbowColorSequence(0, 1, 1, 6); eg.Rotation = 0; eg.Parent = g
            else eg.Color = makeRainbowColorSequence(0, 1, 1, 6); eg.Rotation = 0 end
            return true
        end
        return false
    end
    local function startBorderAnimation()
        if borderConnection then borderConnection:Disconnect(); borderConnection = nil end
        ensureBlurElement()
        borderConnection = RunService.Heartbeat:Connect(function()
            local mf = Window.UIElements and Window.UIElements.Main
            if not mf or not mf.Visible then return end
            applyRainbowBorderColor(Window, 0.15)
        end)
    end
    local function stopBorderAnimation()
        if borderConnection then borderConnection:Disconnect(); borderConnection = nil end
    end
    local function setupVisibilityListener()
        local mf = Window.UIElements and Window.UIElements.Main
        if not mf then
            task.spawn(function()
                repeat task.wait() until Window.UIElements and Window.UIElements.Main
                setupVisibilityListener()
            end)
            return
        end
        if mf.Visible then startBorderAnimation() else stopBorderAnimation() end
        mf:GetPropertyChangedSignal("Visible"):Connect(function()
            if mf.Visible then startBorderAnimation() else stopBorderAnimation() end
        end)
    end
    setupVisibilityListener()
    Window:OnClose(function() stopBorderAnimation() end)
end

task.spawn(function()
    repeat task.wait() until Window.UIElements and Window.UIElements.Main
    local mc = Window.UIElements.Main
    if not mc then return end
    local stroke = Instance.new("UIStroke")
    stroke.Name = "WXHUBStroke"; stroke.Thickness = 2
    stroke.Color = makeRainbowColor(0); stroke.Transparency = 0.3
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; stroke.Parent = mc
    local ge = Instance.new("UIGradient")
    ge.Name = "WXHUBGradient"; ge.Color = makeRainbowColorSequence(0, 1, 1, 7)
    ge.Rotation = 0; ge.Parent = stroke
    task.spawn(function()
        while mc and mc.Parent do
