        local backpack = LocalPlayer.Backpack
        if backpack then
            local tool = backpack:FindFirstChildOfClass("Tool")
            if tool and LocalPlayer.Character then
                LocalPlayer.Character.Humanoid:EquipTool(tool)
            end
        end
    end)
end

