local function refreshEnemies()
    if tick() - lastEnemyCache < 0.1 then return enemyCache end
    enemyCache = {}
    local function scanFolder(folder)
        for _, model in ipairs(folder:GetChildren()) do
            if model:IsA("Model") and model:FindFirstChildOfClass("Humanoid") then
                local isPlayer = false
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr.Character == model then
                        isPlayer = true
                        break
                    end
                end
                if not isPlayer then
                    local hum = model:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        table.insert(enemyCache, model)
                    end
                end
            end
            if model:IsA("Folder") or model:IsA("Model") then
                scanFolder(model)
            end
        end
    end
    scanFolder(Workspace)
    lastEnemyCache = tick()
    return enemyCache
end

local function getEnemyPart(enemy)
    return enemy:FindFirstChild("HumanoidRootPart") or enemy:FindFirstChild("Head") or enemy:FindFirstChildWhichIsA("BasePart")
end

local enemyEspEnabled = false
local enemyEspRunning = false

local function updateEnemyEsp()
    if not player.Character or not player.Character:FindFirstChild("HumanoidRootPart") then return end
    local hrp = player.Character.HumanoidRootPart

    for item, ld in pairs(enemyLabelMap) do
        recycleLabel(ld.nl, enemyLabelPool)
        recycleLabel(ld.dl, enemyLabelPool)
    end
    enemyLabelMap = {}

    local enemies = refreshEnemies()
    for _, enemy in ipairs(enemies) do
        if not enemy or not enemy.Parent then continue end
        local part = getEnemyPart(enemy)
        if not part then continue end

        local pos = part.Position + Vector3.new(0, 3, 0)
        local screenPos, onScreen = camera:WorldToViewportPoint(pos)
        if onScreen and screenPos.Z > 0 then
            local dist = (hrp.Position - part.Position).Magnitude
            local ld = {}
            local nl = getLabel(enemyContainer, enemyLabelPool)
            nl.Text = enemy.Name
            nl.TextColor3 = Color3.fromRGB(255, 0, 0)
            nl.TextSize = 12
            nl.Position = UDim2.new(0, screenPos.X - 100, 0, screenPos.Y - 20)
            nl.Visible = true
            ld.nl = nl

            local dl = getLabel(enemyContainer, enemyLabelPool)
            dl.Text = string.format("%.1fm", dist)
            dl.TextColor3 = Color3.fromRGB(0, 255, 255)
            dl.TextSize = 11
            dl.Position = UDim2.new(0, screenPos.X - 100, 0, screenPos.Y - 8)
            dl.Visible = true
            ld.dl = dl

            enemyLabelMap[enemy] = ld
        end
    end
end

local function enemyEspLoop()
    if enemyEspRunning then return end
    enemyEspRunning = true
    task.spawn(function()
        while enemyEspEnabled do
            updateEnemyEsp()
            task.wait(0.5)
        end
        for item, ld in pairs(enemyLabelMap) do
            recycleLabel(ld.nl, enemyLabelPool)
            recycleLabel(ld.dl, enemyLabelPool)
        end
        enemyLabelMap = {}
        enemyEspRunning = false
    end)
end

