local killAuraEnabled = false
local killAuraRange = 20
local dummyParts = {}

local function createDummy(enemy)
    if dummyParts[enemy] and dummyParts[enemy].Parent then
        return dummyParts[enemy]
    end
    local part = getEnemyPart(enemy)
    if not part then return nil end
    local dummy = Instance.new("Part")
    dummy.Name = "KillAuraDummy_" .. enemy.Name
    dummy.Size = Vector3.new(2, 0.5, 2)
    dummy.CFrame = part.CFrame * CFrame.new(0, -3, 0)
    dummy.Anchored = true
    dummy.CanCollide = false
    dummy.Transparency = 1
    pcall(function() dummy.CanQuery = false end)
    pcall(function() dummy.CanTouch = false end)
    dummy.Parent = workspace
    dummyParts[enemy] = dummy
    local conn
    conn = enemy.AncestryChanged:Connect(function()
        if not enemy.Parent then
            pcall(function()
                if dummy and dummy.Parent then
                    dummy:Destroy()
                end
            end)
            dummyParts[enemy] = nil
            if conn then
                pcall(function() conn:Disconnect() end)
            end
        end
    end)
    return dummy
end

local function updateDummies()
    for enemy, dummy in pairs(dummyParts) do
        if enemy and enemy.Parent and dummy and dummy.Parent then
            local part = getEnemyPart(enemy)
            if part then
                pcall(function()
                    dummy.CFrame = part.CFrame * CFrame.new(0, -3, 0)
                end)
            end
        elseif dummy and dummy.Parent then
            pcall(function() dummy:Destroy() end)
            dummyParts[enemy] = nil
        end
    end
end

local function clearDummies()
    for enemy, dummy in pairs(dummyParts) do
        if dummy and dummy.Parent then
            pcall(function() dummy:Destroy() end)
        end
    end
    dummyParts = {}
end

local function getEquippedGun()
    local char = player.Character
    if not char then return nil end
    for _, obj in ipairs(char:GetChildren()) do
        if obj.Name == "Fists" then continue end
        if obj:IsA("Tool") or obj:IsA("Model") then
            local events = obj:FindFirstChild("Events")
            if events then
                if events:FindFirstChild("Fire") and events:FindFirstChild("Ready") then
                    return obj
                end
            end
        end
        if obj:IsA("Model") then
            for _, sub in ipairs(obj:GetChildren()) do
                if sub.Name == "Fists" then continue end
                if sub:IsA("Tool") or sub:IsA("Model") then
                    local events2 = sub:FindFirstChild("Events")
                    if events2 then
                        if events2:FindFirstChild("Fire") and events2:FindFirstChild("Ready") then
                            return sub
                        end
                    end
                end
            end
        end
    end
    return nil
end

