local function GetHeldTool()
    if not LocalPlayer then return nil end
    local char = LocalPlayer.Character
    if char then
        for _, obj in ipairs(char:GetChildren()) do
            if obj:IsA("Tool") then
                return obj
            end
        end
    end
    return nil
end

local function GetHeldWeaponInfo()
    local tool = GetHeldTool()
    if not tool then
        return nil, nil, "无"
    end
    local name = tool.Name
    if CONFIG.MeleeWeapons[name] then
        return name, "Melee", "近战"
    elseif CONFIG.GunWeapons[name] then
        return name, "Gun", "枪械"
    end
    local comp = string.gsub(string.gsub(string.upper(name), " ", ""), "_", "")
    for w in pairs(CONFIG.MeleeWeapons) do
        if comp == string.gsub(string.gsub(string.upper(w), " ", ""), "_", "") then
            return name, "Melee", "近战"
        end
    end
    for w in pairs(CONFIG.GunWeapons) do
        if comp == string.gsub(string.gsub(string.upper(w), " ", ""), "_", "") then
            return name, "Gun", "枪械"
        end
    end
    return nil, nil, "未知"
end

local WEAPON_NAME_MAP = {
    ["冲锋枪"] = "TommyGun",
    ["加特林"] = "Minigun",
    ["彩虹加特林"] = "Rainbow Minigun",
    ["狙击步枪"] = "SniperRifle",
    ["火箭发射器"] = "RocketLauncher",
    ["汉堡喷射枪"] = "BurgerBlaster",
    ["通用枪械"] = "Gun_Tool",
    ["锅铲"] = "Spatula",
    ["砍肉刀"] = "Cleaver",
    ["扳手"] = "Wrench",
    ["武士刀"] = "Katanna",
}

local ALL_WEAPON_NAMES = {}
for w in pairs(CONFIG.MeleeWeapons) do table.insert(ALL_WEAPON_NAMES, w) end
for w in pairs(CONFIG.GunWeapons) do table.insert(ALL_WEAPON_NAMES, w) end
table.sort(ALL_WEAPON_NAMES)

local function MatchWeapon(input)
    if not input then return nil end
    local upper = string.upper(input)
    for _, name in ipairs(ALL_WEAPON_NAMES) do
        if string.upper(name):find(upper, 1, true) then
            return name
        end
    end
    local comp = string.gsub(string.gsub(upper, " ", ""), "_", "")
    for _, name in ipairs(ALL_WEAPON_NAMES) do
        local cname = string.gsub(string.gsub(string.upper(name), " ", ""), "_", "")
        if cname:find(comp, 1, true) or comp:find(cname, 1, true) then
            return name
        end
    end
    return nil
end

local function NameEq(a, b)
    if not a or not b then return false end
    return string.gsub(string.gsub(string.upper(a), " ", ""), "_", "")
        == string.gsub(string.gsub(string.upper(b), " ", ""), "_", "")
end

local function FindToolRecursive(root, weaponName)
    if not root then return nil, nil end
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("Tool") and NameEq(obj.Name, weaponName) then
            return obj, "exact"
        end
    end
    if root:IsA("Tool") and NameEq(root.Name, weaponName) then
        return root, "exact"
    end
    local upper = string.gsub(string.gsub(string.upper(weaponName), " ", ""), "_", "")
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("Tool") then
            local oname = string.gsub(string.gsub(string.upper(obj.Name), " ", ""), "_", "")
            if oname:find(upper, 1, true) or upper:find(oname, 1, true) then
                return obj, "fuzzy"
            end
        end
    end
    return nil, nil
end

local function CollectToolNames(root, names)
    if not root then return names end
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("Tool") then
            names[obj.Name] = (names[obj.Name] or 0) + 1
        end
    end
    if root:IsA("Tool") then names[root.Name] = (names[root.Name] or 0) + 1 end
    return names
end

local function DumpAvailableTools()
    local found = {}
    for _, root in ipairs({ ReplicatedStorage, LocalPlayer:FindFirstChild("Backpack"), LocalPlayer.Character }) do
        CollectToolNames(root, found)
    end
    local list = {}
    for name in pairs(found) do table.insert(list, name) end
    table.sort(list)
    if #list == 0 then
        warn("[刷武器] 未在 ReplicatedStorage/背包/角色中找到任何 Tool 实例")
    else
        print("[刷武器] 当前游戏真实存在的 Tool:", table.concat(list, ", "))
    end
    return list
end

local function GiveWeapon(weaponName)
    if not LocalPlayer or not weaponName then return nil end
    if not LocalPlayer.Character then
        warn("[刷武器] 玩家角色不存在，无法装备")
        return nil
    end
    local mapped = WEAPON_NAME_MAP[weaponName]
    local target = mapped or MatchWeapon(weaponName) or weaponName
    local candidates = { ReplicatedStorage }
    for _, sub in ipairs({ "Tools", "Weapons", "Items", "Guns", "Equipment" }) do
        local c = ReplicatedStorage:FindFirstChild(sub)
        if c then table.insert(candidates, c) end
    end
    local starterPack = game:GetService("StarterPack")
    if starterPack then table.insert(candidates, starterPack) end
    local sourceTool, matchKey = nil, nil
    for _, root in ipairs(candidates) do
        sourceTool, matchKey = FindToolRecursive(root, target)
        if sourceTool then break end
    end
    if not sourceTool then
        sourceTool, matchKey = FindToolRecursive(Workspace, target)
    end
    if not sourceTool then
        warn(string.format("[刷武器] 未找到武器 \"%s\"。已知武器: %s", target, table.concat(ALL_WEAPON_NAMES, ", ")))
        DumpAvailableTools()
        return nil
    end
    local backpack = LocalPlayer:FindFirstChild("Backpack")
    local cloned = sourceTool:Clone()
    if backpack then
        cloned.Parent = backpack
    else
        cloned.Parent = LocalPlayer.Character
    end
    local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    local equipped = false
    if humanoid then
        equipped = pcall(function()
            humanoid:Equip(cloned)
            return true
        end)
    end
    local hasScript = cloned:FindFirstChildOfClass("LocalScript") ~= nil or cloned:FindFirstChild("Script") ~= nil
    local handle = cloned:FindFirstChild("Handle")
    local toolInfo = string.format("[刷武器] 已发放并装备: %s (来源名: %s, %s)", target, sourceTool.Name, matchKey)
    if not hasScript then
        toolInfo = toolInfo .. " | 此工具克隆后不含本地脚本，可能无法开火/挥砍（游戏可能改用远程事件或购买机制发武器）"
    end
    if not handle then
        toolInfo = toolInfo .. " | 无 Handle 部件"
    end
    print(toolInfo)
    return cloned
end

local PlayedKill = {}
local KillSound = Instance.new("Sound")
KillSound.Name = "KillDing"
KillSound.SoundId = "rbxasset://sounds/click.wav"
KillSound.Volume = 0.8
KillSound.SoundGroup = nil

local function PlayKillDing()
    local s = KillSound:Clone()
    s.Parent = Workspace
    s.Pitch = 1.6 + math.random() * 0.4
    s:Play()
    task.delay(1.2, function()
        s:Destroy()
    end)
    return s
end

local function FindHeadRecursive(model)
    if not model then return nil end
    local direct = model:FindFirstChild("Head")
    if direct and (direct:IsA("BasePart")) then
        return direct
    end
    local found = nil
    local function search(obj)
        if found then return end
        for _, child in ipairs(obj:GetChildren()) do
            if child.Name == "Head" and child:IsA("BasePart") then
                found = child
                return
            elseif child:IsA("Model") then
                search(child)
            end
        end
    end
    search(model)
    return found
end

local function SpawnLaser(target)
    local tool = GetHeldTool()
    local originPart = nil
    if tool then
        originPart = tool:FindFirstChildWhichIsA("BasePart")
    end
    if not originPart then
        originPart = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    end
    local endPart = target and (target:FindFirstChild("Head") or target:FindFirstChild("HumanoidRootPart") or target:FindFirstChildWhichIsA("BasePart"))
    if not originPart or not endPart then return end
    local endAtt = Instance.new("Attachment")
    endAtt.Name = "LaserEnd"
    endAtt.Position = Vector3.new(0, 0.5, 0)
    endAtt.Parent = endPart
    local beam = Instance.new("Beam")
    beam.Name = "KillLaser"
    beam.Attachment0 = originPart.Attachment0 or (function()
        local a = Instance.new("Attachment")
        a.Parent = originPart
        return a
    end)()
    beam.Attachment1 = endAtt
    beam.Color = ColorSequence.new(Color3.fromRGB(80, 255, 160))
    beam.Width0 = 0.06
    beam.Width1 = 0.02
    beam.LightEmission = 1
    beam.LightInfluence = 0
    beam.Transparency = NumberSequence.new(0.2)
    beam.FaceCamera = false
    beam.Parent = Workspace
    for i = 1, 10 do
        task.wait(0.1)
        local t = i / 10
        beam.Transparency = NumberSequence.new(0.2 + 0.8 * t)
    end
    beam:Destroy()
    endAtt:Destroy()
end

local function TriggerKillFX(target)
    if target and not PlayedKill[target] then
        PlayedKill[target] = true
        task.spawn(function()
            if target and target.Parent then
                SpawnLaser(target)
            end
            PlayKillDing()
        end)
    end
end

local IsKilling = false
local SkipCustomers = false
local RemoveCorpses = false

local function GetHitPosition(target)
    local head = target:FindFirstChild("Head")
    local hrp = target:FindFirstChild("HumanoidRootPart")
    local primary = target.PrimaryPart
    if head then
        return head.Position, head.CFrame.LookVector * -1
    elseif hrp then
        return hrp.Position, hrp.CFrame.LookVector * -1
    elseif primary then
        return primary.Position, Vector3.new(0, 1, 0)
    else
        for _, v in ipairs(target:GetDescendants()) do
            if v:IsA("BasePart") then
                return v.Position, Vector3.new(0, 1, 0)
            end
        end
    end
    return Vector3.new(0, 0, 0), Vector3.new(0, 1, 0)
end

local function KillTarget(target, weaponType, weaponName)
    if not target or not target.Parent then return end
    local humanoid = target:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return end
    local hitPart = target:FindFirstChild("Head")
        or target:FindFirstChild("HumanoidRootPart")
        or target:FindFirstChildWhichIsA("BasePart")
    local pos, normal = GetHitPosition(target)
    if weaponType == "Melee" then
        local args = { hitPart, pos, normal, CONFIG.Damage, weaponName }
        pcall(function()
            MeleeHitEvent:FireServer(unpack(args))
        end)
    elseif weaponType == "Gun" then
        if not GunHitEvent then return end
        local args = { hitPart, pos, normal, CONFIG.Damage, weaponName }
        pcall(function()
            GunHitEvent:FireServer(unpack(args))
        end)
    end
end

local function StartKillLoop()
    if IsKilling then return end
    IsKilling = true
    task.spawn(function()
        while IsKilling do
            local weaponName, weaponType, weaponLabel = GetHeldWeaponInfo()
            if weaponType == "Melee" or weaponType == "Gun" then
                for i = #NPCTags.Enemy, 1, -1 do
                    local npc = NPCTags.Enemy[i]
                    if npc and npc.Parent then
                        local hum = npc:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health > 0 then
                            KillTarget(npc, weaponType, weaponName)
                        else
                            TriggerKillFX(npc)
                            if RemoveCorpses then
                                local corpse = npc
                                task.delay(5, function()
                                    if corpse and corpse.Parent then
                                        pcall(function() corpse:Destroy() end)
                                    end
                                end)
                            end
                            table.remove(NPCTags.Enemy, i)
                        end
                    else
                        table.remove(NPCTags.Enemy, i)
                    end
                end
                if not SkipCustomers then
                    for i = #NPCTags.Customer, 1, -1 do
                        local npc = NPCTags.Customer[i]
                        if npc and npc.Parent then
                            local hum = npc:FindFirstChildOfClass("Humanoid")
                            if hum and hum.Health > 0 then
                                KillTarget(npc, weaponType, weaponName)
                            else
                                TriggerKillFX(npc)
                                if CustomersDeadFolder then
                                    pcall(function()
                                        npc.Parent = CustomersDeadFolder
                                    end)
                                end
                                if RemoveCorpses then
                                    local corpse = npc
                                    task.delay(5, function()
                                        if corpse and corpse.Parent then
                                            pcall(function() corpse:Destroy() end)
                                        end
                                    end)
                                end
                                table.remove(NPCTags.Customer, i)
                            end
                        else
                            table.remove(NPCTags.Customer, i)
                        end
                    end
                end
            end
            task.wait(CONFIG.KillInterval)
        end
    end)
end

local function StopKillLoop()
    IsKilling = false
end

local ESP_Overlay = nil
local ESP_Elements = {}
local ESP_OUTLINE = Color3.fromRGB(135, 186, 255)
local ESP_FILL = Color3.fromRGB(255, 200, 210)
local ESP_FILL_A = 0.7
local ESP_LABEL_HEIGHT = 16
local ESP_COLORS = {
    customer = Color3.fromRGB(88, 220, 140),
    rat = Color3.fromRGB(176, 118, 64),
    enemy = Color3.fromRGB(235, 95, 110),
    cop = Color3.fromRGB(96, 165, 255),
}
local ESP_LABELS = {
    customer = "顾客",
    rat = "老鼠",
    enemy = "敌人",
    cop = "警察",
}

local function ESP_GetRoot(model)
    local head = model:FindFirstChild("Head")
    if head then return head end
    local hrp = model:FindFirstChild("HumanoidRootPart")
    if hrp then return hrp end
    for _, v in ipairs(model:GetDescendants()) do
        if v:IsA("BasePart") then
            return v
        end
    end
    return nil
end

local function ESP_ShouldDraw(kind)
    return ESP_Enabled
end

local function ESP_Start()
    if ESP_Overlay and ESP_Overlay.Parent then return end
    local RunService = game:GetService("RunService")
    local lp = Players.LocalPlayer
    if not lp then return end
    ESP_Overlay = Instance.new("ScreenGui")
    ESP_Overlay.Name = "SpatulaESPGui"
    ESP_Overlay.ResetOnSpawn = false
    ESP_Overlay.DisplayOrder = 200
    ESP_Overlay.Parent = lp:WaitForChild("PlayerGui")
    local function EnsureHighlight(model)
        local el = ESP_Elements[model]
        if el and el.hl and el.hl.Parent and el.label and el.label.Parent then
            return el
        end
        local hl = el and el.hl or Instance.new("Highlight")
        hl.FillColor = ESP_FILL
        hl.FillTransparency = 1 - ESP_FILL_A
        hl.OutlineColor = ESP_OUTLINE
        hl.OutlineTransparency = 0
        hl.Enabled = false
        if not hl.Parent then
            hl.Parent = Workspace
        end
        local label = el and el.label or Instance.new("TextLabel")
        label.Size = UDim2.new(0, 200, 0, ESP_LABEL_HEIGHT)
        label.BackgroundTransparency = 1
        label.BorderSizePixel = 0
        label.Text = ""
        label.TextSize = 12
        label.Font = Enum.Font.GothamBold
        label.TextColor3 = Color3.fromRGB(255, 255, 255)
        label.TextXAlignment = Enum.TextXAlignment.Center
        label.Visible = false
        label.Parent = ESP_Overlay
        label.ZIndex = 3
        el = { hl = hl, label = label }
        ESP_Elements[model] = el
        return el
    end
    local function ComputeBounds(model, camera, viewport)
        local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
        local headTop = nil
        local parts = {}
        for _, part in ipairs(model:GetDescendants()) do
            if part:IsA("BasePart") and part.Parent then
                local world = part.CFrame and part.CFrame.Position
                if world then
                    local sp = camera:WorldToScreenPoint(world)
                    if sp.Z > 0 then
                        local px, py = sp.X, sp.Y
                        if px >= -200 and px <= viewport.X + 200 and py >= -200 and py <= viewport.Y + 200 then
                            parts[#parts + 1] = { part = part, x = px, y = py }
                            if px < minX then minX = px end
                            if py < minY then minY = py end
                            if px > maxX then maxX = px end
                            if py > maxY then maxY = py end
                            if not headTop or py < headTop.Y then
                                headTop = Vector2.new(px, py)
                            end
                        end
                    end
                end
            end
        end
        if #parts == 0 or minX > maxX or minY > maxY then return nil end
        return { parts = parts, minX = minX, minY = minY, maxX = maxX, maxY = maxY, headTop = headTop }
    end
    local function HideBox(el)
        if not el then return end
        if el.hl then
            el.hl.Enabled = false
        end
        if el.label then el.label.Visible = false end
    end
    task.spawn(function()
        local camera = Workspace.CurrentCamera
        while ESP_Overlay and ESP_Overlay.Parent do
            if not camera then
                camera = Workspace.CurrentCamera
            end
            if camera then
                local viewport = camera.ViewportSize
                local used = {}
                local targets = {}
                for _, m in ipairs(NPCTags.Customer) do
                    if m and m.Parent then targets[m] = "customer" end
                end
                for _, m in ipairs(NPCTags.Enemy) do
                    if m and m.Parent then
                        local kind = ClassifyNPC(m)
                        if kind == "customer" then targets[m] = "customer"
                        elseif kind == "rat" then targets[m] = "rat"
                        elseif kind == "cop" then targets[m] = "cop"
                        else targets[m] = "enemy" end
                    end
                end
                for model, kind in pairs(targets) do
                    used[model] = true
                    if ESP_ShouldDraw(kind) then
                        local b = ComputeBounds(model, camera, viewport)
                        if b then
                            local el = EnsureHighlight(model)
                            local col = ESP_COLORS[kind]
                            el.hl.Adornee = model
                            el.hl.Enabled = true
                            local topY = b.headTop and b.headTop.Y or b.minY
                            local centerX = b.minX + (b.maxX - b.minX) / 2
                            el.label.Text = ESP_LABELS[kind]
                            el.label.TextColor3 = col
                            el.label.Position = UDim2.new(0, centerX - 100, 0, topY - ESP_LABEL_HEIGHT - 8)
                            el.label.Visible = true
                        else
                            HideBox(ESP_Elements[model])
                        end
                    else
                        HideBox(ESP_Elements[model])
                    end
                end
                for model, el in pairs(ESP_Elements) do
                    if not used[model] then
                        HideBox(el)
                    end
                end
            end
            RunService.RenderStepped:Wait()
        end
    end)
end

