    ["犯罪大亨"] = [==[
-- ==================== WX HUB 彩虹界面（冰冷黄昏同款） ====================
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local WindUI = loadstring(game:HttpGet("https://raw.githubusercontent.com/Footagesus/WindUI/main/dist/main.lua"))()
local MarketplaceService = game:GetService("MarketplaceService")
local RunService = game:GetService("RunService")

local function getPlaceName()
    local ok, info = pcall(function() return MarketplaceService:GetProductInfo(game.PlaceId) end)
    return (ok and info and info.Name) or game.Name
end
local placeName = getPlaceName()

local function hsvToRgb(h, s, v)
    local r, g, b
    local i = math.floor(h / 60) % 6
    local f = (h / 60) - math.floor(h / 60)
    local p = v * (1 - s)
    local q = v * (1 - f * s)
    local t = v * (1 - (1 - f) * s)
    if i == 0 then r, g, b = v, t, p
    elseif i == 1 then r, g, b = q, v, p
    elseif i == 2 then r, g, b = p, v, t
    elseif i == 3 then r, g, b = p, q, v
    elseif i == 4 then r, g, b = t, p, v
    else r, g, b = v, p, q end
    return Color3.new(r, g, b)
end

local function makeRainbowColor(timeOffset, saturation, value)
    saturation = saturation or 1; value = value or 1
    local hue = (tick() * 60 + (timeOffset or 0)) % 360
    return hsvToRgb(hue, saturation, value)
end

local function makeRainbowColorSequence(timeOffset, saturation, value, count)
    saturation = saturation or 1; value = value or 1; count = count or 6
    local hueOffset = (tick() * 60 + (timeOffset or 0)) % 360
    local keypoints = {}
    for i = 0, count - 1 do
        local hue = (hueOffset + (i / count) * 360) % 360
        keypoints[i + 1] = ColorSequenceKeypoint.new(i / (count - 1), hsvToRgb(hue, saturation, value))
    end
    return ColorSequence.new(keypoints)
end

local function gradient3(text, color1, color2, color3)
    local result = ""
    local chars = {}
    for uchar in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do table.insert(chars, uchar) end
    local length = #chars
    for i = 1, length do
        local t = (i - 1) / math.max(length - 1, 1)
        local r, g, b
        if t < 0.5 then
            local s = t * 2
            r = color1.R + (color2.R - color1.R) * s
            g = color1.G + (color2.G - color1.G) * s
            b = color1.B + (color2.B - color1.B) * s
        else
            local s = (t - 0.5) * 2
            r = color2.R + (color3.R - color2.R) * s
            g = color2.G + (color3.G - color2.G) * s
            b = color2.B + (color3.B - color2.B) * s
        end
        result = result .. string.format('<font color="rgb(%d,%d,%d)">%s</font>',
            math.floor(r * 255), math.floor(g * 255), math.floor(b * 255), chars[i])
    end
    return result
end

local titleColor1 = hsvToRgb(0, 1, 1)
local titleColor2 = hsvToRgb(120, 1, 1)
local titleColor3 = hsvToRgb(240, 1, 1)

local Window = WindUI:CreateWindow({
    Title = gradient3("WX HUB", titleColor1, titleColor2, titleColor3),
    Author = gradient3("犯罪大亨 | WX HUB", titleColor3, titleColor1, titleColor2),
    Icon = "wind",
    IconThemed = false,
    Folder = "WXHUB_KB",
    Size = UDim2.fromOffset(580, 420),
