local translatedCache = {}
local monsterNameCache = {}

local function translateText(text)
    if not text or text == "" or #text < 2 then
        return nil
    end
    if translatedCache[text] then
        return translatedCache[text]
    end
    local success, result = pcall(function()
        local url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=zh-CN&dt=t&q=" .. HttpService:UrlEncode(text)
        local response = game:HttpGet(url)
        local decoded = HttpService:JSONDecode(response)
        if decoded and decoded[1] and decoded[1][1] and decoded[1][1][1] then
            return decoded[1][1][1]
        end
        return nil
    end)
    if success and result then
        translatedCache[text] = result
        return result
    end
    return nil
end

local function getTranslatedName(enName)
    if not enName or enName == "" then
        return enName
    end
    if monsterNameCache[enName] then
        return monsterNameCache[enName]
    end
    local zh = translateText(enName)
    if zh then
        monsterNameCache[enName] = zh
        return zh
    end
    return enName
end

