    ["Second Chance"] = createSecondChance,
    ["God Mode"] = createGodMode,
}

local function getItem(itemName)
    local stolen = stealTool(itemName)
    if stolen then
        local clone = stolen:Clone()
        clone.Parent = player.Backpack
        return
    end
    local copied = copyTool(itemName)
    if copied then
        local clone = copied:Clone()
        clone.Parent = player.Backpack
        return
    end
    local creator = itemCreators[itemName]
    if creator then
        local tool = creator()
        tool.Parent = player.Backpack
        return
    end
    local basic = Instance.new("Tool")
    basic.Name = itemName
    basic.RequiresHandle = true
    local handle = Instance.new("Part")
    handle.Name = "Handle"
    handle.Size = Vector3.new(1, 1, 1)
    handle.CanCollide = false
    handle.Parent = basic
    basic.Parent = player.Backpack
end

local function buyItem(itemName)
    local hrp = getHRP()
    if not hrp then return end
    local shop = Workspace:FindFirstChild("shopTouchPrompts")
    if shop then
        for _, item in ipairs(shop:GetChildren()) do
            if item:IsA("BasePart") and item.Name == itemName and item:FindFirstChild("TouchInterest") then
                pcall(function()
                    firetouchinterest(hrp, item, 0)
                    firetouchinterest(hrp, item, 1)
                end)
                return
            end
        end
    end
    local vipGivers = Workspace:FindFirstChild("VIP Givers")
    if vipGivers then
        for _, item in ipairs(vipGivers:GetChildren()) do
            if item.Name == itemName and item:FindFirstChild("TouchInterest") then
                pcall(function()
                    firetouchinterest(hrp, item, 0)
                    firetouchinterest(hrp, item, 1)
                end)
                return
            end
        end
    end
end

local shop = Workspace:FindFirstChild("shopTouchPrompts")
local shopItems = {}
local shopItemMap = {}
if shop then
    for _, item in ipairs(shop:GetChildren()) do
        if item:IsA("BasePart") and item:FindFirstChild("TouchInterest") then
            local zhName = getTranslatedName(item.Name)
            table.insert(shopItems, zhName)
            shopItemMap[zhName] = item.Name
        end
    end
end

local selectedShopItems = {}

if #shopItems > 0 then
    ObtainLeft:AddDropdown("商店道具选择", {
        Values = shopItems,
        Default = 1,
        Multi = true,
        Text = "选择商店道具(可多选)",
        Callback = function(value)
            selectedShopItems = {}
            for k, v in pairs(value) do
                local zhName = nil
                if type(k) == "string" then
                    zhName = k
                elseif type(v) == "string" then
                    zhName = v
                end
                if zhName and shopItemMap[zhName] then
                    table.insert(selectedShopItems, shopItemMap[zhName])
                end
            end
        end
    })
else
    ObtainLeft:AddLabel("未找到商店道具")
end

ObtainLeft:AddButton("购买选中道具", function()
    local hrp = getHRP()
    if not hrp or not shop then return end
    if #selectedShopItems == 0 then return end
    for _, enName in ipairs(selectedShopItems) do
        for _, item in ipairs(shop:GetChildren()) do
            if item:IsA("BasePart") and item.Name == enName and item:FindFirstChild("TouchInterest") then
                pcall(function()
                    firetouchinterest(hrp, item, 0)
                    firetouchinterest(hrp, item, 1)
                end)
            end
        end
    end
    selectedShopItems = {}
    pcall(function()
        Options["商店道具选择"]:SetValue({})
    end)
end)

ObtainLeft:AddButton("免费获取选中道具", function()
    if #selectedShopItems == 0 then return end
    for _, enName in ipairs(selectedShopItems) do
        getItem(enName)
    end
    selectedShopItems = {}
    pcall(function()
        Options["商店道具选择"]:SetValue({})
    end)
end)

