local VipGroup = Tabs.VIP:AddLeftGroupbox("VIP")

local function setVipState(state)
    states.vipEnabled = state
    local char = player.Character
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end
    if state then
        if not head:FindFirstChild("WXHUB_VIP") then
            local vipGui = Instance.new("BillboardGui")
            vipGui.Name = "WXHUB_VIP"
            vipGui.Size = UDim2.new(0, 120, 0, 50)
            vipGui.StudsOffset = Vector3.new(0, 2.8, 0)
            vipGui.AlwaysOnTop = false
            local textLabel = Instance.new("TextLabel")
            textLabel.Name = "PlayerName"
            textLabel.Size = UDim2.new(1, 0, 1, 0)
            textLabel.BackgroundTransparency = 1
            textLabel.Text = "VIP"
            textLabel.TextColor3 = Color3.fromRGB(255, 215, 0)
            textLabel.TextStrokeTransparency = 0
            textLabel.TextScaled = true
            textLabel.Font = Enum.Font.GothamBold
            textLabel.Parent = vipGui
            local gradient = Instance.new("UIGradient")
            gradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 215, 0)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 140, 0))
            })
            gradient.Parent = textLabel
            vipGui.Parent = head
        end
        local vipDoor = workspace:FindFirstChild("VIP Door")
        if vipDoor then
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                pcall(function()
                    firetouchinterest(hrp, vipDoor, 0)
                    task.wait(0.1)
                    firetouchinterest(hrp, vipDoor, 1)
                end)
            end
        end
        Library:Notify("VIP已开启", 3)
    else
        local vipGui = head:FindFirstChild("WXHUB_VIP")
        if vipGui then
            vipGui:Destroy()
        end
        Library:Notify("VIP已关闭", 3)
    end
end

