local monsterBillboards = {}

local function clearESP()
    for _, bb in ipairs(monsterBillboards) do
        pcall(function() bb:Destroy() end)
    end
    monsterBillboards = {}
end

local function updateESP()
    local hrp = getHRP()
    if not hrp then return end
    for _, obj in ipairs(Workspace:GetDescendants()) do
        if obj:IsA("Humanoid") and obj.Parent then
            local model = obj.Parent
            local isPlayer = false
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Character == model then
                    isPlayer = true
                    break
                end
            end
            if not isPlayer then
                local head = model:FindFirstChild("Head") or model:FindFirstChildWhichIsA("BasePart")
                if head then
                    local bb = head:FindFirstChild("WXHUB_ESP")
                    if not bb then
                        bb = Instance.new("BillboardGui")
                        bb.Name = "WXHUB_ESP"
                        bb.Size = UDim2.new(0, 120, 0, 40)
                        bb.AlwaysOnTop = true
                        bb.StudsOffset = Vector3.new(0, 3, 0)
                        bb.Parent = player.PlayerGui
                        bb.Adornee = head
                        local tl = Instance.new("TextLabel")
                        tl.Size = UDim2.new(1, 0, 1, 0)
                        tl.BackgroundTransparency = 1
                        tl.TextColor3 = Color3.fromRGB(255, 0, 0)
                        tl.Font = Enum.Font.GothamBold
                        tl.TextSize = 12
                        tl.Parent = bb
                        table.insert(monsterBillboards, bb)
                    end
                    local dist = math.floor((hrp.Position - head.Position).Magnitude)
                    local tl = bb:FindFirstChildOfClass("TextLabel")
                    if tl then
                        local displayName = getTranslatedName(model.Name)
                        tl.Text = displayName .. "\n" .. dist .. "m"
                    end
                end
            end
        end
    end
end

