local function clearGodMode()
    if states.godSpamThread then
        pcall(function() task.cancel(states.godSpamThread) end)
        states.godSpamThread = nil
    end
    if states.godCharConn then
        pcall(function() states.godCharConn:Disconnect() end)
        states.godCharConn = nil
    end
end

local function findGodMode()
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player then
            local bp = plr:FindFirstChild("Backpack")
            if bp then
                for _, t in ipairs(bp:GetChildren()) do
                    if t:IsA("Tool") and t.Name == "God Mode" then
                        return t
                    end
                end
            end
            if plr.Character then
                for _, t in ipairs(plr.Character:GetChildren()) do
                    if t:IsA("Tool") and t.Name == "God Mode" then
                        return t
                    end
                end
            end
        end
    end
    return nil
end

local function createFakeGodMode()
    local tool = Instance.new("Tool")
    tool.Name = "God Mode"
    tool.RequiresHandle = true
    tool.CanBeDropped = false
    local handle = Instance.new("MeshPart")
    handle.Name = "Handle"
    handle.Size = Vector3.new(1, 1, 1)
    handle.CanCollide = false
    handle.Transparency = 1
    handle.Parent = tool
    local re = Instance.new("RemoteEvent")
    re.Name = "Replication"
    re.Parent = tool
    local funcs = Instance.new("ModuleScript")
    funcs.Name = "Functions"
    funcs.Source = "return {}"
    funcs.Parent = tool
    local ls = Instance.new("LocalScript")
    ls.Name = "LocalScript"
    ls.Parent = tool
    local theme = Instance.new("Sound")
    theme.Name = "Theme"
    theme.Parent = ls
    local anims = Instance.new("Folder")
    anims.Name = "Animations"
    anims.Parent = ls
    local a1 = Instance.new("Animation")
    a1.Name = "activate"
    a1.Parent = anims
    local a2 = Instance.new("Animation")
    a2.Name = "cast"
    a2.Parent = anims
    local a3 = Instance.new("Animation")
    a3.Name = "idle"
    a3.Parent = anims
    return tool
end

local function applyGodMode(char)
    local hum = char:WaitForChild("Humanoid", 3)
    if not hum then return end
    local ff = char:FindFirstChild("WXHUB_GodMode")
    if not ff then
        ff = Instance.new("ForceField")
        ff.Name = "WXHUB_GodMode"
        ff.Parent = char
    end
    local tool = findGodMode()
    if tool then
        tool = tool:Clone()
    else
        tool = createFakeGodMode()
    end
    tool.Parent = player.Backpack
    task.wait(0.1)
    pcall(function() hum:EquipTool(tool) end)
    local re = tool:FindFirstChild("Replication")
    if re then
        for i = 1, 5 do
            pcall(function() re:FireServer() end)
        end
    end
    states.godSpamThread = task.spawn(function()
        while states.permanentGod do
            pcall(function()
                if tool and tool.Parent then
                    if re then re:FireServer() end
                    tool:Activate()
                end
            end)
            task.wait(0.15)
        end
    end)
    pcall(function()
        tool.Unequipped:Connect(function()
            if states.permanentGod then
                task.wait(0.1)
                pcall(function() hum:EquipTool(tool) end)
            end
        end)
    end)
    hum.HealthChanged:Connect(function()
        if states.permanentGod then
            hum.Health = hum.MaxHealth
        end
    end)
end

GodGroup:AddToggle("永久无敌", {
    Text = "永久无敌护盾(God Mode)",
