                    local function loadArea(position, radius)
                        if RunService:IsClient() then
                            pcall(function()
                                Network.InvokeServer("requestStreamAround", position, radius)
                            end)
                            pcall(function()
                                Network.FireServer("setReplicationFocus", position)
