local KICK_REASON = "你所执行的这个脚本不在这个服务器的使用范围内，所以被踢出"

local function CheckPlaceId(ids)
    if type(ids) == "table" then return ids[game.PlaceId] == true end
    return ids == game.PlaceId
end

local function ExecuteGame(gameName)
    local src = GameScripts[gameName]
    if not src then return end
    local fn = loadstring(src)
    if fn then task.spawn(fn) end
end

-- ==================== 统一关闭加载器/游戏列表 UI ====================
local LoaderUIRefs = { screenGui = nil, mainContainer = nil, background = nil, closed = false }

local function CloseMainUI(instant)
    if LoaderUIRefs.closed then return end
    LoaderUIRefs.closed = true
    local sg = LoaderUIRefs.screenGui
    local mc = LoaderUIRefs.mainContainer
    local bg = LoaderUIRefs.background
    local function destroySG()
        if sg and sg.Parent then sg:Destroy() end
    end
    if instant then
        destroySG()
        return
    end
    if mc and mc.Parent then
        local closeInfo = TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In)
        local scaleTween = TweenService:Create(mc, closeInfo, {
            Size = UDim2.new(0, 0, 0, 0),
            Position = UDim2.new(0.5, 0, 0.5, 0)
        })
        scaleTween:Play()
        if bg and bg.Parent then
            TweenService:Create(bg, closeInfo, { BackgroundTransparency = 1 }):Play()
        end
        scaleTween.Completed:Connect(destroySG)
        task.delay(0.6, destroySG)
    else
        destroySG()
    end
end
