local function ShowSmartDetection()
    local matchedName = nil
    for name, ids in pairs(GameIds) do
        if CheckPlaceId(ids) then matchedName = name break end
    end
    if not matchedName then return end

    local sg = Instance.new("ScreenGui")
    sg.Name = "WXHUB_SmartDetect"
