    info.TextColor3 = Color3.fromRGB(220, 230, 255)
    info.TextSize = 15
    info.Font = Enum.Font.GothamMedium
    info.TextWrapped = true
    info.Parent = card

    local runBtn = Instance.new("TextButton")
    runBtn.Size = UDim2.new(0.5, -22, 0, 36)
    runBtn.Position = UDim2.new(0, 15, 1, -50)
    runBtn.BackgroundColor3 = Color3.fromRGB(53, 74, 115)
    runBtn.Text = "立即执行"
    runBtn.TextColor3 = Color3.fromRGB(150, 190, 255)
    runBtn.TextSize = 15
    runBtn.Font = Enum.Font.GothamBold
    runBtn.Parent = card
    local rc = Instance.new("UICorner") rc.CornerRadius = UDim.new(0, 10) rc.Parent = runBtn

    local cancelBtn = Instance.new("TextButton")
    cancelBtn.Size = UDim2.new(0.5, -22, 0, 36)
    cancelBtn.Position = UDim2.new(0.5, 7, 1, -50)
    cancelBtn.BackgroundColor3 = Color3.fromRGB(45, 45, 60)
    cancelBtn.Text = "取消"
    cancelBtn.TextColor3 = Color3.fromRGB(200, 205, 220)
    cancelBtn.TextSize = 15
    cancelBtn.Font = Enum.Font.GothamBold
    cancelBtn.Parent = card
    local cc = Instance.new("UICorner") cc.CornerRadius = UDim.new(0, 10) cc.Parent = cancelBtn

    card.Size = UDim2.new(0, 0, 0, 0)
    card:TweenSize(UDim2.new(0, 340, 0, 180), "Out", "Back", 0.35, true)

    local smartFired = false
    local function handleSmartRun()
        if smartFired then return end
        smartFired = true
        sg:Destroy()
        CloseMainUI(false)
        task.wait(0.2)
        ExecuteGame(matchedName)
    end
    runBtn.MouseButton1Click:Connect(handleSmartRun)
    runBtn.Activated:Connect(handleSmartRun)
    local smartClosed = false
    local function handleSmartCancel()
        if smartClosed then return end
        smartClosed = true
        sg:Destroy()
    end
    cancelBtn.MouseButton1Click:Connect(handleSmartCancel)
    cancelBtn.Activated:Connect(handleSmartCancel)
end

